  ('french-a2-practical-1', 'french-a2-practical-1-010-oui-merci-je-connais-deja-un-peu-le-quartier', 10, 'bright', 'French', 'fr-FR', 'German', 'Oui, merci, je connais déjà un peu le quartier.', '{"English":"Yes, thank you, I already know the neighbourhood a little.","German":"Ja, danke, ich kenne das Viertel schon ein wenig."}', 'f793f8c53b804f9ac15dba5d66fda2bd641667d988dcb2fb69ee244e2253852a'),
  ('french-a2-practical-10', 'french-a2-practical-10-091-je-viens-dallemagne-et-jhabite-maintenant-pres-du-jardin', 1, 'bright', 'French', 'fr-FR', 'German', 'Je viens d''Allemagne et j''habite maintenant près du jardin.', '{"English":"I come from Germany and now live near the garden.","German":"Ich komme aus Deutschland und wohne jetzt nahe dem Park."}', '88f740f7b93045c5e23b200e4e1fb6844a76bccf5c50e9a4bc651c50db28d040'),
  ('french-a2-practical-10', 'french-a2-practical-10-092-je-travaille-dans-un-bureau-au-centre-pres-de-la-gare', 2, 'bright', 'French', 'fr-FR', 'German', 'Je travaille dans un bureau au centre, près de la gare.', '{"English":"I work in an office in the centre, near the station.","German":"Ich arbeite in einem Büro im Zentrum, nahe dem Bahnhof."}', '65d3cd902446a8daa7fbd243d804f7d750752250f8a5738d50837b5acacbc4c4'),
  ('french-a2-practical-10', 'french-a2-practical-10-093-japprends-le-francais-parce-que-je-travaille-avec-des-clients', 3, 'bright', 'French', 'fr-FR', 'German', 'J''apprends le français parce que je travaille avec des clients.', '{"English":"I am learning French because I work with clients.","German":"Ich lerne Französisch, weil ich mit Kunden arbeite."}', 'de5ddef3ad0425c45e6daef4ffa9e6afbef29d8fe996181b13febb456b844df3'),
  ('french-a2-practical-10', 'french-a2-practical-10-094-je-suis-ici-depuis-deux-semaines', 4, 'bright', 'French', 'fr-FR', 'German', 'Je suis ici depuis deux semaines.', '{"English":"I have been here for two weeks.","German":"Ich bin seit zwei Wochen hier."}', 'dbf8edba923efb0d2059e9f9e7f53a0c445a8110071a60550dca694f03c07469'),
  ('french-a2-practical-10', 'french-a2-practical-10-095-ma-famille-est-en-allemagne-je-lappelle-chaque-semaine', 5, 'bright', 'French', 'fr-FR', 'German', 'Ma famille est en Allemagne, je l''appelle chaque semaine.', '{"English":"My family is in Germany; I call them every week.","German":"Meine Familie ist in Deutschland, ich rufe sie jede Woche an."}', '79e0f1339627809b1ae08bdbe46c84ad40c7636821815977302b2d5408e3a73f'),
  ('french-a2-practical-10', 'french-a2-practical-10-096-je-cuisine-et-je-me-promene-dans-le-quartier', 6, 'bright', 'French', 'fr-FR', 'German', 'Je cuisine et je me promène dans le quartier.', '{"English":"I cook and walk around the neighbourhood.","German":"Ich koche und gehe im Viertel spazieren."}', '9622935be702719610111c4fb7960402a55a50f9e6305b953fa333f55426945e'),
  ('french-a2-practical-10', 'french-a2-practical-10-097-le-matin-je-travaille-et-le-soir-jetudie-le-francais', 7, 'bright', 'French', 'fr-FR', 'German', 'Le matin, je travaille et le soir, j''étudie le français.', '{"English":"In the morning I work, and in the evening I study French.","German":"Morgens arbeite ich und abends lerne ich Französisch."}', 'ae9e1a2b6ba3c051337037d7b245f7781cdc475b0b895d4ce12c69ff0fa03990'),
  ('french-a2-practical-10', 'french-a2-practical-10-098-je-comprends-presque-tout-mais-je-parle-encore-lentement', 8, 'bright', 'French', 'fr-FR', 'German', 'Je comprends presque tout, mais je parle encore lentement.', '{"English":"I understand almost everything, but I still speak slowly.","German":"Ich verstehe fast alles, aber ich spreche noch langsam."}', '6c03c5c667d5b1337683d79500e7ed5b870a0856bda60b6b46cbce01e046359c'),
  ('french-a2-practical-10', 'french-a2-practical-10-099-lannee-prochaine-je-vais-revenir-ici-pour-travailler', 9, 'bright', 'French', 'fr-FR', 'German', 'L''année prochaine, je vais revenir ici pour travailler.', '{"English":"Next year, I am going to come back here to work.","German":"Nächstes Jahr werde ich zum Arbeiten hierher zurückkommen."}', '9d918e6ba6a1fc9aa23736ec7202f8678341901ecb27bb0b983bcdcd7370bc8e'),
  ('french-a2-practical-10', 'french-a2-practical-10-100-jai-fait-beaucoup-de-progres-merci-pour-ces-deux-semaines-a-tres-vite', 10, 'bright', 'French', 'fr-FR', 'German', 'J''ai fait beaucoup de progrès. Merci pour ces deux semaines, à très vite !', '{"English":"I have made a lot of progress. Thank you for these two weeks; see you very soon!","German":"Ich habe große Fortschritte gemacht. Danke für diese zwei Wochen, bis ganz bald!"}', '606031f0bd92d97523d6a63a9e3cc560237b701388c7757f6d2406502d5bcfe3'),
  ('french-a2-practical-2', 'french-a2-practical-2-011-je-prends-ces-tomates-parce-quelles-sont-plus-mures', 1, 'bright', 'French', 'fr-FR', 'German', 'Je prends ces tomates, parce qu''elles sont plus mûres.', '{"English":"I am taking these tomatoes because they are riper.","German":"Ich nehme diese Tomaten, weil sie reifer sind."}', 'be88bcd65a72185cb7c660557303ec95b5d8f5413ff4494fdf0b5d55d422f4b0'),
  ('french-a2-practical-2', 'french-a2-practical-2-012-aujourdhui-je-prends-un-jus-parce-quil-est-moins-fort-que-le-cafe', 2, 'bright', 'French', 'fr-FR', 'German', 'Aujourd''hui, je prends un jus, parce qu''il est moins fort que le café.', '{"English":"Today I am having a juice because it is less strong than the coffee.","German":"Heute nehme ich einen Saft, weil er weniger stark ist als der Kaffee."}', 'a998e0f79be5dc2af81f21745d8594105f7eed65d17da2cf09ce20ad43923edb'),
  ('french-a2-practical-2', 'french-a2-practical-2-013-je-prefere-la-chemise-bleue-elle-est-plus-grande-que-lautre', 3, 'bright', 'French', 'fr-FR', 'German', 'Je préfère la chemise bleue : elle est plus grande que l''autre.', '{"English":"I prefer the blue shirt: it is larger than the other one.","German":"Ich bevorzuge das blaue Hemd: Es ist größer als das andere."}', 'b1fdb177803a9980381d72dc950b171bac112f017d629276f423648b67caf3a1'),
  ('french-a2-practical-2', 'french-a2-practical-2-014-je-prends-la-salade-elle-est-plus-legere-que-la-soupe', 4, 'bright', 'French', 'fr-FR', 'German', 'Je prends la salade, elle est plus légère que la soupe.', '{"English":"I am having the salad; it is lighter than the soup.","German":"Ich nehme den Salat, er ist leichter als die Suppe."}', '2bd498111275ae43af61af4440f96e3709a0d7696716bebe6cc1e8fb095eec0d'),
  ('french-a2-practical-2', 'french-a2-practical-2-015-ce-pain-est-plus-frais-que-lautre-alors-je-le-prends', 5, 'bright', 'French', 'fr-FR', 'German', 'Ce pain est plus frais que l''autre, alors je le prends.', '{"English":"This bread is fresher than the other one, so I am taking it.","German":"Dieses Brot ist frischer als das andere, also nehme ich es."}', 'ad5f09dc0ecc0887a657dbe465fd0badbea7ccbe06a8cf83ceadd1ec1c603ff5'),
  ('french-a2-practical-2', 'french-a2-practical-2-016-je-prends-le-metro-il-est-plus-rapide-que-le-bus', 6, 'bright', 'French', 'fr-FR', 'German', 'Je prends le métro, il est plus rapide que le bus.', '{"English":"I am taking the metro; it is faster than the bus.","German":"Ich nehme die Metro, sie ist schneller als der Bus."}', 'b0c58d75fb2337b6f46ff020e61d2ebfb016450e0838aa478b47ec2769cdf9ea'),
  ('french-a2-practical-2', 'french-a2-practical-2-017-je-prefere-cette-chambre-elle-est-plus-calme-et-jy-dors-mieux', 7, 'bright', 'French', 'fr-FR', 'German', 'Je préfère cette chambre : elle est plus calme et j''y dors mieux.', '{"English":"I prefer this room: it is quieter and I sleep better there.","German":"Ich bevorzuge dieses Zimmer: Es ist ruhiger und ich schlafe dort besser."}', '775092385737b84f5a3d67b049c01cae3fc7713bb9afcb873ce8c4095f384ffa'),
  ('french-a2-practical-2', 'french-a2-practical-2-018-je-prends-ces-chaussures-elles-sont-plus-confortables-que-celles-la', 8, 'bright', 'French', 'fr-FR', 'German', 'Je prends ces chaussures, elles sont plus confortables que celles-là.', '{"English":"I am taking these shoes; they are more comfortable than those.","German":"Ich nehme diese Schuhe, sie sind bequemer als jene."}', 'dd52fb25ba042dd82d5ac1e1655a2b9a2e2fc3a63f8ca26632398c0c6900bb64'),
  ('french-a2-practical-2', 'french-a2-practical-2-019-je-prends-la-petite-bouteille-elle-coute-moins-cher', 9, 'bright', 'French', 'fr-FR', 'German', 'Je prends la petite bouteille, elle coûte moins cher.', '{"English":"I am taking the small bottle; it costs less.","German":"Ich nehme die kleine Flasche, sie kostet weniger."}', '7d3f5ca306e460d477cba3e2301b6586bd123ba88522612d1cdfb818dff140dd'),
  ('french-a2-practical-2', 'french-a2-practical-2-020-je-prefere-ce-cafe-parce-quil-est-pres-dici-et-calme', 10, 'bright', 'French', 'fr-FR', 'German', 'Je préfère ce café parce qu''il est près d''ici et calme.', '{"English":"I prefer this cafe because it is nearby and quiet.","German":"Ich bevorzuge dieses Café, weil es ganz in der Nähe liegt und ruhig ist."}', '5ed9209c1ae8f7c936c370097111747501db257fe3872c37cb0996c9dc821aa6'),
  ('french-a2-practical-3', 'french-a2-practical-3-021-jai-deja-paye-par-carte-a-la-caisse', 1, 'bright', 'French', 'fr-FR', 'German', 'J''ai déjà payé par carte à la caisse.', '{"English":"I have already paid by card at the checkout.","German":"Ich habe schon mit Karte an der Kasse bezahlt."}', '7f7d86ccaf38ce124094322bcb2ed3129df123a28f09c633e40a524b3694a620'),
  ('french-a2-practical-3', 'french-a2-practical-3-022-jai-pris-le-train-hier-soir', 2, 'bright', 'French', 'fr-FR', 'German', 'J''ai pris le train hier soir.', '{"English":"I took the train yesterday evening.","German":"Ich habe gestern Abend den Zug genommen."}', '1ce24e139dd8d26cef492316025e13e1e18cef7dc7abfa1b55fd5d5b69155e82'),
  ('french-a2-practical-3', 'french-a2-practical-3-023-jai-deja-commande-la-soupe-merci-beaucoup', 3, 'bright', 'French', 'fr-FR', 'German', 'J''ai déjà commandé la soupe, merci beaucoup.', '{"English":"I have already ordered the soup, thank you very much.","German":"Ich habe die Suppe schon bestellt, vielen Dank."}', 'c4f09bfeb59b47f51ea0038dbbf64792f7d5b7bf1e680abdf1271c5cc88fb231'),
  ('french-a2-practical-3', 'french-a2-practical-3-024-oui-jai-achete-de-bonnes-tomates-au-marche-aujourdhui', 4, 'bright', 'French', 'fr-FR', 'German', 'Oui, j''ai acheté de bonnes tomates au marché aujourd''hui.', '{"English":"Yes, I bought good tomatoes at the market today.","German":"Ja, ich habe heute auf dem Markt gute Tomaten gekauft."}', '950e3c26a2079f87e815f5ef0f21f08200702337266b56915332b6c07ac3ad2b'),
  ('french-a2-practical-3', 'french-a2-practical-3-025-ce-matin-jai-fait-le-marche-avant-le-travail', 5, 'bright', 'French', 'fr-FR', 'German', 'Ce matin, j''ai fait le marché avant le travail.', '{"English":"This morning I did the market shopping before work.","German":"Heute Morgen habe ich vor der Arbeit den Markteinkauf gemacht."}', '37cf88ea7ae336c338a8aaefbd73ef479030980860aed62b9c534686a395ad56'),
  ('french-a2-practical-3', 'french-a2-practical-3-026-jai-mal-dormi-hier-mais-ca-va-mieux', 6, 'bright', 'French', 'fr-FR', 'German', 'J''ai mal dormi hier, mais ça va mieux.', '{"English":"I slept badly yesterday, but things are better now.","German":"Ich habe gestern schlecht geschlafen, aber jetzt geht es besser."}', '08adf43ffa06848970d2c23b856b74e07e8eb87cc5a8501f977a4332054b85b3'),
  ('french-a2-practical-3', 'french-a2-practical-3-027-jai-deja-essaye-la-specialite-du-quartier', 7, 'bright', 'French', 'fr-FR', 'German', 'J''ai déjà essayé la spécialité du quartier.', '{"English":"I have already tried the neighbourhood speciality.","German":"Ich habe die Spezialität des Viertels schon probiert."}', 'bd235d309f661c58a37cc0ab4fe1712510b8c752501772875b7b53bba554d02f'),
  ('french-a2-practical-3', 'french-a2-practical-3-028-je-nai-pas-encore-vu-la-cathedrale', 8, 'bright', 'French', 'fr-FR', 'German', 'Je n''ai pas encore vu la cathédrale.', '{"English":"I have not seen the cathedral yet.","German":"Ich habe die Kathedrale noch nicht gesehen."}', '5e16807c31e1c878cfd63f974ddd95007444198a7994ba4d6020d07139a876c1'),
  ('french-a2-practical-3', 'french-a2-practical-3-029-jai-fini-tot-aujourdhui-et-je-suis-libre', 9, 'bright', 'French', 'fr-FR', 'German', 'J''ai fini tôt aujourd''hui et je suis libre.', '{"English":"I finished early today and am free.","German":"Ich bin heute früh fertig geworden und habe frei."}', '6f1e118dfe9898ab47a59f5cf8e89b388c732b76d50a1d6c7125866b56c34d08'),
  ('french-a2-practical-3', 'french-a2-practical-3-030-jai-fait-beaucoup-de-choses-cette-semaine', 10, 'bright', 'French', 'fr-FR', 'German', 'J''ai fait beaucoup de choses cette semaine.', '{"English":"I have done many things this week.","German":"Ich habe diese Woche viele Dinge gemacht."}', '42ba618731527260c575bd2c7c6a1449cc8507d52ad38ae7023c5700f5fc60b6'),
  ('french-a2-practical-4', 'french-a2-practical-4-031-oui-jeudi-a-dix-huit-heures-cest-parfait-pour-moi', 1, 'bright', 'French', 'fr-FR', 'German', 'Oui, jeudi à dix-huit heures, c''est parfait pour moi.', '{"English":"Yes, Thursday at six o’clock is perfect for me.","German":"Ja, Donnerstag um achtzehn Uhr ist perfekt für mich."}', '3fa0962e209a302ad3e2c8affc5f5d09e3bf26e4ef84f50cede3a78750accc14'),
  ('french-a2-practical-4', 'french-a2-practical-4-032-demain-je-vais-visiter-le-musee-avec-ma-soeur', 2, 'bright', 'French', 'fr-FR', 'German', 'Demain, je vais visiter le musée avec ma sœur.', '{"English":"Tomorrow I am going to visit the museum with my sister.","German":"Morgen werde ich mit meiner Schwester das Museum besuchen."}', '764ddd962b36927504ddadf88e743b327c5dce9cace11c2b26a984ca58080b42'),
  ('french-a2-practical-4', 'french-a2-practical-4-033-on-dit-vendredi-pour-aller-au-cinema', 3, 'bright', 'French', 'fr-FR', 'German', 'On dit vendredi pour aller au cinéma ?', '{"English":"Shall we say Friday to go to the cinema?","German":"Sagen wir Freitag, um ins Kino zu gehen?"}', 'a440b364917823aadd69e4d489179ed6dc16e96e3208c187c2280ee66116c4c3'),
  ('french-a2-practical-4', 'french-a2-practical-4-034-oui-a-huit-heures-devant-le-cinema-ca-vous-va', 4, 'bright', 'French', 'fr-FR', 'German', 'Oui, à huit heures devant le cinéma, ça vous va ?', '{"English":"Yes, at eight o’clock in front of the cinema, does that work for you?","German":"Ja, um acht Uhr vor dem Kino, passt Ihnen das?"}', 'a068e16311a4e7b663b37e1ef79a0774ffe496c3dd71813fdeee64d7073e7044'),
  ('french-a2-practical-4', 'french-a2-practical-4-035-samedi-me-convient-mieux-vous-etes-libre-lapres-midi', 5, 'bright', 'French', 'fr-FR', 'German', 'Samedi me convient mieux, vous êtes libre l''après-midi ?', '{"English":"Saturday suits me better; are you free in the afternoon?","German":"Samstag passt mir besser, haben Sie am Nachmittag frei?"}', '8ff49da782fad315d5d6923eea964634d1f20538c74808260d3323a34df5f263'),
  ('french-a2-practical-4', 'french-a2-practical-4-036-je-ne-peux-pas-ce-soir-jai-beaucoup-de-travail', 6, 'bright', 'French', 'fr-FR', 'German', 'Je ne peux pas ce soir, j''ai beaucoup de travail.', '{"English":"I cannot this evening; I have a lot of work.","German":"Ich kann heute Abend nicht, ich habe viel Arbeit."}', '228bbbd927bfe8426981a1bd48a25c2170b044c211f3a9bc2cf430a920b0bc5a'),
  ('french-a2-practical-4', 'french-a2-practical-4-037-je-vous-invite-a-diner-demain-vous-etes-disponible', 7, 'bright', 'French', 'fr-FR', 'German', 'Je vous invite à dîner demain, vous êtes disponible ?', '{"English":"I am inviting you to dinner tomorrow; are you available?","German":"Ich lade Sie morgen zum Abendessen ein, sind Sie verfügbar?"}', '3efa393baa246da85378a781337f2d5a7d4ad2e4150d88b88e089611cf6b1ef6'),
  ('french-a2-practical-4', 'french-a2-practical-4-038-je-vais-arriver-un-peu-en-retard-excusez-moi', 8, 'bright', 'French', 'fr-FR', 'German', 'Je vais arriver un peu en retard, excusez-moi.', '{"English":"I am going to arrive a little late; excuse me.","German":"Ich werde etwas zu spät kommen, entschuldigen Sie bitte die Verspätung."}', 'f2e83b9379e4320c46e2304e24fb2723c2ef8ee2d940b6df4dcf1dc6027dabd2'),
  ('french-a2-practical-4', 'french-a2-practical-4-039-donc-samedi-a-huit-heures-devant-le-cinema-cest-bien-ca', 9, 'bright', 'French', 'fr-FR', 'German', 'Donc, samedi à huit heures devant le cinéma, c''est bien ça ?', '{"English":"So, Saturday at eight in front of the cinema, is that right?","German":"Also Samstag um acht Uhr vor dem Kino, stimmt das so?"}', 'bc906241890b178d502c5bbf063339d82beb153c56287b2372bc92a50bc39e1b'),
  ('french-a2-practical-4', 'french-a2-practical-4-040-ce-week-end-je-vais-me-reposer-pres-de-la-mer', 10, 'bright', 'French', 'fr-FR', 'German', 'Ce week-end, je vais me reposer près de la mer.', '{"English":"This weekend I am going to rest near the sea.","German":"Dieses Wochenende werde ich mich nahe am Meer ausruhen."}', 'b3eb7362f56fe2086d525484fd51c346cf3f20209829373abecada53f16152fe'),
  ('french-a2-practical-5', 'french-a2-practical-5-041-excusez-moi-il-y-a-une-erreur-jai-commande-un-the-pas-un-cafe', 1, 'bright', 'French', 'fr-FR', 'German', 'Excusez-moi, il y a une erreur : j''ai commandé un thé, pas un café.', '{"English":"Excuse me, there is a mistake: I ordered tea, not coffee.","German":"Entschuldigen Sie, es gibt einen Fehler: Ich habe einen Tee bestellt, keinen Kaffee."}', '4f03af09ba637cea0603c63c10bdf2082e39d268bd24366d554e59b3903b0295'),
  ('french-a2-practical-5', 'french-a2-practical-5-042-non-elle-est-trop-petite-vous-avez-la-taille-au-dessus', 2, 'bright', 'French', 'fr-FR', 'German', 'Non, elle est trop petite. Vous avez la taille au-dessus ?', '{"English":"No, it is too small. Do you have the next size up?","German":"Nein, sie ist zu klein. Haben Sie die nächstgrößere Größe?"}', '71731c7b5000b7ecdcc91bd56219762469176693aef4c4f183d737416a0d6f67'),
  ('french-a2-practical-5', 'french-a2-practical-5-043-je-voudrais-de-leau-plate-a-la-place-sil-vous-plait', 3, 'bright', 'French', 'fr-FR', 'German', 'Je voudrais de l''eau plate à la place, s''il vous plaît.', '{"English":"I would like still water instead, please.","German":"Ich hätte gern stattdessen stilles Wasser, bitte."}', '466291b00000e9dc70c02e78365ee4e1684cc54d513383dcf0451d3295caa822'),
  ('french-a2-practical-5', 'french-a2-practical-5-044-non-merci-je-prefere-les-pommes-rouges-pas-les-vertes', 4, 'bright', 'French', 'fr-FR', 'German', 'Non merci, je préfère les pommes rouges, pas les vertes.', '{"English":"No thank you, I prefer the red apples, not the green ones.","German":"Nein danke, ich bevorzuge die roten Äpfel, nicht die grünen."}', 'efe1fc6db4f565d7e261f16d412835f1e77956a8abb0c38b8774deb31a08c225'),
  ('french-a2-practical-5', 'french-a2-practical-5-045-excusez-moi-il-y-a-trop-de-bruit-vous-pouvez-me-changer-de-chambre', 5, 'bright', 'French', 'fr-FR', 'German', 'Excusez-moi, il y a trop de bruit. Vous pouvez me changer de chambre ?', '{"English":"Excuse me, there is too much noise. Can you move me to another room?","German":"Entschuldigen Sie, es ist zu laut. Können Sie mir ein anderes Zimmer geben?"}', 'ecc10bcdad7d8fbe4990e63673dd221b066572721f7397b17271f9fc0fd7f18e'),
  ('french-a2-practical-5', 'french-a2-practical-5-046-non-merci-je-voudrais-seulement-ceci-sil-vous-plait', 6, 'bright', 'French', 'fr-FR', 'German', 'Non merci, je voudrais seulement ceci, s''il vous plaît.', '{"English":"No thank you, I would like just this, please.","German":"Nein danke, ich hätte gern nur das hier, bitte."}', '710fd4ac6c917d93b8435b48d6459878d1ff26206141f801f6fe63549fe3335a'),
  ('french-a2-practical-5', 'french-a2-practical-5-047-excusez-moi-le-montant-nest-pas-le-bon-sur-laddition', 7, 'bright', 'French', 'fr-FR', 'German', 'Excusez-moi, le montant n''est pas le bon sur l''addition.', '{"English":"Excuse me, the amount on the bill is not right.","German":"Entschuldigen Sie, der Betrag auf der Rechnung stimmt nicht."}', '6feb2a77f77c7bb4ef69c28f3acebdbfad76350be4c974768f5ad7820ab5fd7e'),
  ('french-a2-practical-5', 'french-a2-practical-5-048-je-voudrais-une-boite-plus-petite-sil-vous-plait', 8, 'bright', 'French', 'fr-FR', 'German', 'Je voudrais une boîte plus petite, s''il vous plaît.', '{"English":"I would like a smaller pack, please.","German":"Ich hätte gern eine kleinere Packung, bitte."}', 'e0d93d5d0e14be5c099e02891c6b5a71f057d190692e52b05779599420dcd334'),
  ('french-a2-practical-5', 'french-a2-practical-5-049-a-la-gare-sil-vous-plait-pas-au-centre', 9, 'bright', 'French', 'fr-FR', 'German', 'À la gare, s''il vous plaît, pas au centre.', '{"English":"To the station, please, not the city centre.","German":"Zum Bahnhof, bitte, nicht ins Zentrum."}', '7f627b59ae884ed2feebd3e61bb5c663730ad2b5f6616148a8404dde5efa5cf1'),
  ('french-a2-practical-5', 'french-a2-practical-5-050-aujourdhui-je-ne-peux-pas-mais-merci-pour-linvitation', 10, 'bright', 'French', 'fr-FR', 'German', 'Aujourd''hui, je ne peux pas, mais merci pour l''invitation.', '{"English":"I cannot today, but thank you for the invitation.","German":"Heute kann ich nicht, aber danke für die Einladung."}', 'd4bbeb2c54c14f5814a8527239f8dbc6908c38b37d1d10c1f7c8d510a99e116f'),
  ('french-a2-practical-6', 'french-a2-practical-6-051-je-laisse-ce-pantalon-cest-pret-pour-quand', 1, 'bright', 'French', 'fr-FR', 'German', 'Je laisse ce pantalon, c''est prêt pour quand ?', '{"English":"I am leaving these trousers; when will they be ready?","German":"Ich lasse diese Hose hier, wann ist sie fertig?"}', 'f00f94c5cc08e7fe05f69e0dcc2c8b053c18535013b69c3adeab29ca0904d621'),
  ('french-a2-practical-6', 'french-a2-practical-6-052-mon-telephone-ne-marche-pas-jai-besoin-de-le-faire-reparer', 2, 'bright', 'French', 'fr-FR', 'German', 'Mon téléphone ne marche pas. J''ai besoin de le faire réparer.', '{"English":"My phone does not work. I need to have it repaired.","German":"Mein Telefon funktioniert nicht. Ich muss es reparieren lassen."}', '708a5adc39d88d78eaf7548b6f23573c461a152ecde15c29235c5a533e4d367a'),
  ('french-a2-practical-6', 'french-a2-practical-6-053-jai-besoin-de-dix-euros-de-credit-pour-ma-carte-sim', 3, 'bright', 'French', 'fr-FR', 'German', 'J''ai besoin de dix euros de crédit pour ma carte SIM.', '{"English":"I need ten euros of credit for my SIM card.","German":"Ich brauche zehn Euro Guthaben für meine SIM-Karte."}', '5f1d3af284b83c7c4cd4ddafad97d775ed6b0ba55fb1b5b55dc704e7c4554ce1'),
  ('french-a2-practical-6', 'french-a2-practical-6-054-est-ce-que-je-peux-prendre-rendez-vous-jeudi-vers-quinze-heures', 4, 'bright', 'French', 'fr-FR', 'German', 'Est-ce que je peux prendre rendez-vous jeudi vers quinze heures ?', '{"English":"Can I make an appointment on Thursday at around three o’clock?","German":"Kann ich am Donnerstag gegen fünfzehn Uhr einen Termin vereinbaren?"}', 'fd182be9ef2fac07a9fde73a2c17562dce514c87a6b4a7913c8fc1c9c4b3c9e5'),
  ('french-a2-practical-6', 'french-a2-practical-6-055-jai-besoin-dune-copie-de-cette-cle-sil-vous-plait', 5, 'bright', 'French', 'fr-FR', 'German', 'J''ai besoin d''une copie de cette clé, s''il vous plaît.', '{"English":"I need a copy of this key, please.","German":"Ich brauche eine Kopie von diesem Schlüssel, bitte."}', 'baea043a92f347bb5b9a0320cc18a5c62887fac56dae5c87a85e2123cd237c7f'),
  ('french-a2-practical-6', 'french-a2-practical-6-056-je-viens-chercher-un-colis-pour-mon-voisin', 6, 'bright', 'French', 'fr-FR', 'German', 'Je viens chercher un colis pour mon voisin.', '{"English":"I am here to collect a parcel for my neighbour.","German":"Ich komme, um ein Paket für meinen Nachbarn abzuholen."}', 'a202f001cd5e48360157aea8750eed87bacc4ace4f16c9e8b390ad9cc824752f'),
  ('french-a2-practical-6', 'french-a2-practical-6-057-jai-besoin-de-louer-un-velo-pour-deux-jours', 7, 'bright', 'French', 'fr-FR', 'German', 'J''ai besoin de louer un vélo pour deux jours.', '{"English":"I need to rent a bike for two days.","German":"Ich muss für zwei Tage ein Fahrrad mieten."}', '716ba9c6edc36b2d5aa5f228d78ed24875ae26be0996b8eaa162e70a9517e755'),
  ('french-a2-practical-6', 'french-a2-practical-6-058-la-boutique-est-ouverte-jusqua-quelle-heure-ce-soir', 8, 'bright', 'French', 'fr-FR', 'German', 'La boutique est ouverte jusqu''à quelle heure ce soir ?', '{"English":"Until what time is the shop open this evening?","German":"Bis zu welcher Uhrzeit ist der Laden heute Abend geöffnet?"}', '64694634d32c37f697db934d360ad9fe3150e252f9fdc886294b2ef98e00850b'),
  ('french-a2-practical-6', 'french-a2-practical-6-059-le-telephone-est-pret-je-peux-le-recuperer', 9, 'bright', 'French', 'fr-FR', 'German', 'Le téléphone est prêt, je peux le récupérer ?', '{"English":"Is the phone ready; can I collect it?","German":"Das Telefon ist fertig. Kann ich es abholen?"}', '40ab329136416e779be7526e8ba0b089cd6064b32b96ea879ba3f0637b5b65b6'),
  ('french-a2-practical-6', 'french-a2-practical-6-060-parfait-je-reviens-jeudi-vers-seize-heures-pour-le-recuperer', 10, 'bright', 'French', 'fr-FR', 'German', 'Parfait, je reviens jeudi vers seize heures pour le récupérer.', '{"English":"Perfect, I am coming back on Thursday at around four to collect it.","German":"Perfekt, ich komme am Donnerstag gegen sechzehn Uhr zurück, um es abzuholen."}', '244bc354c6dbc76189b5f78a29b3e408ea89306a842487abb6bf4d5a09997a28'),
  ('french-a2-practical-7', 'french-a2-practical-7-061-quest-ce-que-vous-me-conseillez-ici-pour-dejeuner', 1, 'bright', 'French', 'fr-FR', 'German', 'Qu''est-ce que vous me conseillez ici pour déjeuner ?', '{"English":"What do you recommend here for lunch?","German":"Was empfehlen Sie mir hier zum Mittagessen?"}', '81d9346401695614a56cb0ecc3f1c02a17b0f5545389b9cefb92fedd893ecd0d'),
  ('french-a2-practical-7', 'french-a2-practical-7-062-alors-je-prends-le-poulet-avec-du-riz', 2, 'bright', 'French', 'fr-FR', 'German', 'Alors, je prends le poulet avec du riz.', '{"English":"Then I will have the chicken with rice.","German":"Dann nehme ich das Hähnchen mit Reis."}', '783752597afb212ef4e720e839132d3cefac4f9c516b92598ca2d2b9a3f7d290'),
  ('french-a2-practical-7', 'french-a2-practical-7-063-quel-quartier-me-conseillez-vous-pour-une-promenade', 3, 'bright', 'French', 'fr-FR', 'German', 'Quel quartier me conseillez-vous pour une promenade ?', '{"English":"Which neighbourhood do you recommend for a walk?","German":"Welches Viertel empfehlen Sie mir für einen Spaziergang?"}', '6cd89530576b853fa4d761ad035245cb9e10c71853938d0183f1506576a9fc5c'),
  ('french-a2-practical-7', 'french-a2-practical-7-064-il-est-calme-et-grand-a-cote-de-la-riviere', 4, 'bright', 'French', 'fr-FR', 'German', 'Il est calme et grand, à côté de la rivière.', '{"English":"It is quiet and large, next to the river.","German":"Er ist ruhig und groß, neben dem Fluss."}', '316649be4a79917ee8f0ebdfb3775efcaa68d9ccf5cede2739ddb9c776cd41ca'),
  ('french-a2-practical-7', 'french-a2-practical-7-065-quel-cafe-avec-terrasse-me-conseillez-vous-pres-dici', 5, 'bright', 'French', 'fr-FR', 'German', 'Quel café avec terrasse me conseillez-vous près d''ici ?', '{"English":"Which cafe with a terrace do you recommend nearby?","German":"Welches Café mit Terrasse empfehlen Sie mir ganz in der Nähe?"}', '0a8d63a46aecd98b643f40f2d975c6664bb0a9a969fb54c20c083aa380b927ff'),
  ('french-a2-practical-7', 'french-a2-practical-7-066-vous-avez-une-idee-de-cadeau-pour-mon-ami', 6, 'bright', 'French', 'fr-FR', 'German', 'Vous avez une idée de cadeau pour mon ami ?', '{"English":"Do you have a gift idea for my friend?","German":"Haben Sie eine Geschenkidee für meinen Freund?"}', '0a64fd3a75a65d80cb80ffd15478741c42cc991ff698645ea21c01d5f7ca9975'),
  ('french-a2-practical-7', 'french-a2-practical-7-067-vous-connaissez-un-restaurant-typique-pres-de-lhotel', 7, 'bright', 'French', 'fr-FR', 'German', 'Vous connaissez un restaurant typique près de l''hôtel ?', '{"English":"Do you know a typical restaurant near the hotel?","German":"Kennen Sie ein typisches Restaurant in der Nähe des Hotels?"}', '62bb239117cca884b7cf41888c07bf52d80da5d2fc4d3ec78a0e2d79b65a00c4'),
  ('french-a2-practical-7', 'french-a2-practical-7-068-je-vous-conseille-la-place-derriere-le-theatre', 8, 'bright', 'French', 'fr-FR', 'German', 'Je vous conseille la place, derrière le théâtre.', '{"English":"I recommend the square behind the theatre.","German":"Ich empfehle Ihnen den Platz hinter dem Theater."}', 'eaa004f985e789f8448ff2ab8436a4a5818c687329b89e00b63f8b7a8efb0bea'),
  ('french-a2-practical-7', 'french-a2-practical-7-069-quel-vin-conseillez-vous-avec-le-poisson', 9, 'bright', 'French', 'fr-FR', 'German', 'Quel vin conseillez-vous avec le poisson ?', '{"English":"Which wine do you recommend with the fish?","German":"Welchen Wein empfehlen Sie zum Fisch?"}', '07ca52c4088ebdeff5139ab65972e64ace80752ee535a1e7820d1ce235ba6a8f'),
  ('french-a2-practical-7', 'french-a2-practical-7-070-cest-excellent-vous-avez-raison-merci-pour-ce-conseil', 10, 'bright', 'French', 'fr-FR', 'German', 'C''est excellent, vous avez raison, merci pour ce conseil.', '{"English":"It is excellent, you are right, thank you for this recommendation.","German":"Das ist ausgezeichnet, Sie haben recht, danke für diesen Tipp."}', 'e6b23e1da081a80407e85a13311e85b7c2e5906b1529f4e284b9ada4660d012f'),
  ('french-a2-practical-8', 'french-a2-practical-8-071-quelle-bonne-nouvelle-cest-formidable-pour-vous', 1, 'bright', 'French', 'fr-FR', 'German', 'Quelle bonne nouvelle ! C''est formidable pour vous.', '{"English":"What good news! That is wonderful for you.","German":"Was für eine gute Nachricht! Das ist großartig für Sie."}', '5ac068b81b0ba1bc9a26679b60c2f8d40f7df79a165c7b5acb8b87adc3ef2748'),
  ('french-a2-practical-8', 'french-a2-practical-8-072-oui-il-fait-vraiment-chaud-aujourdhui', 2, 'bright', 'French', 'fr-FR', 'German', 'Oui, il fait vraiment chaud aujourd''hui.', '{"English":"Yes, it is really hot today.","German":"Ja, heute ist es wirklich heiß."}', 'c93be5453c1b047453b52f8d84df09b01b3257f3be6648392a209b910e32ea32'),
  ('french-a2-practical-8', 'french-a2-practical-8-073-jai-sommeil-jai-mal-dormi-cette-nuit', 3, 'bright', 'French', 'fr-FR', 'German', 'J''ai sommeil, j''ai mal dormi cette nuit.', '{"English":"I am sleepy; I slept badly last night.","German":"Ich bin müde, ich habe diese Nacht schlecht geschlafen."}', '90683d3df1f1c9fcfa5fb505aaf2d9183ce1b8d059c56771bf2ee09898d04ac8'),
  ('french-a2-practical-8', 'french-a2-practical-8-074-jai-beaucoup-de-travail-cette-semaine', 4, 'bright', 'French', 'fr-FR', 'German', 'J''ai beaucoup de travail cette semaine.', '{"English":"I have a lot of work this week.","German":"Ich habe diese Woche viel Arbeit."}', '51d23e29970db9e9610f44eef2a00424587e8fecb51498ff9dfea07a87ad02d1'),
  ('french-a2-practical-8', 'french-a2-practical-8-075-oui-il-pleut-encore-quel-dommage', 5, 'bright', 'French', 'fr-FR', 'German', 'Oui, il pleut encore. Quel dommage !', '{"English":"Yes, it is raining again. What a shame!","German":"Ja, es regnet wieder. Wie schade!"}', '2a66504197baa54294657b93f1352b4c826a722ad8ef1ce3582a288b72ca609b'),
  ('french-a2-practical-8', 'french-a2-practical-8-076-oh-non-cest-triste-ca-va-aller', 6, 'bright', 'French', 'fr-FR', 'German', 'Oh non, c''est triste. Ça va aller ?', '{"English":"Oh no, that is sad. Will it be okay?","German":"Oh nein, das ist traurig. Wird alles gut?"}', 'e2a8b8c55e6cbcf7a2c96a5b5cd6e7d324e6bcbaa2e16b4d1fabcf16e075b4d2'),
  ('french-a2-practical-8', 'french-a2-practical-8-077-assez-bien-merci-et-vous-aujourdhui', 7, 'bright', 'French', 'fr-FR', 'German', 'Assez bien, merci. Et vous, aujourd''hui ?', '{"English":"Quite well, thank you. And you today?","German":"Ziemlich gut, danke. Und Ihnen?"}', '188b28ec313addd78562a66e4638b3405d928cf33ad537650bdfb31bd42e8bf2'),
  ('french-a2-practical-8', 'french-a2-practical-8-078-cest-super-cest-une-excellente-nouvelle', 8, 'bright', 'French', 'fr-FR', 'German', 'C''est super, c''est une excellente nouvelle !', '{"English":"That is great, that is excellent news!","German":"Das ist super, das ist eine ausgezeichnete Nachricht!"}', 'a4e5b986dc210b767c9387717c5ac040a024d40b28c95488b312245ae4ba2979'),
  ('french-a2-practical-8', 'french-a2-practical-8-079-il-fait-froid-ce-matin-je-prends-un-cafe', 9, 'bright', 'French', 'fr-FR', 'German', 'Il fait froid ce matin, je prends un café.', '{"English":"It is cold this morning; I am having a coffee.","German":"Heute Morgen ist es kalt, ich nehme einen Kaffee."}', '0ffc5bc61c26e8b94984ce698069a2ae7ea0eda94245fa4a79dc1c85f599e293'),
  ('french-a2-practical-8', 'french-a2-practical-8-080-oui-cest-une-journee-vraiment-agreable', 10, 'bright', 'French', 'fr-FR', 'German', 'Oui, c''est une journée vraiment agréable.', '{"English":"Yes, it is a really pleasant day.","German":"Ja, es ist ein wirklich angenehmer Tag."}', '09758ef83ee0b941b47facb86b5273371a8220977568d48c39275f8ff4dca33e'),
  ('french-a2-practical-9', 'french-a2-practical-9-081-la-douche-ne-marche-pas-jai-appele-la-reception-pouvez-vous-envoyer-quelquun', 1, 'bright', 'French', 'fr-FR', 'German', 'La douche ne marche pas. J''ai appelé la réception. Pouvez-vous envoyer quelqu''un ?', '{"English":"The shower does not work. I called reception; can you send someone?","German":"Die Dusche funktioniert nicht. Ich habe die Rezeption angerufen; können Sie jemanden schicken?"}', 'eef761d7f5beb1e7674a62e7f9dff6225ee9f4ba78ccb59be2a3b1171d8bfb1a'),
  ('french-a2-practical-9', 'french-a2-practical-9-082-jai-commande-une-soupe-mais-elle-nest-pas-encore-la-pouvez-vous-verifier', 2, 'bright', 'French', 'fr-FR', 'German', 'J''ai commandé une soupe, mais elle n''est pas encore là. Pouvez-vous vérifier ?', '{"English":"I ordered a soup, but it is not here yet. Could you check?","German":"Ich habe eine Suppe bestellt, aber sie ist noch nicht da. Können Sie bitte nachsehen?"}', '45196c5ca0ad180b363ebefc47acbef6af880b59de47236eff065c8385006bb7'),
  ('french-a2-practical-9', 'french-a2-practical-9-083-jai-essaye-de-me-connecter-le-wi-fi-ne-fonctionne-pas', 3, 'bright', 'French', 'fr-FR', 'German', 'J''ai essayé de me connecter, le Wi-Fi ne fonctionne pas. Pouvez-vous m''aider ?', '{"English":"I tried to connect, the Wi-Fi does not work. Can you help me?","German":"Ich habe versucht, mich zu verbinden, das WLAN funktioniert nicht. Können Sie mir helfen?"}', 'e2519b825284b7bc8c1d9cefc37f520b64e67611bb48ece330bdb43a54958c82'),
  ('french-a2-practical-9', 'french-a2-practical-9-084-jai-perdu-ma-cle-pouvez-vous-maider-a-entrer', 4, 'bright', 'French', 'fr-FR', 'German', 'J''ai perdu ma clé, pouvez-vous m''aider à entrer ?', '{"English":"I lost my key; can you help me get in?","German":"Ich habe meinen Schlüssel verloren; können Sie mir beim Reinkommen helfen?"}', 'd7c2e53120965180aeb2bb36965b8522bc7115b7a61739a54a8abc23f3e8255b'),
  ('french-a2-practical-9', 'french-a2-practical-9-085-le-taxi-nest-pas-encore-arrive-pouvez-vous-appeler-un-autre-taxi', 5, 'bright', 'French', 'fr-FR', 'German', 'Le taxi n''est pas encore arrivé, pouvez-vous appeler un autre taxi ?', '{"English":"The taxi has not arrived yet; can you call another taxi?","German":"Das Taxi ist noch nicht angekommen; können Sie ein anderes Taxi rufen?"}', 'd21c7e191584f9e9533cfd8f145eb81bdf12596791893dd9417d27616d86c495'),
  ('french-a2-practical-9', 'french-a2-practical-9-086-jai-paye-mais-il-manque-un-euro-pouvez-vous-verifier', 6, 'bright', 'French', 'fr-FR', 'German', 'J''ai payé, mais il manque un euro. Pouvez-vous vérifier ?', '{"English":"I paid, but one euro is missing. Could you check?","German":"Ich habe bezahlt, aber ein Euro fehlt. Können Sie bitte nachsehen?"}', 'a3d360753b70335c25d5cf0909d8dc5e00f61ac1cb10adb51332a131f3127320'),
  ('french-a2-practical-9', 'french-a2-practical-9-087-jai-achete-ce-chargeur-aujourdhui-il-ne-marche-pas-pouvez-vous-le-remplacer', 7, 'bright', 'French', 'fr-FR', 'German', 'J''ai acheté ce chargeur aujourd''hui, il ne marche pas. Pouvez-vous le remplacer ?', '{"English":"I bought this charger today; it does not work. Can you replace it?","German":"Ich habe dieses Ladegerät heute gekauft, es funktioniert nicht. Können Sie es ersetzen?"}', '9073c8e65553a876b3bf641fc518ab47083d2fb132a7a65b338942b2512f3f96'),
  ('french-a2-practical-9', 'french-a2-practical-9-088-jai-commande-cette-soupe-mais-elle-est-froide-pouvez-vous-la-rechauffer', 8, 'bright', 'French', 'fr-FR', 'German', 'J''ai commandé cette soupe, mais elle est froide. Pouvez-vous la réchauffer ?', '{"English":"I ordered this soup, but it is cold. Can you warm it up?","German":"Ich habe diese Suppe bestellt, aber sie ist kalt. Können Sie sie aufwärmen?"}', '49f5c237f8f9b094cb3689f8da722263ee16c0dd79f28f90262705ab106e87f9'),
  ('french-a2-practical-9', 'french-a2-practical-9-089-jai-mal-dormi-a-cause-du-bruit-vous-avez-une-chambre-silencieuse', 9, 'bright', 'French', 'fr-FR', 'German', 'J''ai mal dormi à cause du bruit. Vous avez une chambre silencieuse ?', '{"English":"I slept badly because of the noise. Do you have a quiet room?","German":"Ich habe wegen des Lärms schlecht geschlafen. Haben Sie ein ruhiges Zimmer?"}', 'c00b01d720ffb267a56b21d7aeb4d0189e0a110fbffeb6c538bbf72be24c6648'),
  ('french-a2-practical-9', 'french-a2-practical-9-090-jai-essaye-votre-solution-tout-fonctionne-maintenant-merci-beaucoup', 10, 'bright', 'French', 'fr-FR', 'German', 'J''ai essayé votre solution. Tout fonctionne maintenant. Merci beaucoup.', '{"English":"I tried your solution; everything works now. Thank you very much.","German":"Ich habe Ihre Lösung ausprobiert, jetzt funktioniert alles. Vielen Dank."}', '7e17bfc41e9c874b2684f5565dd412a4f974b013b13f8582059b69f27202c00a'),
  ('german-a1-practical-1', 'german-a1-practical-1-lesson-1-first-contact', 1, 'bright', 'German', 'de-DE', 'English', 'Guten Tag, sprechen Sie Deutsch?', '{"English":"Hello, do you speak German?"}', '78d9d32d3345cad03ec4159ce6e492d6f9f8914667e857c5934c9ff936182b27'),
  ('german-a1-practical-1', 'german-a1-practical-1-lesson-2-polite-follow-up', 2, 'bright', 'German', 'de-DE', 'English', 'Entschuldigung, können Sie das bitte wiederholen?', '{"English":"Sorry, can you please repeat that?"}', '418d1a4dd4e374d406fa88d1bdd8bb44838c54108c873ebb3a56d9e621a8cdff'),
