  ('italian-a2-practical-1', 'italian-a2-practical-1-006-buonasera-ho-una-prenotazione-a-nome-rossi', 6, 'bright', 'Italian', 'it-IT', 'German', 'Buonasera, ho una prenotazione a nome Rossi.', '{"English":"Good evening, I have a reservation under the name Rossi.","German":"Guten Abend, ich habe eine Reservierung auf den Namen Rossi."}', 'f6b1069ee03713253034edc9c6e189d0b03a29b8c7a41a19ed8a5aab9a918edc'),
