  ('italian-a2-practical-10', 'italian-a2-practical-10-092-lavoro-in-un-ufficio-in-centro-vicino-alla-stazione', 2, 'bright', 'Italian', 'it-IT', 'German', 'Lavoro in un ufficio in centro, vicino alla stazione.', '{"English":"I work in an office in the city center, near the station.","German":"Ich arbeite in einem Büro im Zentrum, nahe am Bahnhof."}', 'a5625242a7cf0c6d4c4a8481b5c7539e505f28c79dcf3f8968683a1f412c4979'),
  ('italian-a2-practical-10', 'italian-a2-practical-10-093-studio-italiano-perche-mi-piace-parlare-con-la-gente', 3, 'bright', 'Italian', 'it-IT', 'German', 'Studio italiano perché mi piace parlare con la gente.', '{"English":"I study Italian because I like speaking with people.","German":"Ich lerne Italienisch, weil ich gern mit Menschen spreche."}', '33f2ba7a2d55e75cedf3b211478dc608ef89ce4dfdc7445958f542feaf86e6e9'),
  ('italian-a2-practical-10', 'italian-a2-practical-10-094-sono-qui-da-due-settimane-ormai', 4, 'bright', 'Italian', 'it-IT', 'German', 'Sono qui da due settimane ormai.', '{"English":"I have been here for two weeks now.","German":"Ich bin jetzt seit zwei Wochen hier."}', '198a49d0d94f39f2528d11cf77d0a8d1fb4cbd512c18950b221d2f63ff20b8f9'),
  ('italian-a2-practical-10', 'italian-a2-practical-10-095-la-mia-famiglia-e-in-germania-ma-la-chiamo-ogni-settimana', 5, 'bright', 'Italian', 'it-IT', 'German', 'La mia famiglia è in Germania, ma la chiamo ogni settimana.', '{"English":"My family is in Germany, but I call them every week.","German":"Meine Familie ist in Deutschland, aber ich rufe sie jede Woche an."}', 'e7affbfd3ffb9c00b1857f2d3e84327819b3c1cd68eec3fbd0a6fa7d46b2c581'),
  ('italian-a2-practical-10', 'italian-a2-practical-10-096-nel-tempo-libero-mi-piace-cucinare-e-passeggiare', 6, 'bright', 'Italian', 'it-IT', 'German', 'Nel tempo libero, mi piace cucinare e passeggiare nel quartiere.', '{"English":"In my free time, I like cooking and walking around the neighborhood.","German":"In meiner freien Zeit koche ich gern und gehe im Viertel spazieren."}', 'c65439f7f11228aa658ba8e64f73f484d555ad998783f3df46e9e0b6fdb42fb7'),
  ('italian-a2-practical-10', 'italian-a2-practical-10-097-la-mattina-lavoro-e-la-sera-studio-italiano', 7, 'bright', 'Italian', 'it-IT', 'German', 'La mattina lavoro, e la sera studio italiano.', '{"English":"In the morning I work, and in the evening I study Italian.","German":"Morgens arbeite ich, und abends lerne ich Italienisch."}', '95bec5bfc9098b71f9202f463f810a49993fda1f887f3225f5186a452950efda'),
  ('italian-a2-practical-10', 'italian-a2-practical-10-098-ho-gia-fatto-progressi-capisco-quasi-tutto', 8, 'bright', 'Italian', 'it-IT', 'German', 'Ho già fatto progressi: capisco quasi tutto e parlo piano.', '{"English":"I have already made progress: I understand almost everything and speak slowly.","German":"Ich habe schon Fortschritte gemacht: Ich verstehe fast alles und spreche langsam."}', '5bbfd3b86478fdf9f440f259be2ea90d4883eeb7aa282ac5602b899049b5065a'),
  ('italian-a2-practical-10', 'italian-a2-practical-10-099-lanno-prossimo-torno-qui-per-qualche-giorno', 9, 'bright', 'Italian', 'it-IT', 'German', 'L’anno prossimo torno qui per qualche giorno.', '{"English":"Next year I am coming back here for a few days.","German":"Nächstes Jahr komme ich für ein paar Tage hierher zurück."}', '0c95e639aea7a7f4c2b7b5a7d51c182754b379d4cf9806c3f9e769c40f22615b'),
  ('italian-a2-practical-10', 'italian-a2-practical-10-100-grazie-di-cuore-ci-vediamo-presto', 10, 'bright', 'Italian', 'it-IT', 'German', 'Grazie di cuore. Ci vediamo presto!', '{"English":"Thank you from the heart. See you soon!","German":"Herzlichen Dank. Wir sehen uns bald!"}', 'fbdd2ffc29d7b1d42178787a97fd29831aad9089a6362d1bbee86a5282cdef93'),
  ('italian-a2-practical-2', 'italian-a2-practical-2-011-preferisco-questi-pomodori-perche-sono-piu-maturi', 1, 'bright', 'Italian', 'it-IT', 'German', 'Preferisco questi pomodori perché sono più maturi.', '{"English":"I prefer these tomatoes because they are riper.","German":"Ich bevorzuge diese Tomaten, weil sie reifer sind."}', '8bbabb343d6f51784a4e8cb10aa7bae062de06e3170afda6f6cbc75e2c6e864f'),
  ('italian-a2-practical-2', 'italian-a2-practical-2-012-oggi-preferisco-un-succo-perche-e-meno-forte-del-caffe', 2, 'bright', 'Italian', 'it-IT', 'German', 'Oggi preferisco un succo perché è meno forte del caffè.', '{"English":"Today I prefer a juice because it is less strong than coffee.","German":"Heute bevorzuge ich einen Saft, weil er weniger stark als Kaffee ist."}', 'caf79ea6a7c584b5988fcd4507d3a9caa03b42f74075bc383db28defc745e402'),
  ('italian-a2-practical-2', 'italian-a2-practical-2-013-preferisco-la-camicia-blu-perche-e-piu-grande', 3, 'bright', 'Italian', 'it-IT', 'German', 'Preferisco la camicia blu perché è più grande.', '{"English":"I prefer the blue shirt because it is bigger.","German":"Ich bevorzuge das blaue Hemd, weil es größer ist."}', '6b54ad03d931da834e485389754e7e0060fa2cdf2208de482789f797897232a7'),
  ('italian-a2-practical-2', 'italian-a2-practical-2-014-prendo-linsalata-perche-e-piu-leggera', 4, 'bright', 'Italian', 'it-IT', 'German', 'Prendo l’insalata perché è più leggera.', '{"English":"I will have the salad because it is lighter.","German":"Ich nehme den Salat, weil er leichter ist."}', 'c3d5860159e3c90cbe8b73412356a6839be70f0a1f30650cc3cdb1521938739a'),
  ('italian-a2-practical-2', 'italian-a2-practical-2-015-questo-pane-e-piu-fresco-di-quello', 5, 'bright', 'Italian', 'it-IT', 'German', 'Questo pane è più fresco di quello.', '{"English":"This bread is fresher than that one.","German":"Dieses Brot ist frischer als jenes."}', '9a75684682e0045a18c5ecb99667727ff68d695750d4c7bc8cab281feb2e7831'),
  ('italian-a2-practical-2', 'italian-a2-practical-2-016-vado-in-metro-perche-e-piu-veloce', 6, 'bright', 'Italian', 'it-IT', 'German', 'Vado in metro perché è più veloce.', '{"English":"I go by metro because it is faster.","German":"Ich fahre mit der Metro, weil sie schneller ist."}', '4550a02710ce7456afa6ef2b1d93d67d7b54e81abd42579a1341b132045f0f20'),
  ('italian-a2-practical-2', 'italian-a2-practical-2-017-preferisco-questa-camera-perche-dormo-meglio', 7, 'bright', 'Italian', 'it-IT', 'German', 'Preferisco questa camera perché dormo meglio.', '{"English":"I prefer this room because I sleep better.","German":"Ich bevorzuge dieses Zimmer, weil ich besser schlafe."}', 'ff30431647a02b4e6391008dbb9c6cfbc1d0dc47960ffc42788894ed8e353510'),
  ('italian-a2-practical-2', 'italian-a2-practical-2-018-preferisco-queste-scarpe-perche-sono-comode', 8, 'bright', 'Italian', 'it-IT', 'German', 'Preferisco queste scarpe perché sono comode.', '{"English":"I prefer these shoes because they are comfortable.","German":"Ich bevorzuge diese Schuhe, weil sie bequem sind."}', 'a7c57763ab4fc52a6ef110f44a31292f56786330f450c655076e6fbd563370d3'),
  ('italian-a2-practical-2', 'italian-a2-practical-2-019-prendo-la-bottiglia-piccola-perche-costa-meno', 9, 'bright', 'Italian', 'it-IT', 'German', 'Prendo la bottiglia piccola perché costa meno.', '{"English":"I will take the small bottle because it costs less.","German":"Ich nehme die kleine Flasche, weil sie weniger kostet."}', 'f7acf8638dd631a40961fab45d1669ad9fc177e688f0a8c209f321af485cf9e7'),
  ('italian-a2-practical-2', 'italian-a2-practical-2-020-preferisco-questo-locale-perche-e-vicino-e-tranquillo', 10, 'bright', 'Italian', 'it-IT', 'German', 'Preferisco questo locale perché è vicino e tranquillo.', '{"English":"I prefer this place because it is nearby and quiet.","German":"Ich bevorzuge dieses Lokal, weil es nah und ruhig ist."}', 'ca9a424d4904f9d89e56f1167b94d81c847409b6f93b3e71eaab8d456b6a1d76'),
  ('italian-a2-practical-3', 'italian-a2-practical-3-021-ho-gia-pagato-alla-cassa-grazie', 1, 'bright', 'Italian', 'it-IT', 'German', 'Ho già pagato alla cassa, grazie.', '{"English":"I have already paid at the till, thank you.","German":"Ich habe schon an der Kasse bezahlt, danke."}', '43aa9088b897d6661fba958283478be5f412eed76991c19a19923c2f1acb0080'),
  ('italian-a2-practical-3', 'italian-a2-practical-3-022-ho-preso-il-treno-ieri-sera-alle-otto', 2, 'bright', 'Italian', 'it-IT', 'German', 'Ho preso il treno ieri sera alle otto.', '{"English":"I took the train at eight yesterday evening.","German":"Ich habe gestern Abend um acht den Zug genommen."}', 'a1552f19defbbdeea0df4333a161c0940dbf7e64a2a83967080bd54f630d8f4e'),
  ('italian-a2-practical-3', 'italian-a2-practical-3-023-ho-gia-ordinato-la-pasta-grazie', 3, 'bright', 'Italian', 'it-IT', 'German', 'Ho già ordinato la pasta, grazie.', '{"English":"I have already ordered the pasta, thank you.","German":"Ich habe die Pasta schon bestellt, danke."}', '33cca98d33a5fd18681413de1ad2e3a07ce450ae67569ace9b40e1107572c216'),
  ('italian-a2-practical-3', 'italian-a2-practical-3-024-oggi-ho-comprato-i-pomodori-al-mercato', 4, 'bright', 'Italian', 'it-IT', 'German', 'Oggi ho comprato i pomodori al mercato.', '{"English":"Today I bought the tomatoes at the market.","German":"Heute habe ich die Tomaten auf dem Markt gekauft."}', '14fa3a3211bd9c2648e5271b264d893fa8537f00354143fb8b1747968ffaeeb8'),
  ('italian-a2-practical-3', 'italian-a2-practical-3-025-stamattina-ho-fatto-la-spesa-al-mercato', 5, 'bright', 'Italian', 'it-IT', 'German', 'Stamattina ho fatto la spesa al mercato.', '{"English":"This morning I did the shopping at the market.","German":"Heute Morgen habe ich auf dem Markt eingekauft."}', 'fcd59f21d09fff60c57effb6ea3e29d7c2e6df4eb99685fb7249fd1b5d24401a'),
  ('italian-a2-practical-3', 'italian-a2-practical-3-026-ieri-ho-avuto-mal-di-testa-ma-oggi-sto-meglio', 6, 'bright', 'Italian', 'it-IT', 'German', 'Ieri ho avuto mal di testa, ma oggi sto meglio.', '{"English":"Yesterday I had a headache, but today I feel better.","German":"Gestern hatte ich Kopfschmerzen, aber heute geht es mir besser."}', 'd0d408606560b10402b2260bd93524bd8c2b0f124f475d7237b4265d7e68d688'),
  ('italian-a2-practical-3', 'italian-a2-practical-3-027-si-ho-gia-provato-il-piatto-tipico', 7, 'bright', 'Italian', 'it-IT', 'German', 'Sì, ho già provato il piatto tipico.', '{"English":"Yes, I have already tried the local dish.","German":"Ja, ich habe das typische Gericht schon probiert."}', '091bcc645962f5e8c9aa9e165801a8fd7e07423aeaa8c865048802e26d4bbe04'),
  ('italian-a2-practical-3', 'italian-a2-practical-3-028-purtroppo-non-ho-ancora-visto-il-duomo', 8, 'bright', 'Italian', 'it-IT', 'German', 'Purtroppo non ho ancora visto il duomo.', '{"English":"Unfortunately, I have not seen the cathedral yet.","German":"Leider habe ich den Dom noch nicht gesehen."}', '14e5b12ae1d65a6af3529c1ca36fa1fb82a133de29fae5dc01a7d40c7b698e6a'),
  ('italian-a2-practical-3', 'italian-a2-practical-3-029-oggi-ho-finito-il-lavoro-presto', 9, 'bright', 'Italian', 'it-IT', 'German', 'Oggi ho finito il lavoro presto.', '{"English":"Today I finished work early.","German":"Heute habe ich die Arbeit früh beendet."}', 'cc43651a1944899128c2438f6dbcf844ae79594fbd406394ee27c3926e9b101a'),
  ('italian-a2-practical-3', 'italian-a2-practical-3-030-questa-settimana-ho-fatto-davvero-molte-cose', 10, 'bright', 'Italian', 'it-IT', 'German', 'Questa settimana ho fatto davvero molte cose.', '{"English":"This week I have done many things indeed.","German":"Diese Woche habe ich wirklich viele Dinge gemacht."}', '0ffbc6db2d8e099b1497a53b1799ef62eafa8241bd42145f4ee427b60e9d74d8'),
  ('italian-a2-practical-4', 'italian-a2-practical-4-031-volentieri-alle-cinque-va-bene-per-lei', 1, 'bright', 'Italian', 'it-IT', 'German', 'Volentieri. Alle cinque va bene per Lei?', '{"English":"Gladly. Does five work for you?","German":"Gern. Passt fünf Uhr für Sie?"}', '3d4db61dd7f0d1d92cb9cfa8d310487ce509ceb0454341ff0876a5d6cd898888'),
  ('italian-a2-practical-4', 'italian-a2-practical-4-032-domani-vado-al-museo-dopo-il-lavoro', 2, 'bright', 'Italian', 'it-IT', 'German', 'Domani vado al museo dopo il lavoro.', '{"English":"Tomorrow I am going to the museum after work.","German":"Morgen gehe ich nach der Arbeit ins Museum."}', '92f563bf9b4af530539d6e405f75c31148eeef3098d4050281de45d7466ad57a'),
  ('italian-a2-practical-4', 'italian-a2-practical-4-033-che-ne-dice-del-cinema-venerdi-sera', 3, 'bright', 'Italian', 'it-IT', 'German', 'Che ne dice del cinema venerdì sera?', '{"English":"What do you think of the cinema on Friday evening?","German":"Was halten Sie am Freitagabend vom Kino?"}', '5af6c4267217c1b2b016c83c8ade8707f64d11e8e50e1ff45afeab9d31629ca3'),
  ('italian-a2-practical-4', 'italian-a2-practical-4-034-alle-otto-in-piazza-davanti-alla-fontana', 4, 'bright', 'Italian', 'it-IT', 'German', 'Alle otto in piazza, davanti alla fontana.', '{"English":"At eight in the square, in front of the fountain.","German":"Um acht auf dem Platz, vor dem Brunnen."}', 'a08ec780bdacf762a16df88d2c1dec7ccaf194c00a1ff336606d2a16b681ed96'),
  ('italian-a2-practical-4', 'italian-a2-practical-4-035-sabato-per-me-va-bene-dopo-le-sei', 5, 'bright', 'Italian', 'it-IT', 'German', 'Sabato per me va bene dopo le sei.', '{"English":"Saturday works for me after six.","German":"Samstag passt mir nach sechs Uhr."}', '0a9ba532b96d1fe5d0405a636b165d6d0481432ec5e04d8be9a10b280cde4c73'),
  ('italian-a2-practical-4', 'italian-a2-practical-4-036-mi-dispiace-oggi-non-posso-ho-molto-lavoro', 6, 'bright', 'Italian', 'it-IT', 'German', 'Mi dispiace, oggi non posso: ho molto lavoro.', '{"English":"I am sorry, I cannot today: I have a lot of work.","German":"Es tut mir leid, heute kann ich nicht: Ich habe viel Arbeit."}', '28687f6d364863d1314bdf64896ed42896dde8e72a2d86b6d6877cc2531d90f6'),
  ('italian-a2-practical-4', 'italian-a2-practical-4-037-la-invito-a-cena-mercoledi-alle-otto', 7, 'bright', 'Italian', 'it-IT', 'German', 'La invito a cena mercoledì alle otto.', '{"English":"I invite you to dinner on Wednesday at eight.","German":"Ich lade Sie am Mittwoch um acht zum Abendessen ein."}', 'b33464bf21f9b4f17ddc29b295a95ba7210ae6f56731706a30a3cc00de182665'),
  ('italian-a2-practical-4', 'italian-a2-practical-4-038-arrivo-un-po-tardi-ma-sono-quasi-li', 8, 'bright', 'Italian', 'it-IT', 'German', 'Arrivo un po’ tardi, ma sono quasi lì.', '{"English":"I am arriving a little late, but I am almost there.","German":"Ich komme etwas spät, bin aber fast da."}', '9f4d7bfab5be6bf9e35dbc8d492f5d237898fc552157ed30b214c7b97915680e'),
  ('italian-a2-practical-4', 'italian-a2-practical-4-039-allora-sabato-alle-sei-davanti-al-museo-va-bene', 9, 'bright', 'Italian', 'it-IT', 'German', 'Allora sabato alle sei davanti al museo, va bene?', '{"English":"So Saturday at six in front of the museum, is that right?","German":"Also Samstag um sechs vor dem Museum, passt das?"}', '32fa7623fa846e7350b21a649297ce5c375edcfe1fe68e34f1927246df7be7f9'),
  ('italian-a2-practical-4', 'italian-a2-practical-4-040-nel-fine-settimana-riposo-e-faccio-una-gita-breve', 10, 'bright', 'Italian', 'it-IT', 'German', 'Nel fine settimana riposo e faccio una gita breve.', '{"English":"At the weekend I rest and take a short trip.","German":"Am Wochenende ruhe ich mich aus und mache einen kurzen Ausflug."}', '900c7a3ef34d4e3d60ec4650d70e9a73fb0497eb5e80d5140970ea68754cb6ad'),
  ('italian-a2-practical-5', 'italian-a2-practical-5-041-mi-scusi-ho-ordinato-il-te-invece-del-caffe', 1, 'bright', 'Italian', 'it-IT', 'German', 'Mi scusi, ho ordinato il tè invece del caffè.', '{"English":"Excuse me, I ordered tea instead of coffee.","German":"Entschuldigen Sie, ich habe Tee statt Kaffee bestellt."}', '2d47aad79e6cbc72155814fbe121d1ed56b683559257533fb528744e345a739a'),
  ('italian-a2-practical-5', 'italian-a2-practical-5-042-mi-scusi-questa-taglia-e-troppo-piccola-per-me', 2, 'bright', 'Italian', 'it-IT', 'German', 'Mi scusi, questa taglia è troppo piccola per me.', '{"English":"Excuse me, this size is too small for me.","German":"Entschuldigen Sie, diese Größe ist zu klein für mich."}', '8b9f099b1e891005b3e9e6184ecc49614028f2af129ceb058ce00178696a622d'),
  ('italian-a2-practical-5', 'italian-a2-practical-5-043-mi-porta-acqua-naturale-invece-di-quella-frizzante', 3, 'bright', 'Italian', 'it-IT', 'German', 'Mi porta acqua naturale invece di quella frizzante?', '{"English":"Could you bring me still water instead of sparkling water?","German":"Bringen Sie mir stilles statt sprudelndes Wasser?"}', '4199462cbf5367a7082b3ebe1156bad3407a26748b457c21592d1676387efaf6'),
  ('italian-a2-practical-5', 'italian-a2-practical-5-044-no-preferisco-quelli-piu-maturi-per-favore', 4, 'bright', 'Italian', 'it-IT', 'German', 'No, preferisco quelli più maturi, per favore.', '{"English":"No, I prefer the riper ones, please.","German":"Nein, ich bevorzuge bitte die reiferen."}', 'e09ad07bf4b994a59addb21da9856f81a36c21a0ead31c20e95271b3cf050eb8'),
  ('italian-a2-practical-5', 'italian-a2-practical-5-045-potrei-cambiare-camera-e-troppo-rumorosa', 5, 'bright', 'Italian', 'it-IT', 'German', 'Potrei cambiare camera? È troppo rumorosa.', '{"English":"Could I change rooms? It is too noisy.","German":"Könnte ich das Zimmer wechseln? Es ist zu laut."}', 'bd4df3b436429460828cf69dc65e7fb8166395c368dbbd6ddf955c5c857dacc8'),
  ('italian-a2-practical-5', 'italian-a2-practical-5-046-no-grazie-prendo-solo-questo-per-oggi', 6, 'bright', 'Italian', 'it-IT', 'German', 'No, grazie, prendo solo questo per oggi.', '{"English":"No thanks, I will take just this today.","German":"Nein danke, ich nehme heute nur das hier."}', '77db804e5581a805236d9651332c45fd437d242cbc1af039b1f737e4c63846bb'),
  ('italian-a2-practical-5', 'italian-a2-practical-5-047-mi-scusi-il-totale-non-e-corretto', 7, 'bright', 'Italian', 'it-IT', 'German', 'Mi scusi, il totale non è corretto.', '{"English":"Excuse me, the total is not correct.","German":"Entschuldigen Sie, der Gesamtbetrag stimmt nicht."}', 'a3abfbfd2674a207a33c0601868d8312754ebcd8b797c23e0edca78c86d44ce9'),
  ('italian-a2-practical-5', 'italian-a2-practical-5-048-vorrei-una-confezione-piu-piccola-per-favore', 8, 'bright', 'Italian', 'it-IT', 'German', 'Vorrei una confezione più piccola, per favore.', '{"English":"I would like a smaller pack, please.","German":"Ich hätte gern bitte eine kleinere Packung."}', 'fe207d5dfb9e633eccf71745388316d570890dce79cd1e1436e6d6ae42ca5d0b'),
  ('italian-a2-practical-5', 'italian-a2-practical-5-049-mi-porta-alla-stazione-non-in-centro', 9, 'bright', 'Italian', 'it-IT', 'German', 'Mi porta alla stazione, non in centro?', '{"English":"Could you take me to the station, not downtown?","German":"Fahren Sie mich zum Bahnhof, nicht ins Zentrum?"}', '63067ae068d77a34c041295ba737835307df3628a378b5a8e4077569d94df8de'),
  ('italian-a2-practical-5', 'italian-a2-practical-5-050-mi-dispiace-oggi-non-posso-venire', 10, 'bright', 'Italian', 'it-IT', 'German', 'Mi dispiace, oggi non posso venire.', '{"English":"I am sorry, I cannot come today.","German":"Es tut mir leid, heute kann ich nicht kommen."}', 'e1294700cedb0986e193d956a280e3f5b40a49959705645906dfe3ae9b1720e7'),
  ('italian-a2-practical-6', 'italian-a2-practical-6-051-lascio-questi-vestiti-per-quando-sono-pronti', 1, 'bright', 'Italian', 'it-IT', 'German', 'Lascio questi vestiti. Per quando sono pronti?', '{"English":"I am leaving these clothes. When will they be ready?","German":"Ich gebe diese Kleidung ab. Bis wann ist sie fertig?"}', '3a8bcef36cf70a37f29fe1ee11b8f348f0651e21e4965af1a5805beac2889184'),
  ('italian-a2-practical-6', 'italian-a2-practical-6-052-il-telefono-non-funziona-ho-bisogno-di-farlo-riparare', 2, 'bright', 'Italian', 'it-IT', 'German', 'Il telefono non funziona: ho bisogno di farlo riparare.', '{"English":"The phone does not work: I need to have it repaired.","German":"Das Telefon funktioniert nicht: Ich muss es reparieren lassen."}', '09f409cf4a304aac4d17de32913f8e452c38015501347ccd076ca7f8a26db229'),
  ('italian-a2-practical-6', 'italian-a2-practical-6-053-vorrei-una-ricarica-da-dieci-euro-per-favore', 3, 'bright', 'Italian', 'it-IT', 'German', 'Vorrei una ricarica da dieci euro, per favore.', '{"English":"I would like a ten-euro top-up, please.","German":"Ich hätte gern bitte eine Aufladung über zehn Euro."}', '0ed0cbbffce3cc39c9a5a8631619d08cf2c3a6bbe5d98e22d671b11cf7ade5b9'),
  ('italian-a2-practical-6', 'italian-a2-practical-6-054-vorrei-prendere-un-appuntamento-per-giovedi-mattina', 4, 'bright', 'Italian', 'it-IT', 'German', 'Vorrei prendere un appuntamento per giovedì mattina.', '{"English":"I would like to make an appointment for Thursday morning.","German":"Ich hätte gern einen Termin für Donnerstagmorgen."}', '42f299f62c638f080a54214ad4743fd15012d37ac0d199898572011fd262a0f6'),
  ('italian-a2-practical-6', 'italian-a2-practical-6-055-vorrei-fare-una-copia-di-questa-chiave', 5, 'bright', 'Italian', 'it-IT', 'German', 'Vorrei fare una copia di questa chiave.', '{"English":"I would like a copy of this key.","German":"Ich hätte gern eine Kopie von diesem Schlüssel."}', '552c7e7cb5522413462405770670d35ceee991ad1f450a7969a77bdd4841f5aa'),
  ('italian-a2-practical-6', 'italian-a2-practical-6-056-sono-qui-per-ritirare-un-pacco-a-nome-rossi', 6, 'bright', 'Italian', 'it-IT', 'German', 'Sono qui per ritirare un pacco, a nome Rossi.', '{"English":"I am here to collect a package under the name Rossi.","German":"Ich bin hier, um ein Paket auf den Namen Rossi abzuholen."}', '2bb1dae962dc46cc17e07ed840357b2f9d0c5deed8d67848f7d0993cb8020c2a'),
  ('italian-a2-practical-6', 'italian-a2-practical-6-057-vorrei-noleggiare-una-bicicletta-per-due-giorni', 7, 'bright', 'Italian', 'it-IT', 'German', 'Vorrei noleggiare una bicicletta per due giorni.', '{"English":"I would like to rent a bicycle for two days.","German":"Ich würde gern ein Fahrrad für zwei Tage mieten."}', '15b53668e85a58e32e0500fc7acaf8a391f1a068519e1f23162a3682cfd6518b'),
  ('italian-a2-practical-6', 'italian-a2-practical-6-058-fino-a-che-ora-resta-aperto-oggi', 8, 'bright', 'Italian', 'it-IT', 'German', 'Fino a che ora resta aperto oggi?', '{"English":"Until what time is it open today?","German":"Bis wann haben Sie heute geöffnet?"}', '044e25ab2c7f221b9364eafd1175413609d6cd2159dd0ec6cfc132238a810b1d'),
  ('italian-a2-practical-6', 'italian-a2-practical-6-059-il-telefono-e-gia-pronto-vengo-subito-a-ritirarlo', 9, 'bright', 'Italian', 'it-IT', 'German', 'Il telefono è già pronto? Vengo subito a ritirarlo.', '{"English":"Is the phone already ready? I am coming straight away to collect it.","German":"Ist das Handy schon fertig? Ich komme sofort, um es abzuholen."}', '585724f951c29b7026c61fd46f07b8823eace7bd91d7655c8f57652d0cafa53c'),
  ('italian-a2-practical-6', 'italian-a2-practical-6-060-benissimo-allora-lappuntamento-e-giovedi-mattina', 10, 'bright', 'Italian', 'it-IT', 'German', 'Benissimo, allora l’appuntamento è giovedì mattina.', '{"English":"Excellent, then the appointment is Thursday morning.","German":"Sehr gut, dann ist der Termin am Donnerstagmorgen."}', 'f9e4d92796611f7d938d129399598b8dbb2a3f76df97f183ce12e094255a56d6'),
  ('italian-a2-practical-7', 'italian-a2-practical-7-061-che-cosa-mi-consiglia-da-mangiare-per-pranzo', 1, 'bright', 'Italian', 'it-IT', 'German', 'Che cosa mi consiglia da mangiare per pranzo?', '{"English":"What do you recommend for lunch?","German":"Was empfehlen Sie mir zum Mittagessen?"}', '46ef6bade21ab9fb10cb4dc391b057678def0a3088df41eee383f1d2ecdd3a6a'),
  ('italian-a2-practical-7', 'italian-a2-practical-7-062-allora-prendo-il-risotto-caldo-grazie', 2, 'bright', 'Italian', 'it-IT', 'German', 'Allora prendo il risotto caldo, grazie.', '{"English":"Then I will have the warm risotto, thank you.","German":"Dann nehme ich das warme Risotto, danke."}', '5b2a0426a338d02c4d898ee42ead471f2527eb78005ccebb6554dce0f4482079'),
  ('italian-a2-practical-7', 'italian-a2-practical-7-063-quale-quartiere-consiglia-per-una-passeggiata-tranquilla', 3, 'bright', 'Italian', 'it-IT', 'German', 'Quale quartiere consiglia per una passeggiata tranquilla?', '{"English":"Which neighborhood do you recommend for a quiet walk?","German":"Welches Viertel empfehlen Sie für einen ruhigen Spaziergang?"}', '001ee1640ac4ee9f0f632f3ad6996720ce35b857ee7666316039e1eef3caddee'),
  ('italian-a2-practical-7', 'italian-a2-practical-7-064-e-un-parco-tranquillo-e-grande-accanto-al-fiume', 4, 'bright', 'Italian', 'it-IT', 'German', 'È un parco tranquillo e grande, accanto al fiume.', '{"English":"It is a quiet and large park next to the river.","German":"Es ist ein ruhiger und großer Park neben dem Fluss."}', '7d5264e109098d9774cd978b6dea29e1988072ce8fc8217ca23c08baa111207e'),
  ('italian-a2-practical-7', 'italian-a2-practical-7-065-qual-e-il-miglior-bar-vicino-alla-piazza', 5, 'bright', 'Italian', 'it-IT', 'German', 'Qual è il miglior bar vicino alla piazza?', '{"English":"Which is the best bar near the square?","German":"Welches ist die beste Bar nahe dem Platz?"}', '072d188d03a9c1f526bc2457eb5b667a8631678864095762c8ccf4f9597e8b2c'),
  ('italian-a2-practical-7', 'italian-a2-practical-7-066-che-regalo-mi-consiglia-per-il-compleanno-di-un-amico', 6, 'bright', 'Italian', 'it-IT', 'German', 'Che regalo mi consiglia per il compleanno di un amico?', '{"English":"What gift do you recommend for a friend’s birthday?","German":"Welches Geschenk empfehlen Sie mir zum Geburtstag eines Freundes?"}', '718948aa8344bb291f0f5ec0a151f8087d4f2296223991397e813529435628a0'),
  ('italian-a2-practical-7', 'italian-a2-practical-7-067-per-favore-ce-un-ristorante-tipico-vicino-allhotel', 7, 'bright', 'Italian', 'it-IT', 'German', 'Per favore, c’è un ristorante tipico vicino all’hotel?', '{"English":"Excuse me, is there a typical restaurant near the hotel?","German":"Entschuldigung, gibt es ein typisches Restaurant nahe dem Hotel?"}', 'e774ec19805fbbececcba7879626ec3cee4c9318af745d5a906b775aaf7cbf1b'),
  ('italian-a2-practical-7', 'italian-a2-practical-7-068-le-consiglio-la-piazza-vivace-e-sicura-di-sera', 8, 'bright', 'Italian', 'it-IT', 'German', 'Le consiglio la piazza, vivace e sicura di sera.', '{"English":"I recommend the square to you; it is lively and safe in the evening.","German":"Ich empfehle Ihnen den Platz; abends ist er lebhaft und sicher."}', 'a466a665990233dee81c0acf83749c49ff67566bd567b5bf5295dc81bb13e90d'),
  ('italian-a2-practical-7', 'italian-a2-practical-7-069-quale-vino-consiglia-con-il-pesce-fresco', 9, 'bright', 'Italian', 'it-IT', 'German', 'Quale vino consiglia con il pesce fresco?', '{"English":"Which wine do you recommend with the fresh fish?","German":"Welchen Wein empfehlen Sie zu dem frischen Fisch?"}', '49af81c41513dc15e51cf74937b2ca63c1c0d9272cbed26b97d2b754a57b09ae'),
  ('italian-a2-practical-7', 'italian-a2-practical-7-070-e-eccellente-ha-ragione-grazie-del-consiglio', 10, 'bright', 'Italian', 'it-IT', 'German', 'È eccellente, ha ragione. Grazie del consiglio.', '{"English":"It is excellent, you are right. Thank you for the recommendation.","German":"Es ist ausgezeichnet, Sie haben recht. Danke für die Empfehlung."}', '28853ecb2f7038e87d012e60844e2382ddc8825bd6c9d646e97637f7cefac598'),
  ('italian-a2-practical-8', 'italian-a2-practical-8-071-davvero-che-bella-notizia-per-lei', 1, 'bright', 'Italian', 'it-IT', 'German', 'Davvero? Che bella notizia per Lei!', '{"English":"Really? What lovely news for you!","German":"Wirklich? Was für eine schöne Nachricht für Sie!"}', '974d726959cadd34c4329ad778c9d1acc247dea4aa13313249411b652ebd4155'),
  ('italian-a2-practical-8', 'italian-a2-practical-8-072-si-oggi-fa-davvero-troppo-caldo', 2, 'bright', 'Italian', 'it-IT', 'German', 'Sì, oggi fa davvero troppo caldo.', '{"English":"Yes, it is really too hot today.","German":"Ja, heute ist es wirklich zu heiß."}', '220c9792b20d5027d1b30e2142713e23894e3e7c56e908e854300e84b9e698a0'),
  ('italian-a2-practical-8', 'italian-a2-practical-8-073-ho-sonno-perche-ho-dormito-poco', 3, 'bright', 'Italian', 'it-IT', 'German', 'Ho sonno perché ho dormito poco.', '{"English":"I am sleepy because I slept little.","German":"Ich bin schläfrig, weil ich wenig geschlafen habe."}', 'b7bbe0d16fa3fc48599831094ebfce722719b3b168c3c015ac9c273def929ce7'),
  ('italian-a2-practical-8', 'italian-a2-practical-8-074-questa-settimana-ho-molto-lavoro-purtroppo', 4, 'bright', 'Italian', 'it-IT', 'German', 'Questa settimana ho molto lavoro, purtroppo.', '{"English":"This week I have a lot of work, unfortunately.","German":"Diese Woche habe ich leider viel Arbeit."}', '8941452b201322475949315248e6bbf4babab5f08b9d98ba9158538b8a6bf10c'),
  ('italian-a2-practical-8', 'italian-a2-practical-8-075-piove-ancora-che-peccato-per-il-mercato', 5, 'bright', 'Italian', 'it-IT', 'German', 'Piove ancora: che peccato per il mercato.', '{"English":"It is raining again: what a shame for the market.","German":"Es regnet wieder: schade für den Markt."}', '58aeebc0f2202ecfed44d7d4dfabc6299e6448192d1fb1cab6ee1fca628d786b'),
  ('italian-a2-practical-8', 'italian-a2-practical-8-076-mi-dispiace-molto-spero-in-buone-notizie', 6, 'bright', 'Italian', 'it-IT', 'German', 'Mi dispiace molto. Spero in buone notizie.', '{"English":"I am very sorry. I hope for good news.","German":"Das tut mir sehr leid. Ich hoffe auf gute Nachrichten."}', 'ca4841cbed78ed99beab36b347f28aa1c11d97f9f2dd6fda6f9457367246a511'),
  ('italian-a2-practical-8', 'italian-a2-practical-8-077-abbastanza-bene-grazie-e-lei-come-va', 7, 'bright', 'Italian', 'it-IT', 'German', 'Abbastanza bene, grazie. E Lei, come va?', '{"English":"Quite well, thank you. And you, how is it going?","German":"Ziemlich gut, danke. Und Ihnen, wie geht es?"}', 'b655ae8359ff86fdd75527c77bd15cc689cd7c3c8d29b12eccec7897a30e3cb4'),
  ('italian-a2-practical-8', 'italian-a2-practical-8-078-questa-notizia-mi-fa-davvero-piacere', 8, 'bright', 'Italian', 'it-IT', 'German', 'Questa notizia mi fa davvero piacere.', '{"English":"This news really makes me happy.","German":"Diese Nachricht freut mich wirklich sehr."}', '1604a2400d4ece778f185401c4be358790e1370b49069248dce4bf67b1bc85bd'),
  ('italian-a2-practical-8', 'italian-a2-practical-8-079-stamattina-fa-freddo-prendo-un-caffe', 9, 'bright', 'Italian', 'it-IT', 'German', 'Stamattina fa freddo: prendo un caffè.', '{"English":"This morning it is cold: I will have a coffee.","German":"Heute Morgen ist es kalt: Ich nehme einen Kaffee."}', 'afa20514a9b8e872536529256bcf98ef954cf7e26b14ebdfce8c19c737cc29af'),
  ('italian-a2-practical-8', 'italian-a2-practical-8-080-si-oggi-ce-proprio-il-sole', 10, 'bright', 'Italian', 'it-IT', 'German', 'Sì, oggi c’è proprio il sole.', '{"English":"Yes, the sun is really out today.","German":"Ja, heute scheint wirklich die Sonne."}', '865098a9c0ccf4f2a5728f9f998e93acaf840c4ea7a09b6d451df2ee507d780f'),
  ('italian-a2-practical-9', 'italian-a2-practical-9-081-la-doccia-non-funziona-ho-chiamato-la-reception', 1, 'bright', 'Italian', 'it-IT', 'German', 'La doccia non funziona. Ho chiamato la reception: può mandare qualcuno, per favore?', '{"English":"The shower does not work. I called reception: can you send someone, please?","German":"Die Dusche funktioniert nicht. Ich habe die Rezeption angerufen: Können Sie bitte jemanden schicken?"}', '6e2c866a158a3f1c46a72ef90bd7ad00ae94c873ee5c989645132b8af6180dc2'),
  ('italian-a2-practical-9', 'italian-a2-practical-9-082-ho-ordinato-la-zuppa-ma-non-e-ancora-arrivata', 2, 'bright', 'Italian', 'it-IT', 'German', 'Ho ordinato la zuppa, ma non è ancora arrivata. Può controllare?', '{"English":"I ordered the soup, but it has not arrived yet. Can you check?","German":"Ich habe die Suppe bestellt, aber sie ist noch nicht angekommen. Können Sie nachsehen?"}', '22ad85ff2527baefc27de15511b1129d75b7d55739570eee0ec1a8d6a13ddd57'),
  ('italian-a2-practical-9', 'italian-a2-practical-9-083-ho-chiamato-ieri-ma-la-connessione-non-funziona', 3, 'bright', 'Italian', 'it-IT', 'German', 'Ho chiamato ieri, ma la connessione Wi-Fi non funziona. Può controllare?', '{"English":"I called yesterday, but the Wi-Fi connection does not work. Can you check?","German":"Ich habe gestern angerufen, aber die WLAN-Verbindung funktioniert nicht. Können Sie nachsehen?"}', '47a85461073bd7d8e876182e561fa3eda97c4e4765f9e37757ff608c8ac163b0'),
  ('italian-a2-practical-9', 'italian-a2-practical-9-084-ho-perso-la-chiave-e-non-riesco-ad-aprire-la-porta-puo-mandare-qualcuno', 4, 'bright', 'Italian', 'it-IT', 'German', 'Ho perso la chiave e non riesco ad aprire la porta. Può mandare qualcuno?', '{"English":"I lost the key and cannot open the door. Can you send someone?","German":"Ich habe den Schlüssel verloren und kann die Tür nicht öffnen. Können Sie jemanden schicken?"}', '631a36e61da005ded71e96acc8ecdf413c96e28fe09a0bdfc37a86eeae00c842'),
  ('italian-a2-practical-9', 'italian-a2-practical-9-085-il-taxi-non-e-ancora-arrivato-puo-chiamare-un-altro-taxi', 5, 'bright', 'Italian', 'it-IT', 'German', 'Il taxi non è ancora arrivato. Può chiamare un altro taxi?', '{"English":"The taxi has not arrived yet. Can you call another taxi?","German":"Das Taxi ist noch nicht angekommen. Können Sie ein anderes Taxi rufen?"}', '6ec5e00f41193cde6500c67368be67d8bdd8546e2fa922cf23efe0f0e9906ca2'),
  ('italian-a2-practical-9', 'italian-a2-practical-9-086-ho-pagato-ma-manca-un-euro-di-resto', 6, 'bright', 'Italian', 'it-IT', 'German', 'Ho pagato, ma manca un euro di resto. Può controllare?', '{"English":"I paid, but one euro of change is missing. Can you check?","German":"Ich habe bezahlt, aber ein Euro Wechselgeld fehlt. Können Sie nachsehen?"}', '01892b7c5fad25753e54775c14e34dd1b55def874b4ebf6a36c3da24fba9304f'),
  ('italian-a2-practical-9', 'italian-a2-practical-9-087-ho-comprato-questo-caricatore-oggi-ma-non-funziona', 7, 'bright', 'Italian', 'it-IT', 'German', 'Ho comprato questo caricatore oggi, ma non funziona. Può cambiarlo?', '{"English":"I bought this charger today, but it does not work. Can you exchange it?","German":"Ich habe dieses Ladegerät heute gekauft, aber es funktioniert nicht. Können Sie es umtauschen?"}', 'e392a4d6104319cd2774e756419a9af18a9d82a50a42c3c961c48ffff0b9f5f2'),
  ('italian-a2-practical-9', 'italian-a2-practical-9-088-ho-ordinato-la-zuppa-ma-e-fredda', 8, 'bright', 'Italian', 'it-IT', 'German', 'Ho ordinato la zuppa, ma è fredda. Può scaldare la zuppa, per favore?', '{"English":"I ordered the soup, but it is cold. Can you heat the soup, please?","German":"Ich habe die Suppe bestellt, aber sie ist kalt. Können Sie die Suppe bitte erwärmen?"}', 'd81008f6cae5115a0d3c98a5b1b02f17cb7c89d71f9068bb4294632f4f73b4f0'),
  ('italian-a2-practical-9', 'italian-a2-practical-9-089-ho-dormito-poco-i-vicini-fanno-troppo-rumore', 9, 'bright', 'Italian', 'it-IT', 'German', 'Ho dormito poco: i vicini fanno troppo rumore. Può parlare con loro?', '{"English":"I slept little: the neighbors make too much noise. Can you speak with them?","German":"Ich habe wenig geschlafen: Die Nachbarn machen zu viel Lärm. Können Sie mit ihnen sprechen?"}', 'a439e6b8d7971dce0b7b18bb509ce61a75a8444d4151997a0ff221d2075ffef1'),
  ('italian-a2-practical-9', 'italian-a2-practical-9-090-ho-chiamato-la-reception-ora-funziona-tutto-grazie-mille-per-laiuto', 10, 'bright', 'Italian', 'it-IT', 'German', 'Ho chiamato la reception: ora funziona tutto. Grazie mille per l''aiuto.', '{"English":"I called reception: everything works now. Thank you very much for the help.","German":"Ich habe die Rezeption angerufen: Jetzt funktioniert alles. Vielen Dank für die Hilfe."}', 'd03ebcf91031ba486a2d1b3ba48aa8d27fdd16a39d099553fcc6c665cacc7fb5'),
  ('japanese-a1-practical-1', 'japanese-a1-practical-1-lesson-1-konnichiwa-eigo-dekimasu', 1, 'bright', 'Japanese', 'ja-JP', 'German', 'こんにちは。 英語は できますか。', '{"English":"Hello. Can you speak English?","German":"Guten Tag. Geht Englisch?"}', '9a90e0af7604beb212119c01500eead98ad054757aab1dcd8e989a76632f6ba9'),
  ('japanese-a1-practical-1', 'japanese-a1-practical-1-lesson-2-nihongo-amari-wakarimasen', 2, 'bright', 'Japanese', 'ja-JP', 'German', '日本語は あまり わかりません。', '{"English":"I do not understand Japanese very well.","German":"Ich verstehe Japanisch nicht besonders gut."}', 'a5f909b6af477f8a28ef9b710aa3817dbd93e19458963701731a08fa5b9307bd'),
  ('japanese-a1-practical-1', 'japanese-a1-practical-1-lesson-3-sumimasen-yukkuri-onegaishimasu', 3, 'bright', 'Japanese', 'ja-JP', 'German', 'すみません、 ゆっくり お願いします。', '{"English":"Excuse me, slowly please.","German":"Entschuldigung, bitte langsam."}', '13e112711ef3ad211772db89fc3a29d8c0cb9374d3a5dfa469a350b498072091'),
  ('japanese-a1-practical-1', 'japanese-a1-practical-1-lesson-4-sumimasen-mada-wakarimasen', 4, 'bright', 'Japanese', 'ja-JP', 'German', 'すみません、 まだ わかりません。', '{"English":"Sorry, I still do not understand.","German":"Entschuldigung, ich verstehe es noch nicht."}', '5ac295ee47c01294166c9bf2e0893ff163f828a804560a87d99fce4162ed8688'),
  ('japanese-a1-practical-1', 'japanese-a1-practical-1-lesson-5-korewa-nan-desuka', 5, 'bright', 'Japanese', 'ja-JP', 'German', 'これは 何 ですか。', '{"English":"What is this?","German":"Was ist das?"}', 'c1ed5405f8d17689d82cad41a27b36daed4923df00e30f6e3bd854afcdac977b'),
  ('japanese-a1-practical-1', 'japanese-a1-practical-1-lesson-6-hontoni-domo-arigato', 6, 'bright', 'Japanese', 'ja-JP', 'German', '本当に どうも ありがとうございます。', '{"English":"Thank you very much indeed.","German":"Wirklich, vielen herzlichen Dank."}', '703155f9ad11249c1b14ae8b082a63be9925bf3f32ddbf5b236f65de09275911'),
  ('japanese-a1-practical-1', 'japanese-a1-practical-1-lesson-7-sumimasen-shitsumonga-arimasu', 7, 'bright', 'Japanese', 'ja-JP', 'German', 'すみません、 質問が あります。', '{"English":"Excuse me, I have a question.","German":"Entschuldigung, ich habe eine Frage."}', '68eb3b6e88cf9dc90aae90464c8dbe9c86767702109ced908e1894385e3ef604'),
  ('japanese-a1-practical-1', 'japanese-a1-practical-1-lesson-8-kono-kado-de-ii', 8, 'bright', 'Japanese', 'ja-JP', 'German', 'この カードで いい ですか。', '{"English":"Is this card okay?","German":"Ist diese Karte in Ordnung?"}', '2f730746336dc536dd13689920d45952ce2ba9d9ebafc2eba89f23636ecab9be'),
