  ('japanese-a2-practical-8', 'japanese-a2-practical-8-071-honto-atarashii-shigoto', 1, 'bright', 'Japanese', 'ja-JP', 'German', '本当ですか。 新しい 仕事ですか。 よかったですね!', '{"English":"Really? A new job? That is great!","German":"Wirklich? Ein neuer Job? Das ist ja schön!"}', 'b84407b2a30be6b6eb8ba5ff1a20fb8cfc2d35788eb485ba2fd9c1f5bc4811e5'),
  ('japanese-a2-practical-8', 'japanese-a2-practical-8-072-atsui-natsu-mitai', 2, 'bright', 'Japanese', 'ja-JP', 'German', '今日は 本当に 暑いですね。 夏みたいです。', '{"English":"It is really hot today, is it not? It feels like summer.","German":"Heute ist es wirklich heiß, nicht wahr? Es ist wie im Sommer."}', 'f80b2352e646ef5f1d0f1c7c06a250d7e36edac3e94e4aa937e7387435378f20'),
  ('japanese-a2-practical-8', 'japanese-a2-practical-8-073-nemui-osoku-nemashita', 3, 'bright', 'Japanese', 'ja-JP', 'German', 'ちょっと 眠いです。 昨日 遅く 寝ました。', '{"English":"I am a little sleepy. I went to bed late yesterday.","German":"Ich bin etwas müde. Gestern bin ich spät schlafen gegangen."}', '909258ddfc93e1bb739d238d4d69799ab15bcc34bbb4889f3072f095aa63e7b0'),
