  ('korean-a2-practical-7', 'korean-a2-practical-7-067-hanguk-eumsikjeom-eodiyeyo', 7, 'bright', 'Korean', 'ko-KR', 'German', '호텔 근처에 한국 음식점이 있어요?', '{"English":"Is there a Korean restaurant near the hotel?","German":"Gibt es in der Nähe des Hotels ein koreanisches Restaurant?"}', '9dd95b5e531beedaf8472f9d78450a9fdb772a9749412e2ba980dd04debeefbc'),
  ('korean-a2-practical-7', 'korean-a2-practical-7-068-bame-gwangjangeul-chucheonhaeyo', 8, 'bright', 'Korean', 'ko-KR', 'German', '밤에 광장이 정말 예뻐요. 꼭 가 보세요.', '{"English":"The square is really pretty at night. Be sure to go.","German":"Nachts ist der Platz wirklich schön. Gehen Sie unbedingt hin."}', 'bd8ed7009f3be2d9d4032e1c4953b2ec93f65ed5acf0776d049aee8781b6131e'),
