  ('polish-a2-practical-1', 'polish-a2-practical-1-001-poprosze-mala-kawe-jak-zwykle', 1, 'bright', 'Polish', 'pl-PL', 'German', 'Tak, poproszę małą kawę, jak zwykle.', '{"English":"Yes, a small coffee as usual, please.","German":"Ja, einen kleinen Kaffee, wie immer, bitte."}', 'ceb3eaf13a253134b8f730e92bff9f3f17450fc86df0611f45ee0864f6a146c7'),
  ('polish-a2-practical-1', 'polish-a2-practical-1-002-na-wynos-ile-razem-kosztuje', 2, 'bright', 'Polish', 'pl-PL', 'German', 'Na wynos, poproszę. Ile to razem kosztuje?', '{"English":"To go, please. How much does that cost altogether?","German":"Zum Mitnehmen, bitte. Wie viel kostet das insgesamt?"}', '7352149a4b3e0e158ceb00773641078dbbf2fb0d47564c3519c8b7ad5f08da3e'),
  ('polish-a2-practical-1', 'polish-a2-practical-1-003-poprosze-doladowanie-za-trzydziesci', 3, 'bright', 'Polish', 'pl-PL', 'German', 'Poproszę doładowanie. Czy jest takie za trzydzieści złotych?', '{"English":"I would like a top-up. Do you have one for thirty zloty?","German":"Ich hätte gern eine Guthabenaufladung. Gibt es so eine für dreißig Złoty?"}', '8c4dcf4afd2643a7836786e164dbc8de31eda7176cfae4997918de3647162fb5'),
  ('polish-a2-practical-1', 'polish-a2-practical-1-004-ile-minut-trzeba-isc-pieszo', 4, 'bright', 'Polish', 'pl-PL', 'German', 'Ile minut trzeba iść stąd pieszo?', '{"English":"How many minutes does it take to walk from here?","German":"Wie viele Minuten muss man von hier zu Fuß gehen?"}', 'dec9e1a01a54d1054e36401aa438835b064eaf4141739f2e347e8cd76d109c4c'),
  ('polish-a2-practical-1', 'polish-a2-practical-1-005-wszystko-w-porzadku-poprosze-rachunek', 5, 'bright', 'Polish', 'pl-PL', 'German', 'Tak, wszystko jest w porządku. Poproszę rachunek.', '{"English":"Yes, everything is fine. The bill, please.","German":"Ja, alles ist in Ordnung. Die Rechnung, bitte."}', '560d1748450fd974949ee0c99b4e5413ef894e24b84f9ed3df0e52687f7f5720'),
  ('polish-a2-practical-1', 'polish-a2-practical-1-006-mam-rezerwacje-na-nazwisko-nowak', 6, 'bright', 'Polish', 'pl-PL', 'German', 'Mam rezerwację na nazwisko Nowak.', '{"English":"I have a reservation under the name Nowak.","German":"Ich habe eine Reservierung auf den Namen Nowak."}', '9f709cbf578676c7143197ff8215df6973cc4e0d62060413c17a88a80cca7f69'),
  ('polish-a2-practical-1', 'polish-a2-practical-1-007-nie-to-wszystko-ile-place', 7, 'bright', 'Polish', 'pl-PL', 'German', 'Nie, to wszystko. Ile razem płacę?', '{"English":"No, that is everything. How much do I pay altogether?","German":"Nein, das ist alles. Wie viel zahle ich insgesamt?"}', '593ebce96766fc13ecb86ea4e3b8290cdd9ef1842c98984baad00a04bce7c3a0'),
  ('polish-a2-practical-1', 'polish-a2-practical-1-008-przystanek-na-koncu-ulicy', 8, 'bright', 'Polish', 'pl-PL', 'German', 'Przystanek tramwajowy jest na końcu tej ulicy.', '{"English":"The tram stop is at the end of this street.","German":"Die Straßenbahnhaltestelle ist am Ende dieser Straße."}', '4ced6d7e8c8d97f63a3a925d0c1b9a55ac9a2bfdb939d3b591bef91582790159'),
  ('polish-a2-practical-1', 'polish-a2-practical-1-009-pol-kilo-jablek-i-cytryny', 9, 'bright', 'Polish', 'pl-PL', 'German', 'Poproszę pół kilo jabłek i jeszcze dwie cytryny.', '{"English":"I would like half a kilo of apples and two lemons as well.","German":"Ich hätte gern ein halbes Kilo Äpfel und noch zwei Zitronen."}', 'ccb84c502022718ffebcdf891cff3c432e543be2ffb7b4e97c4b65b923324e7e'),
  ('polish-a2-practical-1', 'polish-a2-practical-1-010-troche-znam-okolice-wokol-domu', 10, 'bright', 'Polish', 'pl-PL', 'German', 'Tak, już trochę znam okolicę wokół domu.', '{"English":"Yes, I already know the area around the house a little.","German":"Ja, ich kenne die Gegend um das Haus schon ein wenig."}', '7d83de9ee46a90d5410a28492747df7760303b08dcb37855022270f522a5160a'),
  ('polish-a2-practical-10', 'polish-a2-practical-10-091-jestem-z-niemiec-mieszkam-tutaj', 1, 'bright', 'Polish', 'pl-PL', 'German', 'Jestem z Niemiec i teraz mieszkam tutaj.', '{"English":"I am from Germany, and I live here now.","German":"Ich komme aus Deutschland und wohne jetzt hier."}', '508ca0b8972adc082dd582ed416e221de29d47462ae3d816c56d10144eafe186'),
  ('polish-a2-practical-10', 'polish-a2-practical-10-092-pracuje-w-biurze-w-centrum', 2, 'bright', 'Polish', 'pl-PL', 'German', 'Pracuję w biurze w centrum miasta.', '{"English":"I work in an office in the city center.","German":"Ich arbeite in einem Büro im Stadtzentrum."}', 'c41275b36d7175c21b971364b849b71cf907c5c0cbbea590d28a0870429118a8'),
  ('polish-a2-practical-10', 'polish-a2-practical-10-093-ucze-sie-polskiego-chce-mowic', 3, 'bright', 'Polish', 'pl-PL', 'German', 'Uczę się polskiego, bo chcę mówić po polsku.', '{"English":"I am learning Polish because I want to speak Polish.","German":"Ich lerne Polnisch, weil ich Polnisch sprechen möchte."}', 'b16805d703c2aa7626f6699b434869ed74a4657f9ed4ae249b64627d2dc18a97'),
  ('polish-a2-practical-10', 'polish-a2-practical-10-094-jestem-tu-od-dwoch-tygodni', 4, 'bright', 'Polish', 'pl-PL', 'German', 'Jestem tu od dwóch tygodni. Już trochę znam miasto.', '{"English":"I have been here for two weeks. I already know the city a little.","German":"Ich bin seit zwei Wochen hier. Ich kenne die Stadt schon ein wenig."}', 'ce82d9fbe0b382c771d64afcf84bf384387518cd9a42d4992725e19ad5cc0906'),
  ('polish-a2-practical-10', 'polish-a2-practical-10-095-moja-rodzina-jest-w-niemczech', 5, 'bright', 'Polish', 'pl-PL', 'German', 'Moja rodzina mieszka w Niemczech. Dzwonię do nich co tydzień.', '{"English":"My family lives in Germany. I call them every week.","German":"Meine Familie lebt in Deutschland. Ich rufe sie jede Woche an."}', '72e4886adbbf56beccaf5335d758d7db802802b49bb7342bfe0187be641c6111'),
  ('polish-a2-practical-10', 'polish-a2-practical-10-096-lubie-gotowac-i-chodzic-na-spacery', 6, 'bright', 'Polish', 'pl-PL', 'German', 'Lubię gotować i chodzić na spacery po okolicy.', '{"English":"I like cooking and going for walks around the neighborhood.","German":"Ich koche gern und gehe gern in der Gegend spazieren."}', '72d422a21af97307e6a71569c98a52f6a27019f1749d95f71c05a58532acebcf'),
  ('polish-a2-practical-10', 'polish-a2-practical-10-097-rano-pracuje-wieczorem-ucze-sie', 7, 'bright', 'Polish', 'pl-PL', 'German', 'Rano pracuję, a wieczorem uczę się polskiego.', '{"English":"I work in the morning, and I study Polish in the evening.","German":"Morgens arbeite ich, und abends lerne ich Polnisch."}', '40bdbe1a1a24eea7925f51bb9b6d46ee99f89de75a8c5e6e2b48f3b938ff5aa6'),
  ('polish-a2-practical-10', 'polish-a2-practical-10-098-rozumiem-prawie-wszystko-mowie-powoli', 8, 'bright', 'Polish', 'pl-PL', 'German', 'Rozumiem prawie wszystko, ale mówię jeszcze dość powoli.', '{"English":"I understand almost everything, but I still speak quite slowly.","German":"Ich verstehe fast alles, aber ich spreche noch ziemlich langsam."}', '252be4854a431a1ece8cba8f9516484a21c069516a68b3e9f4057169b8e1fd0a'),
  ('polish-a2-practical-10', 'polish-a2-practical-10-099-duzo-sie-nauczylem-wroce', 9, 'bright', 'Polish', 'pl-PL', 'German', 'Dużo się tutaj nauczyłem. W przyszłym roku wrócę.', '{"English":"I learned a lot here. I will come back next year.","German":"Ich habe hier viel gelernt. Nächstes Jahr komme ich zurück."}', '70817c155de67b1e9510d7f68c5e3fdfddcf96aa100335d824a0cc8982e6c88b'),
  ('polish-a2-practical-10', 'polish-a2-practical-10-100-dziekuje-za-te-tygodnie', 10, 'bright', 'Polish', 'pl-PL', 'German', 'Dziękuję za te tygodnie. To dla mnie ważne. Do zobaczenia!', '{"English":"Thank you for these weeks. That means a lot to me. See you!","German":"Danke für diese Wochen. Das ist mir wichtig. Bis zum nächsten Mal!"}', 'f3ac8d490a4b246806119ba7cc793a4c38c49046dae1940114f44ab18c176b92'),
  ('polish-a2-practical-2', 'polish-a2-practical-2-011-poprosze-te-jablka-bo-tansze', 1, 'bright', 'Polish', 'pl-PL', 'German', 'Poproszę te jabłka, bo są tańsze.', '{"English":"I would like these apples because they are cheaper.","German":"Ich hätte gern diese Äpfel, weil sie günstiger sind."}', '55d4ac69e87f5f3e58bd335bd3c4f545c07885e2a317e8872c0cbaab2c900c08'),
  ('polish-a2-practical-2', 'polish-a2-practical-2-012-dzisiaj-mrozona-bo-goraco', 2, 'bright', 'Polish', 'pl-PL', 'German', 'Dzisiaj poproszę mrożoną, bo jest gorąco.', '{"English":"Today I would like an iced coffee because it is hot.","German":"Heute nehme ich einen Eiskaffee, weil es heiß ist."}', 'e53d0069de1fca8476c0c9b644307b165b7e1e87609a58a7fdb4127190e511d6'),
  ('polish-a2-practical-2', 'polish-a2-practical-2-013-wole-granatowa-bo-rozmiar-lezy', 3, 'bright', 'Polish', 'pl-PL', 'German', 'Wolę granatową, bo lepiej na mnie leży.', '{"English":"I prefer the navy one because it fits me better.","German":"Ich bevorzuge die dunkelblaue, weil sie mir besser passt."}', '077e3ef499d90a0d188d08fa1f491b454b405971f35dd6ab66311d29202af155'),
  ('polish-a2-practical-2', 'polish-a2-practical-2-014-wole-zupe-bo-lzejsza', 4, 'bright', 'Polish', 'pl-PL', 'German', 'Dzisiaj wolę zupę, bo jest lżejsza.', '{"English":"Today I prefer the soup because it is lighter.","German":"Heute bevorzuge ich die Suppe, weil sie leichter ist."}', 'cf4af5761fc0ede29cc4521353e81fbd2d87ad0dcb98857dbb257879ebc09443'),
  ('polish-a2-practical-2', 'polish-a2-practical-2-015-ten-razowy-bo-bardziej-chrupiacy', 5, 'bright', 'Polish', 'pl-PL', 'German', 'Poproszę ten razowy, bo dziś jest bardziej chrupiący.', '{"English":"I would like the wholegrain one because it is crunchier today.","German":"Ich hätte gern das Vollkornbrot, weil es heute knuspriger ist."}', '9f5c8b8acba9dd2701a920ce28735ca064e30b147035adb2a7a69d59d76a23bc'),
  ('polish-a2-practical-2', 'polish-a2-practical-2-016-wole-tramwaj-bo-jedzie-szybciej', 6, 'bright', 'Polish', 'pl-PL', 'German', 'Wolę tramwaj, bo jedzie szybciej.', '{"English":"I prefer the tram because it goes faster.","German":"Ich bevorzuge die Straßenbahn, weil sie schneller fährt."}', '0321be52b1eac8047b8b218def5915fb7cfa965ef37e53109a67af032ad2f92d'),
  ('polish-a2-practical-2', 'polish-a2-practical-2-017-pokoj-od-podworza-spi-sie-spokojniej', 7, 'bright', 'Polish', 'pl-PL', 'German', 'Wolę pokój od podwórza, bo śpi się tam spokojniej.', '{"English":"I prefer the courtyard room because one sleeps more peacefully there.","German":"Ich bevorzuge das Zimmer zum Innenhof, weil man dort ruhiger schläft."}', 'ef3f2b238cd7deb5e7def67de6d782455c790352e5c3425b27907eee6b184850'),
  ('polish-a2-practical-2', 'polish-a2-practical-2-018-te-buty-bo-sa-wygodniejsze', 8, 'bright', 'Polish', 'pl-PL', 'German', 'Poproszę te buty, bo są wygodniejsze.', '{"English":"I would like these shoes because they are more comfortable.","German":"Ich hätte gern diese Schuhe, weil sie bequemer sind."}', '86dd0dc100c2bdbc5739c7f6bfbfc3f4680d97de0507e4d2f37869a7b1a52c0c'),
  ('polish-a2-practical-2', 'polish-a2-practical-2-019-mniejsza-butelke-bo-kosztuje-mniej', 9, 'bright', 'Polish', 'pl-PL', 'German', 'Poproszę mniejszą butelkę, bo kosztuje mniej.', '{"English":"I would like the smaller bottle because it costs less.","German":"Ich hätte gern die kleinere Flasche, weil sie weniger kostet."}', '4d9ce9979ba13ed6a826276b6a3476b7fa94f80fb2553174f2c8a84375e7c08e'),
  ('polish-a2-practical-2', 'polish-a2-practical-2-020-wole-te-kawiarnie-bo-blisko-cicho', 10, 'bright', 'Polish', 'pl-PL', 'German', 'Wolę tę kawiarnię, bo jest blisko i jest tam cicho.', '{"English":"I prefer this cafe because it is close and quiet there.","German":"Ich bevorzuge dieses Café, weil es nah ist und man dort Ruhe hat."}', '4f4481b8fe4d0d6930b458de31af582a7163ef690295ec1ea95f408ab633fcb9'),
  ('polish-a2-practical-3', 'polish-a2-practical-3-021-juz-zaplacilam-wszystko-gotowe', 1, 'bright', 'Polish', 'pl-PL', 'German', 'Już zapłaciłam kartą przy kasie. Wszystko jest gotowe.', '{"English":"I already paid by card at the register. Everything is ready.","German":"Ich habe schon mit Karte an der Kasse bezahlt. Alles ist fertig."}', 'a717645c96b9660fe9bdb95961227952aaa103881ea5b68fb1f61abcd97603d8'),
  ('polish-a2-practical-3', 'polish-a2-practical-3-022-przyjechalam-wczoraj-teraz-mam-pokoj', 2, 'bright', 'Polish', 'pl-PL', 'German', 'Przyjechałam wczoraj wieczorem, teraz mam już pokój.', '{"English":"I arrived yesterday evening, and now I already have a room.","German":"Ich bin gestern Abend angekommen, jetzt habe ich schon ein Zimmer."}', 'f0d261ffd15b205d182dd096f09450998d15a06aed1f1d6b3ee271591103eb76'),
  ('polish-a2-practical-3', 'polish-a2-practical-3-023-juz-zamowilam-zupe-teraz-czekam', 3, 'bright', 'Polish', 'pl-PL', 'German', 'Już zamówiłam zupę, teraz czekam przy stoliku.', '{"English":"I already ordered the soup, and now I am waiting at the table.","German":"Ich habe die Suppe schon bestellt, jetzt warte ich am Tisch."}', '898de716f5d542f2f083bdae0928cde7484b5bc4474acc485d0b00f22a84ff11'),
  ('polish-a2-practical-3', 'polish-a2-practical-3-024-dzis-rano-kupilam-pomidory', 4, 'bright', 'Polish', 'pl-PL', 'German', 'Dziś rano kupiłam pomidory na targu.', '{"English":"This morning I bought tomatoes at the market.","German":"Heute Morgen habe ich Tomaten auf dem Markt gekauft."}', '2acacc1320aa2e81bf1a54736c746f7a1724556b06dac21bd32baa4c43236c95'),
  ('polish-a2-practical-3', 'polish-a2-practical-3-025-wczesniej-zrobilam-zakupy', 5, 'bright', 'Polish', 'pl-PL', 'German', 'Wcześniej zrobiłam zakupy, teraz niczego nie potrzebuję.', '{"English":"I did my shopping earlier; now I do not need anything.","German":"Ich habe die Einkäufe vorhin schon erledigt, jetzt brauche ich nichts mehr."}', '427ade079d3ea2d98679bfb7e74777e4705150c3de62ac06a990ba2e86e305b8'),
  ('polish-a2-practical-3', 'polish-a2-practical-3-026-wczoraj-spalam-zle-dzis-lepiej', 6, 'bright', 'Polish', 'pl-PL', 'German', 'Wczoraj źle spałam, ale dziś czuję się lepiej.', '{"English":"I slept badly yesterday, but today I feel better.","German":"Gestern habe ich schlecht geschlafen, aber heute fühle ich mich besser."}', '45a51e5fd0b1d0b9c41da79b5f23df6537bbee289273600fc8297290bce66b3b'),
  ('polish-a2-practical-3', 'polish-a2-practical-3-027-juz-sprobowalam-lokalnego-dania', 7, 'bright', 'Polish', 'pl-PL', 'German', 'Już spróbowałam lokalnego dania i naprawdę mi smakuje.', '{"English":"I already tried the local dish, and I really like it.","German":"Ich habe das lokale Gericht schon probiert und es schmeckt mir wirklich."}', '35834f879f0e8ba3b757d13557c1301525d3ac9b9f07cf4686016fd6cb2a5b11'),
  ('polish-a2-practical-3', 'polish-a2-practical-3-028-jeszcze-nie-zobaczylam-starego-miasta', 8, 'bright', 'Polish', 'pl-PL', 'German', 'Jeszcze nie zobaczyłam starego miasta, szukam dobrej trasy.', '{"English":"I have not seen the old town yet, and I am looking for a good route.","German":"Ich habe die Altstadt noch nicht gesehen und suche eine gute Route."}', 'b966b985cd706b06ba9eda8351bf9bd8154955935cc7743ecf9215913cbedf77'),
  ('polish-a2-practical-3', 'polish-a2-practical-3-029-bylam-wczoraj-w-muzeum', 9, 'bright', 'Polish', 'pl-PL', 'German', 'Byłam wczoraj w muzeum, dziś zwiedzam stare miasto.', '{"English":"I was at the museum yesterday; today I am touring the old town.","German":"Ich war gestern im Museum, heute besichtige ich die Altstadt."}', '7d106381d3f7887a18f81dc7941d983527f1549a5c7f24f637719d51be51e777'),
  ('polish-a2-practical-3', 'polish-a2-practical-3-030-w-tym-tygodniu-zrobilam-duzo', 10, 'bright', 'Polish', 'pl-PL', 'German', 'W tym tygodniu zrobiłam dużo, teraz odpoczywam.', '{"English":"I did a lot this week, and now I am resting.","German":"Diese Woche habe ich viel gemacht, jetzt ruhe ich mich aus."}', '9ef620167cd6caeb5069a1b09e677b76d8d2d6ba5b582720c867eb04d7dea739'),
  ('polish-a2-practical-4', 'polish-a2-practical-4-031-chetnie-spotkamy-sie-o-szostej', 1, 'bright', 'Polish', 'pl-PL', 'German', 'Chętnie. Spotkamy się w piątek o szóstej?', '{"English":"I’d love to. Shall we meet at six on Friday?","German":"Gern. Treffen wir uns am Freitag um sechs?"}', 'b986869a9229e6a9c5b016ce84258141313e2d009480b546892e7bbe27df5a1b'),
  ('polish-a2-practical-4', 'polish-a2-practical-4-032-jutro-pojde-do-muzeum', 2, 'bright', 'Polish', 'pl-PL', 'German', 'Jutro pójdę do muzeum po pracy.', '{"English":"Tomorrow I will go to the museum after work.","German":"Morgen gehe ich nach der Arbeit ins Museum."}', '6eefde50bd4c69b63ef3b1e3227d6cf096576991052f20e8a3c432ec2aedafa0'),
  ('polish-a2-practical-4', 'polish-a2-practical-4-033-moze-pojdziemy-do-kina', 3, 'bright', 'Polish', 'pl-PL', 'German', 'Może pójdziemy do kina w piątek?', '{"English":"Maybe we could go to the cinema on Friday?","German":"Vielleicht gehen wir am Freitag ins Kino?"}', 'e198cf7fbfc4551085f3eec1d5f76d28063717d66fa3943b6d8948f4d1f5d711'),
  ('polish-a2-practical-4', 'polish-a2-practical-4-034-spotkamy-sie-o-osmej-na-rynku', 4, 'bright', 'Polish', 'pl-PL', 'German', 'Spotkamy się o ósmej na rynku.', '{"English":"We will meet at eight in the market square.","German":"Wir treffen uns um acht auf dem Marktplatz."}', '2bf64a5038724a65c3e1f048fa6fd4030dc743c2dca47035de67b2b669a85217'),
  ('polish-a2-practical-4', 'polish-a2-practical-4-035-mozemy-przelozyc-na-sobote', 5, 'bright', 'Polish', 'pl-PL', 'German', 'Możemy przełożyć spotkanie na sobotę?', '{"English":"Can we move the meeting to Saturday?","German":"Können wir das Treffen auf Samstag verschieben?"}', '0b6592578da9b1664748da893197fd2805a44870992fa146ea93f9839ea5979c'),
  ('polish-a2-practical-4', 'polish-a2-practical-4-036-nie-moge-bo-mam-duzo-pracy', 6, 'bright', 'Polish', 'pl-PL', 'German', 'Nie mogę dzisiaj, bo mam dużo pracy.', '{"English":"I cannot today because I have a lot of work.","German":"Ich kann heute nicht, weil ich viel Arbeit habe."}', '7fc43408dd58f5ec66ecb60d4cc030b68eb8eb67a09b573c0402f3156481c732'),
  ('polish-a2-practical-4', 'polish-a2-practical-4-037-zapraszam-cie-na-kolacje', 7, 'bright', 'Polish', 'pl-PL', 'German', 'Zapraszam cię na kolację w niedzielę.', '{"English":"I am inviting you to dinner on Sunday.","German":"Ich lade dich am Sonntag zum Abendessen ein."}', '9b94efa4551fc4b83f05cd12d83d3834cceb4486945fb69b656401d4c06bedcb'),
  ('polish-a2-practical-4', 'polish-a2-practical-4-038-spoznie-sie-piec-minut', 8, 'bright', 'Polish', 'pl-PL', 'German', 'Spóźnię się o pięć minut, przepraszam.', '{"English":"I will be five minutes late, sorry.","German":"Ich verspäte mich um fünf Minuten, entschuldige."}', '2bdaeb55e7cecba61f1a6884524eb19c0831b0b60c2ff2de0029e8c6b095ff88'),
  ('polish-a2-practical-4', 'polish-a2-practical-4-039-czyli-w-sobote-o-osmej', 9, 'bright', 'Polish', 'pl-PL', 'German', 'Czyli w sobotę o ósmej na rynku, tak?', '{"English":"So Saturday at eight in the market square, right?","German":"Also am Samstag um acht auf dem Marktplatz, ja?"}', '4a320ea55713ce4ccfca40206644131b321d2dc73499286f587f33304065a9a0'),
  ('polish-a2-practical-4', 'polish-a2-practical-4-040-w-weekend-zrobie-mala-wycieczke', 10, 'bright', 'Polish', 'pl-PL', 'German', 'W weekend zrobię małą wycieczkę za miasto.', '{"English":"At the weekend I will take a short trip out of town.","German":"Am Wochenende mache ich einen kleinen Ausflug ins Umland."}', '23facb1b9383234666df8748a2ada2c89173bf8ee153a1c453e95699c4506faa'),
  ('polish-a2-practical-5', 'polish-a2-practical-5-041-przepraszam-zamowilam-herbate', 1, 'bright', 'Polish', 'pl-PL', 'German', 'Przepraszam, zamówiłam herbatę, nie kawę.', '{"English":"Excuse me, I ordered tea, not coffee.","German":"Entschuldigung, ich habe Tee bestellt, nicht Kaffee."}', '0e088ae5a1d9eb2ba81fcf12d92d9676860299b48135fa725375d90849f49c56'),
  ('polish-a2-practical-5', 'polish-a2-practical-5-042-bluzka-za-mala-czy-mozna-zamienic', 2, 'bright', 'Polish', 'pl-PL', 'German', 'Przepraszam, ta bluzka jest za mała. Czy można ją zamienić?', '{"English":"Excuse me, this blouse is too small. Can it be exchanged?","German":"Entschuldigung, diese Bluse ist zu klein. Kann man sie umtauschen?"}', '7aa0a34df5035bef4ee24cc8020f9f402dafaf278cccc7ce34a0222fec32b6fc'),
  ('polish-a2-practical-5', 'polish-a2-practical-5-043-raczej-wode-niegazowana', 3, 'bright', 'Polish', 'pl-PL', 'German', 'Poproszę raczej wodę niegazowaną zamiast gazowanej.', '{"English":"I would prefer still water instead of sparkling water.","German":"Ich hätte lieber stilles Wasser statt Wasser mit Kohlensäure."}', 'd419855f6a234a4de07ef2c6950c36a537823ac760654831e95a41a2688462b5'),
  ('polish-a2-practical-5', 'polish-a2-practical-5-044-nie-te-tylko-tamte-pomidory', 4, 'bright', 'Polish', 'pl-PL', 'German', 'Nie te, tylko tamte pomidory, poproszę.', '{"English":"Not these, the tomatoes over there, please.","German":"Nicht diese, sondern die dortigen Tomaten, bitte."}', 'f5db3a6fa971a3608e53cf89b5980785b7cf1ad91d8109ddb2d3eca468a88a42'),
  ('polish-a2-practical-5', 'polish-a2-practical-5-045-zmienic-pokoj-za-duzo-halasu', 5, 'bright', 'Polish', 'pl-PL', 'German', 'Czy można zmienić pokój? Jest tu za dużo hałasu.', '{"English":"Can I change rooms? There is too much noise here.","German":"Kann man das Zimmer wechseln? Hier ist zu viel Lärm."}', 'f8ed2ccee9a420bc9c49afac4a1c12476bb56b32077e0c6f61a7ee6e4077c56b'),
  ('polish-a2-practical-5', 'polish-a2-practical-5-046-poprosze-tylko-to-opakowanie', 6, 'bright', 'Polish', 'pl-PL', 'German', 'Nie, dziękuję. Poproszę tylko to opakowanie.', '{"English":"No, thank you. I would just like this pack.","German":"Nein, danke. Ich hätte nur diese Packung gern."}', '1b1567338ed5ef9371d72e9a36f5c3c1ee7d440c76fdbc40fa41c988f25e3349'),
  ('polish-a2-practical-5', 'polish-a2-practical-5-047-cos-sie-nie-zgadza-na-rachunku', 7, 'bright', 'Polish', 'pl-PL', 'German', 'Przepraszam, coś się chyba nie zgadza na rachunku.', '{"English":"Excuse me, something does not seem right on the bill.","German":"Entschuldigung, auf der Rechnung stimmt wohl etwas nicht."}', '60287748b2023bf53039cb9238c3656c4690b5b80b303fdd22de38036d9caeb2'),
  ('polish-a2-practical-5', 'polish-a2-practical-5-048-czy-jest-inne-mniejsze-opakowanie', 8, 'bright', 'Polish', 'pl-PL', 'German', 'Czy jest inne, mniejsze opakowanie?', '{"English":"Is there a different, smaller pack?","German":"Gibt es eine andere, kleinere Packung?"}', 'af519a37ea0b2d51c77ecc41cf529a008b6342aa64e29b4c72a28072db5c5986'),
  ('polish-a2-practical-5', 'polish-a2-practical-5-049-na-dworzec-nie-do-centrum', 9, 'bright', 'Polish', 'pl-PL', 'German', 'Na dworzec, nie do centrum, poproszę.', '{"English":"To the station, not the center, please.","German":"Zum Bahnhof, nicht ins Zentrum, bitte."}', '32ca2fd69195673bedbf6568c435776665174fe9a0362c78afd9c0588e89ef7c'),
  ('polish-a2-practical-5', 'polish-a2-practical-5-050-niestety-dzisiaj-nie-moge', 10, 'bright', 'Polish', 'pl-PL', 'German', 'Dziękuję, ale niestety dzisiaj nie mogę.', '{"English":"Thank you, but unfortunately I cannot today.","German":"Danke, aber heute kann ich leider nicht."}', '1d215121a4c17325edcc72515280fc910520559b3041b82df04187f4d434cde1'),
  ('polish-a2-practical-6', 'polish-a2-practical-6-051-oddaje-ubrania-do-prania', 1, 'bright', 'Polish', 'pl-PL', 'German', 'Chcę oddać te ubrania do prania. Kiedy można je odebrać?', '{"English":"I would like to drop off these clothes for washing. When can I pick them up?","German":"Ich möchte diese Kleidung zum Waschen abgeben. Wann kann ich sie abholen?"}', '08a5785b92ace470146db2313184da1d5ddf21d5b2fc90aeb6f32cca361f7083'),
  ('polish-a2-practical-6', 'polish-a2-practical-6-052-potrzebuje-naprawy-telefonu', 2, 'bright', 'Polish', 'pl-PL', 'German', 'Potrzebuję naprawy telefonu. Ekran nie działa.', '{"English":"I need the phone repaired. The screen does not work.","German":"Mein Telefon muss repariert werden. Der Bildschirm funktioniert nicht."}', '4e82010a76506cda194d0785eaf0741cce6e69885a52e3d4f1b31bc7527aed0f'),
  ('polish-a2-practical-6', 'polish-a2-practical-6-053-doladowanie-za-trzydziesci-zlotych', 3, 'bright', 'Polish', 'pl-PL', 'German', 'Potrzebuję doładowania za trzydzieści złotych.', '{"English":"I need a top-up for thirty zloty.","German":"Ich brauche ein Guthaben für dreißig Złoty."}', 'b06251d0fa631bde4f1299e7b5e2d039e288714473811e5d501874066ea9e368'),
  ('polish-a2-practical-6', 'polish-a2-practical-6-054-chce-sie-umowic-na-czwartek', 4, 'bright', 'Polish', 'pl-PL', 'German', 'Chcę się umówić na czwartek. Czy jest wolny termin?', '{"English":"I want to make an appointment for Thursday. Is there an available slot?","German":"Ich möchte einen Termin für Donnerstag vereinbaren. Ist ein Termin frei?"}', '5a61f27532b72570fbf95c0f75dfed0220494c6ae1a19c24306271ef1e0cc2ac'),
  ('polish-a2-practical-6', 'polish-a2-practical-6-055-chce-dorobic-klucz', 5, 'bright', 'Polish', 'pl-PL', 'German', 'Chcę dorobić klucz. Na kiedy może być gotowy?', '{"English":"I want to have a key copied. When can it be ready?","German":"Ich möchte einen Schlüssel nachmachen lassen. Bis wann kann er fertig sein?"}', '91c9a4fe571ca8fa14db34863be8c680511601e42ed380d162e52f72f90c2ca6'),
  ('polish-a2-practical-6', 'polish-a2-practical-6-056-mam-numer-odbioru-paczki', 6, 'bright', 'Polish', 'pl-PL', 'German', 'Mam numer odbioru. Chcę odebrać paczkę.', '{"English":"I have a pickup number. I want to collect a package.","German":"Ich habe eine Abholnummer. Ich möchte ein Paket abholen."}', '9e95519367b6fbee9e081aad8c42006069b56d4a12cb9de7671e9b73340d6d5d'),
  ('polish-a2-practical-6', 'polish-a2-practical-6-057-chce-wynajac-rower-na-dwa-dni', 7, 'bright', 'Polish', 'pl-PL', 'German', 'Chcę wynająć rower na dwa dni.', '{"English":"I want to rent a bike for two days.","German":"Ich möchte ein Fahrrad für zwei Tage mieten."}', '870d7932c768a154bac298d7fadd5a222438d4df5f872229e432eb3ae1de1563'),
  ('polish-a2-practical-6', 'polish-a2-practical-6-058-do-ktorej-otwarte-w-sobote', 8, 'bright', 'Polish', 'pl-PL', 'German', 'Do której jest otwarte w sobotę?', '{"English":"How late is it open on Saturday?","German":"Bis wann ist am Samstag geöffnet?"}', '77376dbd74a41be3e5f9e89d7c2d1ac205b0a76703fc722fa6262106e6f9b433'),
  ('polish-a2-practical-6', 'polish-a2-practical-6-059-telefon-gotowy-do-odbioru', 9, 'bright', 'Polish', 'pl-PL', 'German', 'Czy telefon jest już gotowy do odbioru?', '{"English":"Is the phone ready for pickup yet?","German":"Ist das Telefon schon zur Abholung bereit?"}', 'a42c06debead2386ae7e7dabce5927bd1d01f1db9d0622a35baa8a819f12f108'),
  ('polish-a2-practical-6', 'polish-a2-practical-6-060-w-takim-razie-do-zobaczenia', 10, 'bright', 'Polish', 'pl-PL', 'German', 'Dziękuję. W takim razie do zobaczenia w czwartek.', '{"English":"Thank you. See you on Thursday then.","German":"Danke. Dann bis Donnerstag."}', 'b1a8c91489a3ddcac5fe9a9456a5ca618a9a670c838ab0b8af95bc36567fa146'),
  ('polish-a2-practical-7', 'polish-a2-practical-7-061-co-pani-poleca-na-obiad', 1, 'bright', 'Polish', 'pl-PL', 'German', 'Jeszcze nie wiem. Co pani poleca na obiad?', '{"English":"I do not know yet. What do you recommend for lunch?","German":"Ich weiß es noch nicht. Was empfehlen Sie zum Mittagessen?"}', 'e1921c96722736b1a2f7d6e4f90464e774a5fe3e31169682de3038c00eb55644'),
  ('polish-a2-practical-7', 'polish-a2-practical-7-062-brzmi-dobrze-wezme-to-danie', 2, 'bright', 'Polish', 'pl-PL', 'German', 'Brzmi dobrze, wezmę to danie.', '{"English":"That sounds good; I will take this dish.","German":"Das klingt gut, ich nehme dieses Gericht."}', 'b74382dfed34956509366e19fcdaf5776777ac6666f090959c2292aabf1cb9e9'),
  ('polish-a2-practical-7', 'polish-a2-practical-7-063-ktora-dzielnice-pani-poleca', 3, 'bright', 'Polish', 'pl-PL', 'German', 'Którą dzielnicę pani poleca na spokojny spacer?', '{"English":"Which neighborhood do you recommend for a quiet walk?","German":"Welches Viertel empfehlen Sie für einen ruhigen Spaziergang?"}', 'c8313a94890e275a0b280af450078418e9daa0635b2e5c5cb29b651e421d3d8f'),
  ('polish-a2-practical-7', 'polish-a2-practical-7-064-park-cichy-ladny-obok-rzeki', 4, 'bright', 'Polish', 'pl-PL', 'German', 'Ten park jest cichy i ładny. Leży obok rzeki.', '{"English":"This park is quiet and pretty. It lies beside the river.","German":"Dieser Park ist ruhig und schön. Er liegt neben dem Fluss."}', '54d2f55947ba741e9df238b614d1290687b3f15a88b130a3b2bfe3b174ab3a42'),
  ('polish-a2-practical-7', 'polish-a2-practical-7-065-najlepsza-kawiarnia-najblizej-hotelu', 5, 'bright', 'Polish', 'pl-PL', 'German', 'Najlepsza kawiarnia jest najbliżej hotelu, przy rynku.', '{"English":"The best cafe is closest to the hotel, by the market square.","German":"Das beste Café liegt dem Hotel am nächsten, am Marktplatz."}', '5567e74d5ff798ada97d75bf6ccffd53d4c228ac3a24180db064a78534c97992'),
  ('polish-a2-practical-7', 'polish-a2-practical-7-066-szukam-prezentu-czy-pani-ma-pomysl', 6, 'bright', 'Polish', 'pl-PL', 'German', 'Szukam prezentu dla przyjaciela. Czy ma pani jakiś pomysł?', '{"English":"I am looking for a gift for a friend. Do you have an idea?","German":"Ich suche ein Geschenk für einen Freund. Haben Sie eine Idee?"}', '9d539f435243eb153bc07db444033a30cbc47db12e630015cf4a9b0b576272a4'),
  ('polish-a2-practical-7', 'polish-a2-practical-7-067-typowa-polska-restauracja-blisko-hotelu', 7, 'bright', 'Polish', 'pl-PL', 'German', 'Czy jest typowa polska restauracja blisko hotelu?', '{"English":"Is there a typical Polish restaurant near the hotel?","German":"Gibt es ein typisch polnisches Restaurant in der Nähe des Hotels?"}', 'e77c08c9580a3934ef5a3ff02eaea4434b0d63efb30d49f438008c3039b5a0e7'),
  ('polish-a2-practical-7', 'polish-a2-practical-7-068-polecam-rynek-wieczorem', 8, 'bright', 'Polish', 'pl-PL', 'German', 'Polecam rynek wieczorem. Jest piękny i spokojny.', '{"English":"I recommend the market square in the evening. It is beautiful and peaceful.","German":"Ich empfehle den Marktplatz am Abend. Er ist schön und ruhig."}', '92d09721a0e6a295a055ec5d380c543510af9200de06a9997e33664d075a566e'),
  ('polish-a2-practical-7', 'polish-a2-practical-7-069-ktore-ciasto-pani-poleca', 9, 'bright', 'Polish', 'pl-PL', 'German', 'Które ciasto pani poleca do tej kawy?', '{"English":"Which cake do you recommend with this coffee?","German":"Welchen Kuchen empfehlen Sie zu diesem Kaffee?"}', 'e39d3304ce76b1a3b0d2f28e8aab7c0f9d8a4ff6c2c181309b5c03b1c0a8c3ac'),
  ('polish-a2-practical-7', 'polish-a2-practical-7-070-to-jest-swietne-ma-pan-racje', 10, 'bright', 'Polish', 'pl-PL', 'German', 'Dziękuję, to jest świetne. Ma pan rację.', '{"English":"Thank you, this is excellent. You are right.","German":"Danke, das ist ausgezeichnet. Sie haben recht."}', 'a6174dc49389292c93a005042619fc7c6f5e4337a307160e2d24905a7bd4fa4f'),
  ('polish-a2-practical-8', 'polish-a2-practical-8-071-naprawde-super-bardzo-sie-ciesze', 1, 'bright', 'Polish', 'pl-PL', 'German', 'Naprawdę? Super, bardzo się cieszę!', '{"English":"Really? Great, I am very happy!","German":"Wirklich? Super, ich freue mich sehr!"}', 'af6ad476eb9a4298027a648ef82ca108815b53408f9f3f62deea8367342a811c'),
  ('polish-a2-practical-8', 'polish-a2-practical-8-072-jest-dzis-goraco-prawda', 2, 'bright', 'Polish', 'pl-PL', 'German', 'Jest dziś gorąco, prawda? Masz wodę?', '{"English":"It is hot today, right? Do you have water?","German":"Heute ist es heiß, oder? Hast du Wasser?"}', '71ddffaca92d665e9b802d09903a413ced2d1b2970801cbe17abc927d37a18cd'),
  ('polish-a2-practical-8', 'polish-a2-practical-8-073-jestem-zmeczony-bo-malo-spalem', 3, 'bright', 'Polish', 'pl-PL', 'German', 'Dziś jestem zmęczony, bo w nocy mało spałem.', '{"English":"I am tired today because I did not sleep much last night.","German":"Heute bin ich müde, weil ich in der Nacht wenig geschlafen habe."}', 'f20e8a268f4edc3f78fdf1a14185fe2a47b39589be4923c35e9974ee4ea1df90'),
  ('polish-a2-practical-8', 'polish-a2-practical-8-074-mam-duzo-pracy-w-tym-tygodniu', 4, 'bright', 'Polish', 'pl-PL', 'German', 'Nie mam czasu. Mam dużo pracy w tym tygodniu.', '{"English":"I do not have time. I have a lot of work this week.","German":"Ich habe keine Zeit. Ich habe diese Woche viel Arbeit."}', '684bd2a540178cd1cf397b219d0210d5b62680bb7f6b44bda6362e92b55d36b5'),
  ('polish-a2-practical-8', 'polish-a2-practical-8-075-szkoda-znowu-pada', 5, 'bright', 'Polish', 'pl-PL', 'German', 'Szkoda, znowu pada. Zostańmy dziś w kawiarni.', '{"English":"That is a shame; it is raining again. Let us stay in the cafe today.","German":"Schade, es regnet schon wieder. Bleiben wir heute im Café."}', '305a2aa62d6a91811dd1096883f639cbf82d53caa0f1d0dda24889536406a425'),
  ('polish-a2-practical-8', 'polish-a2-practical-8-076-o-nie-przykro-mi', 6, 'bright', 'Polish', 'pl-PL', 'German', 'O nie, przykro mi. Mogę ci pomóc?', '{"English":"Oh no, I am sorry. Can I help you?","German":"Oh nein, das tut mir leid. Kann ich dir helfen?"}', '016da3a1b3a73197b291940aaae5a242ac4e767f2279622a5ce118fd1564c8b1'),
  ('polish-a2-practical-8', 'polish-a2-practical-8-077-dosc-dobrze-troche-zmeczony', 7, 'bright', 'Polish', 'pl-PL', 'German', 'Dość dobrze, tylko jestem trochę zmęczony.', '{"English":"Quite well; I am just a little tired.","German":"Ziemlich gut, ich bin nur etwas müde."}', 'a0a59c202715e8702d29120532fb352f9af079df4a9d05ded475a318730f3196'),
  ('polish-a2-practical-8', 'polish-a2-practical-8-078-swietnie-idziemy-na-koncert', 8, 'bright', 'Polish', 'pl-PL', 'German', 'Świetnie! To idziemy razem na koncert.', '{"English":"Great! We are going to the concert together, then.","German":"Großartig! Dann gehen wir zusammen zum Konzert."}', 'd149da463d54b80abc138463ecd77e99c7d51a6de3d7d072c2a69e804a239034'),
  ('polish-a2-practical-8', 'polish-a2-practical-8-079-jest-mi-zimno-potrzebuje-kawy', 9, 'bright', 'Polish', 'pl-PL', 'German', 'Jest mi zimno i jestem głodny. Potrzebuję gorącej kawy.', '{"English":"I am cold and hungry. I need a hot coffee.","German":"Mir ist kalt und ich bin hungrig. Ich brauche einen heißen Kaffee."}', 'dd8d123dd021df11da30719e0f03bd75d911d0fce98065d1fa7a99aafe84b200'),
  ('polish-a2-practical-8', 'polish-a2-practical-8-080-to-jest-udany-dzien', 10, 'bright', 'Polish', 'pl-PL', 'German', 'To jest udany dzień, prawda? Czuję się dobrze.', '{"English":"This is a good day, right? I feel well.","German":"Das ist ein gelungener Tag, oder? Ich fühle mich gut."}', 'ca79df9bb995c9f9e6364cbccfafa61a38bcc7bfadc75452c4b9d8e418318306'),
  ('polish-a2-practical-9', 'polish-a2-practical-9-081-prysznic-nie-dziala-zadzwonilam', 1, 'bright', 'Polish', 'pl-PL', 'German', 'Prysznic nie działa. Zadzwoniłam już do recepcji. Czy można to sprawdzić?', '{"English":"The shower does not work. I already called reception. Can this be checked?","German":"Die Dusche funktioniert nicht. Ich habe schon an der Rezeption angerufen. Kann man das prüfen?"}', 'b6c294721ea3e429bf9b6951f28bd810e3052ddd18afdeefe1aa7adb9f1b7cb1'),
  ('polish-a2-practical-9', 'polish-a2-practical-9-082-zamowilam-zupe-nadal-jej-nie-ma', 2, 'bright', 'Polish', 'pl-PL', 'German', 'Zamówiłam zupę, ale nadal jej nie ma. Czy można to sprawdzić?', '{"English":"I ordered soup, but it is still not here. Can this be checked?","German":"Ich habe Suppe bestellt, aber sie ist immer noch nicht da. Kann man das prüfen?"}', '1e49eab8f25b085d70757960f470b16571d539818d6f54034f95339dd407b03f'),
  ('polish-a2-practical-9', 'polish-a2-practical-9-083-zadzwonilam-wi-fi-nie-dziala', 3, 'bright', 'Polish', 'pl-PL', 'German', 'Zadzwoniłam do recepcji, bo wi-fi w pokoju nie działa. Czy można mi pomóc?', '{"English":"I called reception because the Wi-Fi in the room does not work. Can you help me?","German":"Ich habe an der Rezeption angerufen, weil das WLAN im Zimmer nicht funktioniert. Können Sie mir helfen?"}', '82f86f64b8dab1842363dff86b76cb7c990a29862fd94b77d5b1a9ecb1021983'),
  ('polish-a2-practical-9', 'polish-a2-practical-9-084-zgubilam-klucz-nie-moge-wejsc', 4, 'bright', 'Polish', 'pl-PL', 'German', 'Zgubiłam klucz i teraz nie mogę wejść. Czy można mi pomóc?', '{"English":"I lost my key and cannot get into my room now. Can you help me?","German":"Ich habe den Schlüssel verloren und komme jetzt nicht ins Zimmer. Können Sie mir helfen?"}', '0ff5807c5c1960862c7be1c7e52a4eed201f93f1a1abdabdf8e3207676a0e33e'),
  ('polish-a2-practical-9', 'polish-a2-practical-9-085-zadzwonilam-po-taksowke-zamowic-kolejna', 5, 'bright', 'Polish', 'pl-PL', 'German', 'Zadzwoniłam po taksówkę, ale nadal jej nie ma. Czy można zamówić kolejną?', '{"English":"I called for a taxi, but it is still not here. Can another one be ordered?","German":"Ich habe ein Taxi gerufen, aber es ist immer noch nicht da. Kann man ein anderes bestellen?"}', '14c8b2d9cd98a561e61f783fff2b5e8046f278fae7990b1ff0607016a3609f94'),
  ('polish-a2-practical-9', 'polish-a2-practical-9-086-zaplacilam-brakuje-jednego-zlotego', 6, 'bright', 'Polish', 'pl-PL', 'German', 'Zapłaciłam gotówką, ale brakuje jednego złotego. Czy można sprawdzić resztę?', '{"English":"I paid cash, but one zloty is missing. Can the change be checked?","German":"Ich habe bar bezahlt, aber ein Złoty fehlt. Kann man das Wechselgeld prüfen?"}', '06cc905cc22814bb1d1f93f86858655fdb3d9aeaa24291ee5bdb1b04567dbb7c'),
  ('polish-a2-practical-9', 'polish-a2-practical-9-087-kupilam-ladowarke-nie-dziala', 7, 'bright', 'Polish', 'pl-PL', 'German', 'Kupiłam tę ładowarkę dzisiaj, ale teraz nie działa. Czy można ją wymienić?', '{"English":"I bought this charger today, but now it does not work. Can it be exchanged?","German":"Ich habe dieses Ladegerät heute gekauft, aber jetzt funktioniert es nicht. Kann man es umtauschen?"}', '9671e98830ae9a965950faa8b5de71f5f4472e41b24e82434cba26bd68a8859e'),
  ('polish-a2-practical-9', 'polish-a2-practical-9-088-zamowilam-goraca-zupe-jest-zimna', 8, 'bright', 'Polish', 'pl-PL', 'German', 'Zamówiłam gorącą zupę, ale jest zimna. Czy można ją podgrzać?', '{"English":"I ordered hot soup, but it is cold. Can it be warmed up?","German":"Ich habe eine heiße Suppe bestellt, aber sie ist kalt. Kann man sie aufwärmen?"}', 'bb33d962b848510a760b777e7146f388eec4e9be3a727956e423867a2cbfac91'),
  ('polish-a2-practical-9', 'polish-a2-practical-9-089-zle-spalam-za-duzo-halasu', 9, 'bright', 'Polish', 'pl-PL', 'German', 'Źle spałam, bo w pokoju jest za dużo hałasu. Czy jest gdzieś ciszej?', '{"English":"I slept badly because there is too much noise in the room. Is there somewhere quieter?","German":"Ich habe schlecht geschlafen, weil im Zimmer zu viel Lärm ist. Ist es irgendwo ruhiger?"}', 'f86296dad1de8826452aa4e93a7cc6a8793bf899188ba7b8a55873898af407ff'),
  ('polish-a2-practical-9', 'polish-a2-practical-9-090-zadzwonilam-rano-teraz-wszystko-dziala', 10, 'bright', 'Polish', 'pl-PL', 'German', 'Zadzwoniłam rano, a teraz wszystko działa. Bardzo dziękuję za pomoc.', '{"English":"I called this morning, and now everything works. Thank you very much for the help.","German":"Ich habe heute Morgen angerufen, und jetzt funktioniert alles. Vielen Dank für die Hilfe."}', 'ce1942966a5d3cda5f7b290ff1dd4a06d933eea1af7816f24d56a98f333c4e06'),
  ('portuguese-a1-practical-1', 'portuguese-a1-practical-1-lesson-1-ola-portugues', 1, 'bright', 'Portuguese', 'pt-BR', 'German', 'Olá, você fala português?', '{"English":"Hello, do you speak Portuguese?","German":"Hallo, sprechen Sie Portugiesisch?"}', '3511dadc3f0cbc8b08fb9d53c76438c951b89864a3723e7e2772b76538402518'),
  ('portuguese-a1-practical-1', 'portuguese-a1-practical-1-lesson-2-repetir', 2, 'bright', 'Portuguese', 'pt-BR', 'German', 'Desculpe, você pode repetir, por favor?', '{"English":"Sorry, could you repeat that, please?","German":"Entschuldigung, können Sie das bitte wiederholen?"}', 'e090c7711bc1459c58c03dfaabe896c7904a17b77d54f77d82bad216c74429d9'),
  ('portuguese-a1-practical-1', 'portuguese-a1-practical-1-lesson-3-onde-fica-a-estacao', 3, 'bright', 'Portuguese', 'pt-BR', 'German', 'Com licença, onde fica a estação?', '{"English":"Excuse me, where is the station?","German":"Entschuldigung, wo ist der Bahnhof?"}', '8cfa362a11a70e803d9c70b4d0978f7786dc6faa30ec13915e982f3db6ab0d4e'),
  ('portuguese-a1-practical-1', 'portuguese-a1-practical-1-lesson-4-cafe', 4, 'bright', 'Portuguese', 'pt-BR', 'German', 'Um café, por favor.', '{"English":"A coffee, please.","German":"Einen Kaffee, bitte."}', '13424cdbec8b260a410dc985174d1916a0f478828f885ceda1367eeb44051acb'),
  ('portuguese-a1-practical-1', 'portuguese-a1-practical-1-lesson-5-quanto-custa', 5, 'bright', 'Portuguese', 'pt-BR', 'German', 'Quanto custa isso, por favor?', '{"English":"How much is this, please?","German":"Wie viel kostet das bitte?"}', '1b16731b298d2cdcdcfb67438e89d6a125d38153fac22a7fd76fe11f51755835'),
  ('portuguese-a1-practical-1', 'portuguese-a1-practical-1-lesson-6-trem', 6, 'bright', 'Portuguese', 'pt-BR', 'German', 'A que horas sai o trem?', '{"English":"What time does the train leave?","German":"Um wie viel Uhr fährt der Zug?"}', '74939cfdbd659eaef4f0bb7fa57e46bdf4b50cb36ad783157fafeacee908ceec'),
  ('portuguese-a1-practical-1', 'portuguese-a1-practical-1-lesson-7-ajuda', 7, 'bright', 'Portuguese', 'pt-BR', 'German', 'Eu preciso de ajuda, por favor.', '{"English":"I need some help, please.","German":"Ich brauche Hilfe, bitte."}', '004d568ba5a461d3a891cc1eda56758cae7a43fe185770e303a188b50317513c'),
  ('portuguese-a1-practical-1', 'portuguese-a1-practical-1-lesson-8-aqui-no-cafe', 8, 'bright', 'Portuguese', 'pt-BR', 'German', 'Este café é muito bonito.', '{"English":"This cafe is really lovely.","German":"Dieses Café ist sehr schön."}', 'ffca7e940bc432f9dadb8c237da0e771dbbe7556a1b47b8c85964357b7411c1c'),
  ('portuguese-a1-practical-1', 'portuguese-a1-practical-1-lesson-9-amanha-as-sete', 9, 'bright', 'Portuguese', 'pt-BR', 'German', 'Amanhã às sete. Perfeito!', '{"English":"Tomorrow at seven. Perfect!","German":"Morgen um sieben. Perfekt!"}', 'b7b6d9c8f84201d72dad1bbd82a5ceeda34a7670a63680fd247b2861e5bac908'),
  ('portuguese-a1-practical-1', 'portuguese-a1-practical-1-lesson-10-obrigado-tchau', 10, 'bright', 'Portuguese', 'pt-BR', 'German', 'Obrigado. Tchau.', '{"English":"Thank you. Bye.","German":"Danke. Tschüss."}', 'fcac130728eedbd66fb545a8aaad2d181ec0354ccd8e6c437184187a491d5186'),
  ('portuguese-a1-practical-10', 'portuguese-a1-practical-10-lesson-1-dia', 1, 'bright', 'Portuguese', 'pt-BR', 'German', 'Hoje é um bom dia.', '{"English":"Today is a good day.","German":"Heute ist ein guter Tag."}', '9572cd5d2ce67cd3d5c698a6ead5fbcd0078b079344a80352c49cdd9cd9ef9da'),
  ('portuguese-a1-practical-10', 'portuguese-a1-practical-10-lesson-2-lugar', 2, 'bright', 'Portuguese', 'pt-BR', 'German', 'Gosto deste lugar.', '{"English":"I like this place.","German":"Ich mag diesen Ort."}', '56105911b9bb8621d3d2ddc93c058180cf4d4823c6b2a3e271a0eea60875f8d4'),
  ('portuguese-a1-practical-10', 'portuguese-a1-practical-10-lesson-3-pela', 3, 'bright', 'Portuguese', 'pt-BR', 'German', 'Obrigado pela ajuda.', '{"English":"Thanks for the help.","German":"Danke für die Hilfe."}', '37f74b77c7fe6268788b6b04b2c248af31c1b3a7e9a0f1aa50accc86a2771198'),
  ('portuguese-a1-practical-10', 'portuguese-a1-practical-10-lesson-4-aprendi', 4, 'bright', 'Portuguese', 'pt-BR', 'German', 'Eu aprendo muito aqui.', '{"English":"I learn a lot here.","German":"Ich lerne hier viel."}', 'b734b4e2c6a3856f9c41a79fd6e7f76035b7d8fe63eb6b98722723adfa534aae'),
  ('portuguese-a1-practical-10', 'portuguese-a1-practical-10-lesson-5-cansado', 5, 'bright', 'Portuguese', 'pt-BR', 'German', 'Estou cansado agora.', '{"English":"I''m tired now.","German":"Ich bin jetzt müde."}', '129339124082710856665fc840dbbb00e69f18810e503dcc8e4e85406e4e09af'),
  ('portuguese-a1-practical-10', 'portuguese-a1-practical-10-lesson-6-ir', 6, 'bright', 'Portuguese', 'pt-BR', 'German', 'Preciso ir agora.', '{"English":"I have to go now.","German":"Ich muss jetzt gehen."}', '678270c8ffd64f4232c9f25842e580de38baf662c4468ccad951894c86d0214f'),
  ('portuguese-a1-practical-10', 'portuguese-a1-practical-10-lesson-7-vez', 7, 'bright', 'Portuguese', 'pt-BR', 'German', 'Até a próxima.', '{"English":"Until next time.","German":"Bis zum nächsten Mal."}', 'd488c16a051bb6af909c39f7931efe195510390a030b93a92b96ea342c7572b6'),
  ('portuguese-a1-practical-10', 'portuguese-a1-practical-10-lesson-8-funciona', 8, 'bright', 'Portuguese', 'pt-BR', 'German', 'Amanhã funciona para mim.', '{"English":"Tomorrow works for me.","German":"Morgen passt es für mich."}', 'b3e1b977b6f275b14727ba836ede39dd6fac256d7b970fc34d6dd282d0b93b2d'),
  ('portuguese-a1-practical-10', 'portuguese-a1-practical-10-lesson-9-durma', 9, 'bright', 'Portuguese', 'pt-BR', 'German', 'Durma bem.', '{"English":"Sleep well.","German":"Schlaf gut."}', '2de9f570e8fb477712ba91f1e834af9d6ace747e535674192a57ba1edd3622d7'),
