  ('portuguese-a1-practical-8', 'portuguese-a1-practical-8-lesson-2-quarto', 2, 'bright', 'Portuguese', 'pt-BR', 'German', 'Preciso de um quarto, por favor.', '{"English":"I need a room, please.","German":"Ich brauche ein Zimmer, bitte."}', 'b751578ba500b31389379f25bfd041f931d8be15e57af93ac6ced744c524713f'),
  ('portuguese-a1-practical-8', 'portuguese-a1-practical-8-lesson-3-andar', 3, 'bright', 'Portuguese', 'pt-BR', 'German', 'Em que andar fica o meu quarto?', '{"English":"What floor is my room on?","German":"In welchem Stock ist mein Zimmer?"}', 'dd60e28bef427c37b06e60eb38566dbff7a12d98e956da2ddfa55b3de1c1deab'),
  ('portuguese-a1-practical-8', 'portuguese-a1-practical-8-lesson-4-chave', 4, 'bright', 'Portuguese', 'pt-BR', 'German', 'A chave do quarto, por favor.', '{"English":"The room key, please.","German":"Den Zimmerschlüssel, bitte."}', 'd9d4fb8b5436f45217440316b7e3ade9c3f293cf62fd4e3bfedb35e4f148526d'),
  ('portuguese-a1-practical-8', 'portuguese-a1-practical-8-lesson-5-wifi', 5, 'bright', 'Portuguese', 'pt-BR', 'German', 'Tem Wi-Fi no quarto?', '{"English":"Is there Wi-Fi in the room?","German":"Gibt es WLAN im Zimmer?"}', 'f6ac4a70399e9f2750ae4dafcfbdca4e8ea3b3e38bff16b171a270a8b5ebed65'),
  ('portuguese-a1-practical-8', 'portuguese-a1-practical-8-lesson-6-banheiro', 6, 'bright', 'Portuguese', 'pt-BR', 'German', 'Onde fica o banheiro?', '{"English":"Where''s the bathroom?","German":"Wo ist das Bad?"}', 'c70ca73d8c6bbbb44880d6cb42d854c4d409101e373ee121ac6b64b2d3213c98'),
  ('portuguese-a1-practical-8', 'portuguese-a1-practical-8-lesson-7-toalha', 7, 'bright', 'Portuguese', 'pt-BR', 'German', 'Uma toalha, por favor.', '{"English":"A towel, please.","German":"Ein Handtuch, bitte."}', 'cd35532755d7087eaf82a20dad5f031b158220c3f9bcbd667a83ee1c478fbcbf'),
  ('portuguese-a1-practical-8', 'portuguese-a1-practical-8-lesson-8-dormir', 8, 'bright', 'Portuguese', 'pt-BR', 'German', 'Quero dormir agora.', '{"English":"I want to sleep now.","German":"Ich will jetzt schlafen."}', 'c0b31857cbddf53e3dc99b88649be32ab5118471aa30d966603b6acdd29185a4'),
  ('portuguese-a1-practical-8', 'portuguese-a1-practical-8-lesson-9-manha', 9, 'bright', 'Portuguese', 'pt-BR', 'German', 'A que horas é o café da manhã?', '{"English":"What time is breakfast?","German":"Um wie viel Uhr ist das Frühstück?"}', '3f8db91d666cda768ecdd5d192fb3352f2caf39ab9a24192fbf852fae473f5f0'),
  ('portuguese-a1-practical-8', 'portuguese-a1-practical-8-lesson-10-check-out', 10, 'bright', 'Portuguese', 'pt-BR', 'German', 'Vou fazer o check-out agora.', '{"English":"I''m checking out now.","German":"Ich checke jetzt aus."}', '341558215119eb026f34ac8e31451237f110c044014b27f165c72ea27fb87aa3'),
  ('portuguese-a1-practical-9', 'portuguese-a1-practical-9-lesson-1-oi', 1, 'bright', 'Portuguese', 'pt-BR', 'German', 'Oi, eu sou Ana. Prazer.', '{"English":"Hi, I''m Ana. Nice to meet you.","German":"Hallo, ich bin Ana. Freut mich."}', 'a6202ffb2c1f3a7cbd4b3124a040d9d1ce93fb48e90e8d840938f1da1bdb1dfc'),
  ('portuguese-a1-practical-9', 'portuguese-a1-practical-9-lesson-2-livre', 2, 'bright', 'Portuguese', 'pt-BR', 'German', 'Você está livre hoje?', '{"English":"Are you free today?","German":"Hast du heute Zeit?"}', '3a5914bbbba6f95f6f940c308cf23d9679fad1f39646371caafa81278da922c1'),
  ('portuguese-a1-practical-9', 'portuguese-a1-practical-9-lesson-3-depois', 3, 'bright', 'Portuguese', 'pt-BR', 'German', 'Podemos nos encontrar depois?', '{"English":"Can we meet later?","German":"Können wir uns später treffen?"}', '99cfbea7654dbf8d5de7d5ce4614dee23d9335db7bd4c067374ea5deccac3ed0'),
  ('portuguese-a1-practical-9', 'portuguese-a1-practical-9-lesson-4-horario', 4, 'bright', 'Portuguese', 'pt-BR', 'German', 'Que horário fica bom para você?', '{"English":"What time works for you?","German":"Welche Uhrzeit passt dir?"}', 'c5c15c717071418bd98644d71b0c75ddaf45d204bdc88d9d7fe41ff84ecf56a3'),
  ('portuguese-a1-practical-9', 'portuguese-a1-practical-9-lesson-5-mesmo', 5, 'bright', 'Portuguese', 'pt-BR', 'German', 'Vamos nos encontrar aqui mesmo?', '{"English":"Shall we meet right here?","German":"Treffen wir uns genau hier?"}', '106dca3ffd780f0d172ee55141f0023a72935c71a58e9bc30f7ef9124acb43c3'),
  ('portuguese-a1-practical-9', 'portuguese-a1-practical-9-lesson-6-fora', 6, 'bright', 'Portuguese', 'pt-BR', 'German', 'Estou esperando lá fora.', '{"English":"I''m waiting outside.","German":"Ich warte draußen."}', '1021d957e9f2f66a7b1e4848a1d4e06a9ac7161ed224197243b12fc7d51ef071'),
  ('portuguese-a1-practical-9', 'portuguese-a1-practical-9-lesson-7-chegar', 7, 'bright', 'Portuguese', 'pt-BR', 'German', 'Vou chegar tarde.', '{"English":"I''ll be late.","German":"Ich werde spät ankommen."}', 'f14c626573c55a03dc9ec9b92459ab17d6856a3db7735db3ee361beddaa86142'),
  ('portuguese-a1-practical-9', 'portuguese-a1-practical-9-lesson-8-mudar', 8, 'bright', 'Portuguese', 'pt-BR', 'German', 'Podemos mudar o plano?', '{"English":"Can we change the plan?","German":"Können wir den Plan ändern?"}', 'dc77c7811bd03c8568b2fc782d0e5ae949de251da6e9f4a16dca54d123911b9e'),
  ('portuguese-a1-practical-9', 'portuguese-a1-practical-9-lesson-9-gente', 9, 'bright', 'Portuguese', 'pt-BR', 'German', 'A gente se vê amanhã.', '{"English":"See you tomorrow.","German":"Wir sehen uns morgen."}', 'c34b1ece07d89b721ea464e2605f2424fca1afaa085f922e844915f0abfb3818'),
  ('portuguese-a1-practical-9', 'portuguese-a1-practical-9-lesson-10-boa', 10, 'bright', 'Portuguese', 'pt-BR', 'German', 'Boa noite. Até amanhã.', '{"English":"Good night. See you tomorrow.","German":"Schönen Abend. Bis morgen."}', '4fd3d7a5df9f2144508a2594a5f036edfacd5ac93be6ff5c59d332f5b98ab75b'),
  ('portuguese-a2-practical-1', 'portuguese-a2-practical-1-001-sim-o-de-sempre', 1, 'bright', 'Portuguese', 'pt-BR', 'German', 'Sim, o de sempre: um café com leite, por favor.', '{"English":"Yes, the usual: a coffee with milk, please.","German":"Ja, das Übliche: ein Milchkaffee, bitte."}', 'd5c8b9149fece5af83336c50ca2785bf570d8ae5028ee5f7d3c012f5eb29456e'),
  ('portuguese-a2-practical-1', 'portuguese-a2-practical-1-002-para-viagem-quanto-fica', 2, 'bright', 'Portuguese', 'pt-BR', 'German', 'Para viagem, por favor. Quanto fica tudo?', '{"English":"To go, please. How much is everything?","German":"Zum Mitnehmen, bitte. Wie viel kostet alles?"}', '4ac0418cb0adf9a7e99210f1102b4b9b71fc7dabbe30ec7adfa46016083c4505'),
  ('portuguese-a2-practical-1', 'portuguese-a2-practical-1-003-procurando-chip-celular', 3, 'bright', 'Portuguese', 'pt-BR', 'German', 'Estou procurando um chip para o celular. Vocês têm?', '{"English":"I am looking for a SIM card for the phone. Do you have any?","German":"Ich suche eine SIM-Karte fürs Handy. Haben Sie welche?"}', 'fad743cc427c0a8bfaecf34ff503cb0aa3cabf117f6ed66fe1a75828e3907863'),
  ('portuguese-a2-practical-1', 'portuguese-a2-practical-1-004-quantos-minutos-a-pe', 4, 'bright', 'Portuguese', 'pt-BR', 'German', 'São quantos minutos a pé daqui?', '{"English":"How many minutes is it from here on foot?","German":"Wie viele Minuten sind es von hier zu Fuß?"}', '69e1ef889cd8d894a9ef7c0eb3c7c51f3872c8f59eed73cba9317fee114cc78b'),
  ('portuguese-a2-practical-1', 'portuguese-a2-practical-1-005-pode-trazer-a-conta', 5, 'bright', 'Portuguese', 'pt-BR', 'German', 'Sim, está tudo muito bom. Pode trazer a conta?', '{"English":"Yes, everything is very good. Can you bring the bill?","German":"Ja, alles ist sehr gut. Können Sie die Rechnung bringen?"}', '3219b38d38f8ab58ebe40d06eff72606ae0923de27ddc52577f1f2a7e131ba98'),
  ('portuguese-a2-practical-1', 'portuguese-a2-practical-1-006-reserva-em-nome-de-silva', 6, 'bright', 'Portuguese', 'pt-BR', 'German', 'Tenho uma reserva em nome de Silva.', '{"English":"I have a reservation under the name Silva.","German":"Ich habe eine Reservierung auf den Namen Silva."}', 'f44652b32218cf307c5557a1b492ee1be45de0997624c84d2dde9bdd905e9eb9'),
  ('portuguese-a2-practical-1', 'portuguese-a2-practical-1-007-quanto-devo-pela-pomada', 7, 'bright', 'Portuguese', 'pt-BR', 'German', 'Não, só isso. Quanto eu devo pela pomada?', '{"English":"No, just that. How much do I owe for the ointment?","German":"Nein, nur das. Wie viel schulde ich für die Salbe?"}', 'bce5aeae88c7a7db5197a41006af5f739eb4d8d5ac6333d7ff12c2b77ac1d995'),
  ('portuguese-a2-practical-1', 'portuguese-a2-practical-1-008-metro-no-fim-da-rua', 8, 'bright', 'Portuguese', 'pt-BR', 'German', 'O metrô fica no fim desta rua.', '{"English":"The metro is at the end of this street.","German":"Die Metro ist am Ende dieser Straße."}', 'f35da28bcd4a12db46a2f97bba01a1ff6ae1762595292289468f67f78c121c82'),
  ('portuguese-a2-practical-1', 'portuguese-a2-practical-1-009-meio-quilo-dois-limoes', 9, 'bright', 'Portuguese', 'pt-BR', 'German', 'Meio quilo, e também dois limões, por favor.', '{"English":"Half a kilo, and also two lemons, please.","German":"Ein halbes Kilo und außerdem zwei Zitronen, bitte."}', 'd1d9bcaba1010b08cecc92323b3a1d12ef031ed95309a9ecd9ba6e52de65d73a'),
  ('portuguese-a2-practical-1', 'portuguese-a2-practical-1-010-ja-conheco-o-bairro', 10, 'bright', 'Portuguese', 'pt-BR', 'German', 'Sim, já conheço um pouco o bairro.', '{"English":"Yes, I already know the neighborhood a little.","German":"Ja, ich kenne das Viertel schon ein wenig."}', 'de8de4f195d376dab2423b36f9a80385f2da431d50fd688a229de4e51c2cdaa5'),
  ('portuguese-a2-practical-10', 'portuguese-a2-practical-10-091-sou-da-alemanha-e-agora-moro-aqui', 1, 'bright', 'Portuguese', 'pt-BR', 'German', 'Sou da Alemanha e agora moro aqui.', '{"English":"I am from Germany and live here now.","German":"Ich komme aus Deutschland und wohne jetzt hier."}', '647856db61db891f41ec62a8d8e3d39b9bf9215b125cff0b1088ec2321ca9962'),
  ('portuguese-a2-practical-10', 'portuguese-a2-practical-10-092-trabalho-escritorio-no-centro-perto-daqui', 2, 'bright', 'Portuguese', 'pt-BR', 'German', 'Trabalho em um escritório no centro, perto daqui.', '{"English":"I work in an office downtown, nearby.","German":"Ich arbeite in einem Büro im Zentrum, ganz in der Nähe."}', '3cb3784e5476e2db4e9c4066932d95ae8702d7a994bf691c02bbde33ef3f003c'),
  ('portuguese-a2-practical-10', 'portuguese-a2-practical-10-093-estudo-portugues-porque-gosto-da-musica-brasileira', 3, 'bright', 'Portuguese', 'pt-BR', 'German', 'Estudo português porque gosto da música brasileira.', '{"English":"I study Portuguese because I like Brazilian music.","German":"Ich lerne Portugiesisch, weil ich brasilianische Musik mag."}', 'd01e1202d3580cb1e3c642943bc0d207d9431adb01bf274838944344464d1063'),
  ('portuguese-a2-practical-10', 'portuguese-a2-practical-10-094-estou-aqui-ha-duas-semanas', 4, 'bright', 'Portuguese', 'pt-BR', 'German', 'Estou aqui há duas semanas e gosto muito daqui.', '{"English":"I have been here for two weeks and like it here a lot.","German":"Ich bin seit zwei Wochen hier und mag es hier sehr."}', '8351fe602c7dcdbdd98604cf0601b3f45eb57ef3f21faabc671027c3f27e8727'),
  ('portuguese-a2-practical-10', 'portuguese-a2-practical-10-095-minha-familia-esta-na-alemanha-falamos-domingo', 5, 'bright', 'Portuguese', 'pt-BR', 'German', 'Minha família está na Alemanha, e falamos todo domingo.', '{"English":"My family is in Germany, and we speak every Sunday.","German":"Meine Familie ist in Deutschland, und wir sprechen jeden Sonntag."}', '2c16fdb332882234a5600f31004253b66c29c069f0441c5c74f0e64a955651f4'),
  ('portuguese-a2-practical-10', 'portuguese-a2-practical-10-096-gosto-de-cozinhar-e-caminhar-no-bairro', 6, 'bright', 'Portuguese', 'pt-BR', 'German', 'Gosto de cozinhar e caminhar no bairro.', '{"English":"I like cooking and walking around the neighborhood.","German":"Ich koche gern und gehe gern im Viertel spazieren."}', '2d784c0e514f91ffbab66fb085fef34db71e3d19534aaceb9aa4eba1c22f04fa'),
  ('portuguese-a2-practical-10', 'portuguese-a2-practical-10-097-de-manha-trabalho-a-noite-estudo-portugues', 7, 'bright', 'Portuguese', 'pt-BR', 'German', 'De manhã trabalho, e à noite estudo português.', '{"English":"In the morning I work, and at night I study Portuguese.","German":"Morgens arbeite ich, und abends lerne ich Portugiesisch."}', '624753078cdbc15800e9f286dcf690de6dd31528f9e306286b5bfc07fe239238'),
  ('portuguese-a2-practical-10', 'portuguese-a2-practical-10-098-entendo-quase-tudo-e-falo-devagar', 8, 'bright', 'Portuguese', 'pt-BR', 'German', 'Entendo quase tudo e falo devagar agora.', '{"English":"I understand almost everything and speak slowly now.","German":"Ich verstehe jetzt fast alles und spreche langsam."}', '6e22f3b9eba8191d8c2488cf119d499f0e90a665a47002fb0f0ef356506032e3'),
  ('portuguese-a2-practical-10', 'portuguese-a2-practical-10-099-ano-que-vem-vou-voltar-para-ca', 9, 'bright', 'Portuguese', 'pt-BR', 'German', 'Ano que vem vou voltar para cá.', '{"English":"Next year I am going to come back here.","German":"Nächstes Jahr werde ich hierher zurückkommen."}', 'fd6bcc0c434f47c5ef6f2f8e3a3cccb67d385bdd546f689368006b75e2408a30'),
  ('portuguese-a2-practical-10', 'portuguese-a2-practical-10-100-fiz-amigos-aqui-obrigado-por-estas-duas-semanas-ate-a-proxima', 10, 'bright', 'Portuguese', 'pt-BR', 'German', 'Fiz amigos aqui. Obrigado por estas duas semanas. Até a próxima!', '{"English":"I made friends here. Thank you for these two weeks. See you next time!","German":"Ich habe hier Freunde gefunden. Danke für diese zwei Wochen. Bis zum nächsten Mal!"}', '93f42f0735dd496f5dab4162bcbec8ce0d7981445a8ad58a2c94c6238cdcfd66'),
  ('portuguese-a2-practical-2', 'portuguese-a2-practical-2-011-prefiro-estes-tomates', 1, 'bright', 'Portuguese', 'pt-BR', 'German', 'Prefiro estes tomates porque estão mais maduros do que aqueles.', '{"English":"I prefer these tomatoes because they are riper than those.","German":"Ich bevorzuge diese Tomaten, weil sie reifer sind als jene."}', 'a3f6e53925c54ed3243df237862ed9bd215b94d38d3b9b18186f9970bfcacc1c'),
  ('portuguese-a2-practical-2', 'portuguese-a2-practical-2-012-hoje-prefiro-um-suco', 2, 'bright', 'Portuguese', 'pt-BR', 'German', 'Hoje prefiro um suco porque é menos forte do que o café.', '{"English":"Today I prefer a juice because it is less strong than coffee.","German":"Heute bevorzuge ich einen Saft, weil er weniger stark ist als der Kaffee."}', 'e40a0be18bc237ada9e8137dc166256491775c604dbed50ae68f27a411484603'),
  ('portuguese-a2-practical-2', 'portuguese-a2-practical-2-013-prefiro-a-camisa-azul', 3, 'bright', 'Portuguese', 'pt-BR', 'German', 'Prefiro a camisa azul porque fica mais bonita do que a preta.', '{"English":"I prefer the blue shirt because it looks nicer than the black one.","German":"Ich bevorzuge das blaue Hemd, weil es schöner wirkt als das schwarze."}', 'ad27b79da6807cb5298c7b2de78576d467ffe3416bd5d7c5260cd0671a5cac5a'),
  ('portuguese-a2-practical-2', 'portuguese-a2-practical-2-014-quero-a-salada-mais-leve', 4, 'bright', 'Portuguese', 'pt-BR', 'German', 'Quero a salada porque é mais leve do que a massa.', '{"English":"I want the salad because it is lighter than the pasta.","German":"Ich möchte den Salat, weil er leichter ist als die Pasta."}', '8be54613dfe39bf365ffacda2efd0d25d63919681e13158983880b3b49f77941'),
  ('portuguese-a2-practical-2', 'portuguese-a2-practical-2-015-escolho-pao-frances-fresquinho', 5, 'bright', 'Portuguese', 'pt-BR', 'German', 'Escolho este pão francês porque está mais fresquinho do que o outro.', '{"English":"I choose this Brazilian bread roll because it is fresher than the other one.","German":"Ich wähle dieses brasilianische Brötchen, weil es frischer ist als das andere."}', '5e2c370f0577bf317b8b88b96de41723448164f2ea7b6a754072c9febf0fc38e'),
  ('portuguese-a2-practical-2', 'portuguese-a2-practical-2-016-vou-de-metro-mais-rapido', 6, 'bright', 'Portuguese', 'pt-BR', 'German', 'Vou de metrô porque é mais rápido do que o ônibus.', '{"English":"I go by metro because it is faster than the bus.","German":"Ich fahre mit der Metro, weil sie schneller ist als der Bus."}', 'f772ad491cb55ec05e9fb29740d440a1a4753daf47abac1a40fa258bdc69f341'),
  ('portuguese-a2-practical-2', 'portuguese-a2-practical-2-017-quarto-mais-silencioso', 7, 'bright', 'Portuguese', 'pt-BR', 'German', 'Este quarto é mais silencioso do que o outro, então durmo melhor.', '{"English":"This room is quieter than the other one, so I sleep better.","German":"Dieses Zimmer ist ruhiger als das andere, deshalb schlafe ich besser."}', '07bdcfb8d04ad9a3acc0abd01dab49d002440b74c6d33e3039988f60dcade692'),
  ('portuguese-a2-practical-2', 'portuguese-a2-practical-2-018-sapatos-mais-confortaveis', 8, 'bright', 'Portuguese', 'pt-BR', 'German', 'Prefiro estes sapatos porque são mais confortáveis do que aqueles.', '{"English":"I prefer these shoes because they are more comfortable than those.","German":"Ich bevorzuge diese Schuhe, weil sie bequemer sind als jene."}', '08a85edade3f217ff36e9c3349f487a8562cb54c7004710c2f5d74b9e5ac7c55'),
  ('portuguese-a2-practical-2', 'portuguese-a2-practical-2-019-garrafa-menor-custa-menos', 9, 'bright', 'Portuguese', 'pt-BR', 'German', 'Quero a garrafa menor porque custa menos do que a grande.', '{"English":"I want the smaller bottle because it costs less than the large one.","German":"Ich möchte die kleinere Flasche, weil sie weniger kostet als die große."}', 'b1c8e8ba8cb6084c30bd659d2b2f165fedef1c2d467a344a6b9034f5476cdd7f'),
  ('portuguese-a2-practical-2', 'portuguese-a2-practical-2-020-cafe-mais-tranquilo', 10, 'bright', 'Portuguese', 'pt-BR', 'German', 'Este café é mais tranquilo e fica mais perto do que o outro.', '{"English":"This cafe is quieter and closer than the other one.","German":"Dieses Café ist ruhiger und liegt näher als das andere."}', '36fc35d2a3384309e5df1de56fbf6861fbd5d8979990408cd1ad1f7f516c6fd5'),
  ('portuguese-a2-practical-3', 'portuguese-a2-practical-3-021-ja-paguei-no-caixa', 1, 'bright', 'Portuguese', 'pt-BR', 'German', 'Já paguei no caixa com cartão.', '{"English":"I already paid at the register by card.","German":"Ich habe schon an der Kasse mit Karte bezahlt."}', '1a15d11bb3d2f58ac1d130958e06135f72583daf4bb58f126bb458d44157b39a'),
  ('portuguese-a2-practical-3', 'portuguese-a2-practical-3-022-cheguei-ontem-no-hotel', 2, 'bright', 'Portuguese', 'pt-BR', 'German', 'Cheguei ontem à noite no hotel.', '{"English":"I arrived at the hotel yesterday evening.","German":"Ich bin gestern Abend im Hotel angekommen."}', '726d3372ef337e07b90208c38ad37bd49eeab5eb01f7f8027bd5a2ad8e305037'),
  ('portuguese-a2-practical-3', 'portuguese-a2-practical-3-023-ja-pedi-a-sopa', 3, 'bright', 'Portuguese', 'pt-BR', 'German', 'Já pedi a sopa do dia, obrigado.', '{"English":"I already ordered the soup of the day, thank you.","German":"Ich habe die Tagessuppe schon bestellt, danke."}', 'f527052759cd721a28bc01c3de2e17059753095a4683f391202dea5b8e2b5749'),
  ('portuguese-a2-practical-3', 'portuguese-a2-practical-3-024-hoje-comprei-tomates-na-feira', 4, 'bright', 'Portuguese', 'pt-BR', 'German', 'Hoje comprei tomates na feira cedo.', '{"English":"Today I bought tomatoes early at the street market.","German":"Heute habe ich früh Tomaten auf dem Wochenmarkt gekauft."}', 'df177971f9d5ced57fee9e71dddc4d0f7743439e126ec6e3c99bc11e971ecc9c'),
  ('portuguese-a2-practical-3', 'portuguese-a2-practical-3-025-hoje-de-manha-fui-a-feira', 5, 'bright', 'Portuguese', 'pt-BR', 'German', 'Hoje de manhã fui à feira bem cedo.', '{"English":"This morning I went to the street market very early.","German":"Heute Morgen bin ich sehr früh zum Wochenmarkt gegangen."}', 'adcfb971917bc98239810751aeeda71964b94984d6ad602ddbe58fa05400f8b4'),
  ('portuguese-a2-practical-3', 'portuguese-a2-practical-3-026-ontem-tive-dor-de-cabeca', 6, 'bright', 'Portuguese', 'pt-BR', 'German', 'Ontem tive dor de cabeça, mas hoje estou melhor.', '{"English":"Yesterday I had a headache, but today I am better.","German":"Gestern hatte ich Kopfschmerzen, aber heute geht es mir besser."}', '92045e08d9deff39dda1e93f50a9a0521ea6c95d8044f0a2abfca751bc6c8865'),
  ('portuguese-a2-practical-3', 'portuguese-a2-practical-3-027-ja-provei-o-prato-tipico', 7, 'bright', 'Portuguese', 'pt-BR', 'German', 'Já provei o prato típico daqui.', '{"English":"I already tried the local dish from here.","German":"Ich habe das typische Gericht von hier schon probiert."}', '8a5a402fe08d9b6e7cc144d06ab6519fb0aa08210411d902966b7365065f2917'),
  ('portuguese-a2-practical-3', 'portuguese-a2-practical-3-028-ainda-nao-vi-a-catedral', 8, 'bright', 'Portuguese', 'pt-BR', 'German', 'Ainda não vi a catedral da cidade.', '{"English":"I have not seen the city cathedral yet.","German":"Ich habe die Kathedrale der Stadt noch nicht gesehen."}', '4a789f94e7a9ceeea8e344f1e1eb5d82be438e9f0963e1eb3d3711a01c13b2ef'),
  ('portuguese-a2-practical-3', 'portuguese-a2-practical-3-029-terminei-o-trabalho-cedo', 9, 'bright', 'Portuguese', 'pt-BR', 'German', 'Terminei o trabalho cedo hoje, então tenho tempo.', '{"English":"I finished work early today, so I have time.","German":"Ich habe die Arbeit heute früh beendet, also habe ich Zeit."}', '333954b5a8afaef3229f4b06a7816b192f7726dce9b167269e13f38d05fc3856'),
  ('portuguese-a2-practical-3', 'portuguese-a2-practical-3-030-fiz-muitas-coisas-esta-semana', 10, 'bright', 'Portuguese', 'pt-BR', 'German', 'Fiz muitas coisas esta semana por aqui.', '{"English":"I did many things around here this week.","German":"Ich habe diese Woche hier viele Dinge erledigt."}', 'd32b9f208456875823c659d910702af9b41ab52555ac1666c1ccfb3f9b6736e6'),
  ('portuguese-a2-practical-4', 'portuguese-a2-practical-4-031-claro-vamos-tomar-cafe', 1, 'bright', 'Portuguese', 'pt-BR', 'German', 'Claro, vamos tomar um café às quatro.', '{"English":"Sure, let’s have coffee at four.","German":"Klar, lass uns um vier einen Kaffee trinken."}', '86012e322d2e37a5d669efebd1d9db93479594e21d8ee3672de7ec18a6151630'),
  ('portuguese-a2-practical-4', 'portuguese-a2-practical-4-032-amanha-vou-visitar-o-museu-no-centro', 2, 'bright', 'Portuguese', 'pt-BR', 'German', 'Amanhã vou visitar o museu no centro.', '{"English":"Tomorrow I’m going to visit the museum in the center.","German":"Morgen besuche ich das Museum im Zentrum."}', '3fa39eace152726b93a8140f32aeefe50b93cb4f5cdd3c060ce9bf30a6dd3313'),
  ('portuguese-a2-practical-4', 'portuguese-a2-practical-4-033-que-tal-ir-ao-cinema', 3, 'bright', 'Portuguese', 'pt-BR', 'German', 'Que tal ir ao cinema na sexta à noite?', '{"English":"How about going to the cinema on Friday night?","German":"Wie wäre es, am Freitagabend ins Kino zu gehen?"}', 'de9b2c509ecf4e4221f1f07b547ac6d2c7388a05d54c833449ff0c176593dc15'),
  ('portuguese-a2-practical-4', 'portuguese-a2-practical-4-034-perfeito-encontro-voce-na-praca', 4, 'bright', 'Portuguese', 'pt-BR', 'German', 'Perfeito, encontro você na praça às oito.', '{"English":"Perfect, I’ll meet you at the square at eight.","German":"Perfekt, ich treffe dich um acht auf dem Platz."}', 'fea4ba10d387c6b4a192e5bde196a0ab3680db9c34e07f7969e8643a5585a488'),
  ('portuguese-a2-practical-4', 'portuguese-a2-practical-4-035-podemos-mudar-para-sabado', 5, 'bright', 'Portuguese', 'pt-BR', 'German', 'Podemos mudar para sábado de manhã?', '{"English":"Can we move it to Saturday morning?","German":"Können wir es auf Samstagvormittag verschieben?"}', '76801130a00df260134ac8af3dd1ba630e13aa54eb250d7eef06b74b82c0bbfb'),
  ('portuguese-a2-practical-4', 'portuguese-a2-practical-4-036-desculpe-hoje-nao-posso', 6, 'bright', 'Portuguese', 'pt-BR', 'German', 'Desculpe, hoje não posso; tenho muito trabalho.', '{"English":"Sorry, I can’t today; I have a lot of work.","German":"Entschuldige, heute kann ich nicht; ich habe viel Arbeit."}', 'edfb540f336af6b2e0cb9c1aa2dcbfdbfa6acceb769d9b06740ac8b6057242f3'),
  ('portuguese-a2-practical-4', 'portuguese-a2-practical-4-037-quero-convidar-voce-para-jantar', 7, 'bright', 'Portuguese', 'pt-BR', 'German', 'Quero convidar você para jantar amanhã.', '{"English":"I want to invite you to dinner tomorrow.","German":"Ich möchte dich morgen zum Abendessen einladen."}', '04a0baa33b40c359ecb580a816f79e2aac985d8396e1e571670599cbaeaa46ec'),
  ('portuguese-a2-practical-4', 'portuguese-a2-practical-4-038-vou-chegar-um-pouco-mais-tarde', 8, 'bright', 'Portuguese', 'pt-BR', 'German', 'Desculpe, vou chegar um pouco mais tarde.', '{"English":"Sorry, I’m going to arrive a little later.","German":"Entschuldige, ich werde etwas später ankommen."}', 'b918fdf7e8d3b3bd4dd644e20a3ff1a36f0b69b1f08499068522b1d26a889783'),
  ('portuguese-a2-practical-4', 'portuguese-a2-practical-4-039-sabado-as-oito-na-praca-combinado', 9, 'bright', 'Portuguese', 'pt-BR', 'German', 'Então, sábado às oito na praça, combinado?', '{"English":"So, Saturday at eight at the square, agreed?","German":"Also, Samstag um acht auf dem Platz, abgemacht?"}', '836ed75a8edd410f207705056b3556d66ee5489c3016b40a9a9bedb3c84509e1'),
  ('portuguese-a2-practical-4', 'portuguese-a2-practical-4-040-vou-descansar-e-fazer-uma-viagem', 10, 'bright', 'Portuguese', 'pt-BR', 'German', 'No fim de semana, vou descansar e fazer uma viagem curta.', '{"English":"At the weekend, I’m going to rest and take a short trip.","German":"Am Wochenende werde ich mich ausruhen und einen kurzen Ausflug machen."}', 'c1eb0078bb74a9d91125296223f752ff655e2135904784c3f706e441e41e6269'),
  ('portuguese-a2-practical-5', 'portuguese-a2-practical-5-041-desculpe-pedi-um-cha', 1, 'bright', 'Portuguese', 'pt-BR', 'German', 'Desculpe, pedi um chá, não um café.', '{"English":"Sorry, I ordered tea, not coffee.","German":"Entschuldige, ich habe einen Tee bestellt, keinen Kaffee."}', '70af6d65ec1f603c44766f9e86177894a930a0c5a646151dda66ced8417aa7c4'),
  ('portuguese-a2-practical-5', 'portuguese-a2-practical-5-042-voce-pode-trocar-esta-camisa', 2, 'bright', 'Portuguese', 'pt-BR', 'German', 'Você pode trocar esta camisa? Está pequena.', '{"English":"Can you exchange this shirt? It is too small.","German":"Können Sie dieses Hemd umtauschen? Es ist zu klein."}', 'f34df29180652db2ae0c9825831f19501e6e065508371c0a96ec7e22ea740071'),
  ('portuguese-a2-practical-5', 'portuguese-a2-practical-5-043-eu-queria-agua-sem-gas', 3, 'bright', 'Portuguese', 'pt-BR', 'German', 'Eu queria água sem gás, por favor.', '{"English":"I would like still water, please.","German":"Ich hätte gern stilles Wasser, bitte."}', '0eaddc557ad55c84397a4fed2a5d2a61b447fdcedefa58f274ca07c965aa72c0'),
  ('portuguese-a2-practical-5', 'portuguese-a2-practical-5-044-prefiro-aquelas-bananas-nao-quero-estas', 4, 'bright', 'Portuguese', 'pt-BR', 'German', 'Prefiro aquelas bananas, não quero estas.', '{"English":"I prefer those bananas; I don’t want these.","German":"Ich bevorzuge jene Bananen, diese möchte ich nicht."}', '388adcd4354906abd499f9c0dec3edbba874800a2b310eb94ea06c1afbbba929'),
  ('portuguese-a2-practical-5', 'portuguese-a2-practical-5-045-voce-pode-trocar-meu-quarto', 5, 'bright', 'Portuguese', 'pt-BR', 'German', 'Você pode trocar meu quarto? Tem muito barulho.', '{"English":"Can you change my room? There is a lot of noise.","German":"Können Sie mein Zimmer wechseln? Es ist sehr laut."}', 'fc7db1aff0d6ca27c7fe5f5fa05fd33a155028e3a0afa43a3d3be645c04ebec8'),
  ('portuguese-a2-practical-5', 'portuguese-a2-practical-5-046-so-quero-o-carregador', 6, 'bright', 'Portuguese', 'pt-BR', 'German', 'Não, só quero o carregador deste celular, obrigado.', '{"English":"No, I only want the charger for this phone, thank you.","German":"Nein, ich möchte nur das Ladegerät für dieses Handy, danke."}', '502d687f40d8f088f83d1099b8c63f6ca42236bae7196eeca0e87dffbb0c9060'),
  ('portuguese-a2-practical-5', 'portuguese-a2-practical-5-047-pode-conferir-o-total', 7, 'bright', 'Portuguese', 'pt-BR', 'German', 'Desculpe, o total não está correto. Pode conferir?', '{"English":"Sorry, the total is not correct. Can you check it?","German":"Entschuldige, der Gesamtbetrag stimmt nicht. Können Sie das prüfen?"}', '1a8e85f929916266849bb6dd97ed10450ec5a8c0741389a986c3ea0dda0b6e05'),
  ('portuguese-a2-practical-5', 'portuguese-a2-practical-5-048-eu-queria-uma-embalagem-menor', 8, 'bright', 'Portuguese', 'pt-BR', 'German', 'Eu queria uma embalagem menor, por favor.', '{"English":"I would like a smaller pack, please.","German":"Ich hätte gern eine kleinere Packung, bitte."}', '70c63b747c2f8ca6d3e20da40c81c2bfe30f613efba7aa1fd3c3db6730656575'),
  ('portuguese-a2-practical-5', 'portuguese-a2-practical-5-049-para-a-estacao-nao-para-o-centro', 9, 'bright', 'Portuguese', 'pt-BR', 'German', 'Para a estação, por favor, não para o centro.', '{"English":"To the station, please, not to the center.","German":"Zum Bahnhof, bitte, nicht ins Zentrum."}', '14040badb172deb2fb3e0ecd19febda1ee1714ac2fc1d91b8516bd9d15dcb05e'),
  ('portuguese-a2-practical-5', 'portuguese-a2-practical-5-050-desculpe-hoje-nao-posso-fico-em-casa', 10, 'bright', 'Portuguese', 'pt-BR', 'German', 'Desculpe, hoje não posso; fico em casa.', '{"English":"Sorry, I can’t today; I’m staying home.","German":"Entschuldige, heute kann ich nicht; ich bleibe zu Hause."}', '45c2c7058de27755cd25f7722089bd1c67528019d7625d89b9356ac2efb9c2af'),
  ('portuguese-a2-practical-6', 'portuguese-a2-practical-6-051-para-quando-ficam-minhas-roupas', 1, 'bright', 'Portuguese', 'pt-BR', 'German', 'Para quando ficam minhas roupas, por favor?', '{"English":"When will my clothes be ready, please?","German":"Bis wann sind meine Sachen fertig, bitte?"}', '3686b51f678bbd8494b1a4bf8158037c7ecbcd9254d76bf4cd416c113f6fda47'),
  ('portuguese-a2-practical-6', 'portuguese-a2-practical-6-052-preciso-consertar-meu-celular', 2, 'bright', 'Portuguese', 'pt-BR', 'German', 'Preciso consertar meu celular, por favor.', '{"English":"I need to repair my phone, please.","German":"Ich muss mein Handy reparieren lassen, bitte."}', 'bb70e902c65d7fd983ecf7538bc224aac1accc4b59f061043259ab13e7216d8d'),
  ('portuguese-a2-practical-6', 'portuguese-a2-practical-6-053-quero-uma-recarga-de-dez-reais', 3, 'bright', 'Portuguese', 'pt-BR', 'German', 'Quero uma recarga de dez reais, por favor.', '{"English":"I would like a top-up of ten reais, please.","German":"Ich möchte bitte eine Aufladung von zehn Reais."}', 'a33fa01d2715d56c114a1824930b8682f706ed837417164582c4c49381e395f7'),
  ('portuguese-a2-practical-6', 'portuguese-a2-practical-6-054-quero-marcar-para-quinta', 4, 'bright', 'Portuguese', 'pt-BR', 'German', 'Quero marcar para quinta de manhã.', '{"English":"I want to book for Thursday morning.","German":"Ich möchte für Donnerstagvormittag einen Termin vereinbaren."}', '217f6970761a485dbdf5ce3fd2959ef58fcf0928383da6a862139b70847aad71'),
  ('portuguese-a2-practical-6', 'portuguese-a2-practical-6-055-preciso-de-uma-copia-desta-chave', 5, 'bright', 'Portuguese', 'pt-BR', 'German', 'Preciso de uma cópia desta chave, por favor.', '{"English":"I need a copy of this key, please.","German":"Ich brauche bitte eine Kopie von diesem Schlüssel."}', 'f3dfa9e6bd23e17cff18e20720faf20856ac07370abfcbcf3f7b1503260e50e6'),
  ('portuguese-a2-practical-6', 'portuguese-a2-practical-6-056-quero-retirar-um-pacote', 6, 'bright', 'Portuguese', 'pt-BR', 'German', 'Quero retirar um pacote para mim.', '{"English":"I want to pick up a package for myself.","German":"Ich möchte ein Paket für mich abholen."}', '8f14f60e72789fd26eaebe0a8d7b0c2701b03c468f7c4b2b21b17a33de9472ae'),
  ('portuguese-a2-practical-6', 'portuguese-a2-practical-6-057-quero-alugar-uma-bicicleta', 7, 'bright', 'Portuguese', 'pt-BR', 'German', 'Quero alugar uma bicicleta por dois dias.', '{"English":"I want to rent a bicycle for two days.","German":"Ich möchte für zwei Tage ein Fahrrad mieten."}', '4052a720a36fabb2e6b14a17630f7ab7b5714437c0d70c19b410df7322f37f8a'),
  ('portuguese-a2-practical-6', 'portuguese-a2-practical-6-058-ate-que-horas-voces-ficam-abertos', 8, 'bright', 'Portuguese', 'pt-BR', 'German', 'Até que horas vocês ficam abertos?', '{"English":"Until what time are you open?","German":"Bis wie viel Uhr haben Sie geöffnet?"}', '5440ea8f5dea7cff79f4485a279fb50818b6f72f77677577d42f655265713255'),
  ('portuguese-a2-practical-6', 'portuguese-a2-practical-6-059-celular-ja-esta-pronto-para-retirar', 9, 'bright', 'Portuguese', 'pt-BR', 'German', 'O celular já está pronto para retirar?', '{"English":"Is the phone ready to pick up already?","German":"Ist das Handy schon zur Abholung bereit?"}', '75885405b3a24bb5ddd2cbf3ecafcf16a994159e21fe741b0ce9b3afe58e6ae8'),
  ('portuguese-a2-practical-6', 'portuguese-a2-practical-6-060-perfeito-ate-quinta-volto-para-buscar', 10, 'bright', 'Portuguese', 'pt-BR', 'German', 'Perfeito, até quinta. Volto para buscar.', '{"English":"Perfect, until Thursday. I’ll come back to pick it up.","German":"Perfekt, bis Donnerstag. Ich komme zum Abholen wieder."}', '165281a3ad70e60d41bc0da3fe920e4a6bc5d53c4cb2851618fb888b508f27dc'),
  ('portuguese-a2-practical-7', 'portuguese-a2-practical-7-061-o-que-voce-recomenda-para-comer-aqui', 1, 'bright', 'Portuguese', 'pt-BR', 'German', 'O que você recomenda para comer aqui?', '{"English":"What do you recommend to eat here?","German":"Was empfiehlst du hier zum Essen?"}', 'bb57124e981ec1ff456af70ed96f8af4a7ce6e1fe48aebca9fb108a0b621bb20'),
  ('portuguese-a2-practical-7', 'portuguese-a2-practical-7-062-entao-eu-quero-o-prato-do-dia-por-favor', 2, 'bright', 'Portuguese', 'pt-BR', 'German', 'Então, eu quero o prato do dia, por favor.', '{"English":"Then I would like the daily special, please.","German":"Dann nehme ich bitte das Tagesgericht."}', '041fe7f952087209f177f5436e25fb96a53aae0ee21bb3bd95749d104b6a0cf0'),
  ('portuguese-a2-practical-7', 'portuguese-a2-practical-7-063-eu-recomendo-o-bairro-antigo-para-caminhar', 3, 'bright', 'Portuguese', 'pt-BR', 'German', 'Eu recomendo o bairro antigo para caminhar.', '{"English":"I recommend the old neighborhood for walking.","German":"Ich empfehle das alte Viertel zum Spazierengehen."}', 'eb50121162fade3c87f3f3673951103cf2e3101e78ea20a5057f86e86cd1b546'),
  ('portuguese-a2-practical-7', 'portuguese-a2-practical-7-064-o-parque-e-tranquilo-e-bonito-fica-ao-lado-do-rio', 4, 'bright', 'Portuguese', 'pt-BR', 'German', 'O parque é tranquilo e bonito; fica ao lado do rio.', '{"English":"The park is quiet and beautiful; it is next to the river.","German":"Der Park ist ruhig und schön; er liegt neben dem Fluss."}', 'f2d2eb1511c01077d7b91e795909a2ae71fa8babe3df36422800fa33eda52e97'),
  ('portuguese-a2-practical-7', 'portuguese-a2-practical-7-065-o-cafe-e-pequeno-e-calmo-fica-perto-de-uma-livraria', 5, 'bright', 'Portuguese', 'pt-BR', 'German', 'O café é pequeno e calmo; fica perto de uma livraria.', '{"English":"The café is small and calm; it is near a bookstore.","German":"Das Café ist klein und ruhig; es liegt nahe bei einer Buchhandlung."}', 'fac8dc94261764e1804da4aacc2b469b5474f0c2bd56ce8528091e43d5f69050'),
  ('portuguese-a2-practical-7', 'portuguese-a2-practical-7-066-sim-procuro-um-presente-para-um-amigo-o-que-voce-recomenda', 6, 'bright', 'Portuguese', 'pt-BR', 'German', 'Sim, procuro um presente para um amigo. O que você recomenda?', '{"English":"Yes, I’m looking for a gift for a friend. What do you recommend?","German":"Ja, ich suche ein Geschenk für einen Freund. Was empfehlen Sie?"}', '4a746758b708a3547e9992d405d4dc31d3a268641390c2c7fbaa6611913e6b27'),
  ('portuguese-a2-practical-7', 'portuguese-a2-practical-7-067-o-restaurante-e-tipico-e-pequeno-fica-perto-do-hotel', 7, 'bright', 'Portuguese', 'pt-BR', 'German', 'O restaurante é típico e pequeno; fica perto do hotel.', '{"English":"The restaurant is typical and small; it is near the hotel.","German":"Das Restaurant ist typisch und klein; es liegt nahe beim Hotel."}', '5b6bfb2696ea22001553a95d3b8d9a4e4398379a24908f34f51bb43e8bf14c67'),
  ('portuguese-a2-practical-7', 'portuguese-a2-practical-7-068-eu-recomendo-a-praca-a-noite-e-bonita-e-animada', 8, 'bright', 'Portuguese', 'pt-BR', 'German', 'Eu recomendo a praça à noite: é bonita e animada.', '{"English":"I recommend the square at night: it is beautiful and lively.","German":"Ich empfehle den Platz abends: Er ist schön und lebhaft."}', '8e322d8c910fce5ab13f9af472c25216fb95e23f1ee45b410ecfe066f7f4c19d'),
  ('portuguese-a2-practical-7', 'portuguese-a2-practical-7-069-eu-recomendo-suco-de-maracuja-com-o-peixe', 9, 'bright', 'Portuguese', 'pt-BR', 'German', 'Eu recomendo suco de maracujá com o peixe.', '{"English":"I recommend passion fruit juice with the fish.","German":"Ich empfehle Maracujasaft zum Fisch."}', '6b2a08d066b71783c87321fd7a51175eb9f0fc2fd3742e7902f4815a423cb1fb'),
  ('portuguese-a2-practical-7', 'portuguese-a2-practical-7-070-agradeco-pela-dica-voce-tem-razao-e-excelente', 10, 'bright', 'Portuguese', 'pt-BR', 'German', 'Agradeço pela dica, você tem razão: é excelente.', '{"English":"Thank you for the tip, you are right: it is excellent.","German":"Danke für den Tipp, du hast recht: Es ist ausgezeichnet."}', '16777614fe1a6eb7f6749e7c7a92c1b17cb995ed24f28df2a1f91e5a4fe40d4a'),
  ('portuguese-a2-practical-8', 'portuguese-a2-practical-8-071-serio-que-bom-fico-muito-feliz-por-voce', 1, 'bright', 'Portuguese', 'pt-BR', 'German', 'Sério? Que bom! Fico muito feliz por você.', '{"English":"Really? That is great! I am very happy for you.","German":"Wirklich? Wie schön! Ich freue mich sehr für dich."}', '0707ceb5c8d042ff1a058a9ac2e78d78a482a1970198d1772279923817fcfe35'),
  ('portuguese-a2-practical-8', 'portuguese-a2-practical-8-072-esta-muito-calor-hoje-aqui-ne', 2, 'bright', 'Portuguese', 'pt-BR', 'German', 'Está muito calor hoje aqui, né?', '{"English":"It is very hot here today, right?","German":"Heute ist es hier sehr heiß, oder?"}', 'c9430c44072e7d0eb985ed06f2f61f80cdaadead23168581e402adfdd99e8827'),
  ('portuguese-a2-practical-8', 'portuguese-a2-practical-8-073-estou-com-sono-porque-dormi-pouco-ontem-a-noite', 3, 'bright', 'Portuguese', 'pt-BR', 'German', 'Estou com sono porque dormi pouco ontem à noite.', '{"English":"I am sleepy because I slept little last night.","German":"Ich bin schläfrig, weil ich gestern Nacht wenig geschlafen habe."}', '6464cfb3238bd2675f749cc43844e885afb17b6ff6ea8aa719097e8d6e5745ff'),
  ('portuguese-a2-practical-8', 'portuguese-a2-practical-8-074-tenho-muito-trabalho-nesta-semana-mas-consigo-descansar-a-noite', 4, 'bright', 'Portuguese', 'pt-BR', 'German', 'Tenho muito trabalho nesta semana, mas consigo descansar à noite.', '{"English":"I have a lot of work this week, but I manage to rest at night.","German":"Ich habe diese Woche viel Arbeit, aber ich schaffe es, mich abends auszuruhen."}', 'b3e8a38abd81f9927f2a6c4191d335123f4570d4031fa1194cd80998f7cc599f'),
  ('portuguese-a2-practical-8', 'portuguese-a2-practical-8-075-esta-chovendo-de-novo-que-pena', 5, 'bright', 'Portuguese', 'pt-BR', 'German', 'Está chovendo de novo, que pena!', '{"English":"It is raining again, what a shame!","German":"Es regnet wieder, wie schade!"}', '0d4cf4afa36effd6c51708f17c292d96d0aae9ff7a595190ed0be5908a0048c5'),
  ('portuguese-a2-practical-8', 'portuguese-a2-practical-8-076-sinto-muito-isso-e-realmente-dificil', 6, 'bright', 'Portuguese', 'pt-BR', 'German', 'Sinto muito, isso é realmente difícil.', '{"English":"I am sorry, that is really difficult.","German":"Es tut mir leid, das ist wirklich schwer."}', 'b027e9b7a45d060e0457f33d31b7b6ac9bca4909a1a6fe868e498929ee7d11e2'),
  ('portuguese-a2-practical-8', 'portuguese-a2-practical-8-077-esta-tudo-bastante-bem-e-com-voce', 7, 'bright', 'Portuguese', 'pt-BR', 'German', 'Está tudo bastante bem, e com você?', '{"English":"Everything is quite good, and you?","German":"Alles ist ziemlich gut, und bei dir?"}', '21bc1d6e716d2117e35de707231f2ea8081ee85bf8e5f54153334c40f387a7d3'),
  ('portuguese-a2-practical-8', 'portuguese-a2-practical-8-078-que-noticia-otima-estou-muito-contente-por-voce', 8, 'bright', 'Portuguese', 'pt-BR', 'German', 'Que notícia ótima! Estou muito contente por você.', '{"English":"What great news! I am very happy for you.","German":"Was für tolle Neuigkeiten! Ich freue mich sehr für dich."}', '2c5a1d22090ed6d4dea62790e52a43964f2d1b11657736c0cfaca997d2750a2b'),
  ('portuguese-a2-practical-8', 'portuguese-a2-practical-8-079-esta-bastante-frio-preciso-de-um-cafe-quente', 9, 'bright', 'Portuguese', 'pt-BR', 'German', 'Está bastante frio, preciso de um café quente.', '{"English":"It is quite cold; I need a hot coffee.","German":"Es ist ziemlich kalt, ich brauche einen heißen Kaffee."}', 'b03e9a98cf1d58132dbf68b9234343423053d94e12c83e4390ac3361bcddde3f'),
  ('portuguese-a2-practical-8', 'portuguese-a2-practical-8-080-que-dia-agradavel-ne-tudo-esta-muito-bem', 10, 'bright', 'Portuguese', 'pt-BR', 'German', 'Que dia agradável, né? Tudo está muito bem.', '{"English":"What a pleasant day, right? Everything is going very well.","German":"Was für ein angenehmer Tag, oder? Alles läuft sehr gut."}', '96e8bfdac4a92e62369b0bc046dba39c401313b923887216efc0b5e26a816c80'),
  ('portuguese-a2-practical-9', 'portuguese-a2-practical-9-081-ja-liguei-mas-o-chuveiro-nao-funciona', 1, 'bright', 'Portuguese', 'pt-BR', 'German', 'Já liguei, mas o chuveiro não funciona. Pode mandar alguém, por favor?', '{"English":"I already called, but the shower does not work. Can you send someone, please?","German":"Ich habe schon angerufen, aber die Dusche funktioniert nicht. Können Sie bitte jemanden schicken?"}', '3324e2de0c0e327fb70692667aeb792ba811673470989b94e5fcf297525f6447'),
  ('portuguese-a2-practical-9', 'portuguese-a2-practical-9-082-pedi-a-sopa-mas-ainda-nao-chegou', 2, 'bright', 'Portuguese', 'pt-BR', 'German', 'Pedi a sopa, mas ela ainda não chegou. Pode ver, por favor?', '{"English":"I ordered the soup, but it has not arrived yet. Can you check, please?","German":"Ich habe die Suppe bestellt, aber sie ist noch nicht gekommen. Können Sie bitte nachsehen?"}', 'c53145c465cbb56ca8e3b0d9883b48418b08b7778467468e0ad91c2c46c0ca69'),
  ('portuguese-a2-practical-9', 'portuguese-a2-practical-9-083-wifi-nao-esta-funcionando-liguei-antes', 3, 'bright', 'Portuguese', 'pt-BR', 'German', 'O wi-fi não está funcionando. Liguei antes; pode verificar, por favor?', '{"English":"The wi-fi is not working. I called earlier; can you check, please?","German":"Das WLAN funktioniert nicht. Ich habe vorher angerufen; können Sie bitte nachsehen?"}', 'ce0f57f5987209994b58ba220fa2d152c6a0c57f53813c8698f9cc053102e03a'),
  ('portuguese-a2-practical-9', 'portuguese-a2-practical-9-084-perdi-a-chave-nao-consigo-entrar', 4, 'bright', 'Portuguese', 'pt-BR', 'German', 'Perdi a chave e não consigo entrar. Pode ajudar, por favor?', '{"English":"I lost the key and cannot get in. Can you help, please?","German":"Ich habe den Schlüssel verloren und kann nicht hinein. Können Sie bitte helfen?"}', '63f61698f1f58faf7a065a88fcb4662e030487bb501acc701f04f2d7e64e7170'),
  ('portuguese-a2-practical-9', 'portuguese-a2-practical-9-085-taxi-ainda-nao-chegou-chamar-outro', 5, 'bright', 'Portuguese', 'pt-BR', 'German', 'O táxi ainda não chegou. Pode chamar outro, por favor?', '{"English":"The taxi has not arrived yet. Can you call another one, please?","German":"Das Taxi ist noch nicht gekommen. Können Sie bitte ein anderes Taxi rufen?"}', 'cbeb79db18e654fca2e182e6ea654a861ee76883cf4e02dd99b61b34b863fd70'),
  ('portuguese-a2-practical-9', 'portuguese-a2-practical-9-086-paguei-dez-reais-falta-troco', 6, 'bright', 'Portuguese', 'pt-BR', 'German', 'Paguei dez reais, mas falta um real no troco. Pode conferir?', '{"English":"I paid ten reais, but one real is missing from the change. Can you check?","German":"Ich habe zehn Reais bezahlt, aber ein Real fehlt im Wechselgeld. Können Sie das prüfen?"}', 'f326e35c4a07815be4c1e4cb3ba4bdd243818cc881e9edaca7a1330fe4bfd4e5'),
  ('portuguese-a2-practical-9', 'portuguese-a2-practical-9-087-comprei-celular-hoje-nao-esta-funcionando', 7, 'bright', 'Portuguese', 'pt-BR', 'German', 'Comprei este celular hoje, mas não está funcionando. Pode olhar, por favor?', '{"English":"I bought this phone today, but it is not working. Can you take a look, please?","German":"Ich habe dieses Handy heute gekauft, aber es funktioniert nicht. Können Sie bitte nachsehen?"}', '3c0914bfd603a0df86c33ea32c0a2fab5079d41d065a139582861a1b1499bc6f'),
  ('portuguese-a2-practical-9', 'portuguese-a2-practical-9-088-pedi-a-sopa-esta-fria-esquentar', 8, 'bright', 'Portuguese', 'pt-BR', 'German', 'Pedi a sopa, mas está fria. Pode esquentar, por favor?', '{"English":"I ordered the soup, but it is cold. Can you heat it, please?","German":"Ich habe die Suppe bestellt, aber sie ist kalt. Können Sie sie bitte warm machen?"}', 'b84581cb428f94387d7c8baf5a163adb75373d3be95a59bd5f210c2bc27b988c'),
  ('portuguese-a2-practical-9', 'portuguese-a2-practical-9-089-dormi-pouco-barulho-trocar-quarto', 9, 'bright', 'Portuguese', 'pt-BR', 'German', 'Dormi pouco porque tem muito barulho. Pode trocar meu quarto?', '{"English":"I slept little because there is a lot of noise. Can you change my room?","German":"Ich habe wenig geschlafen, weil es sehr laut ist. Können Sie mein Zimmer wechseln?"}', '66269578ecd948c6b987dd6e6b8de9a9a271494108d04760674917432e73db1b'),
  ('portuguese-a2-practical-9', 'portuguese-a2-practical-9-090-liguei-agora-tudo-esta-funcionando', 10, 'bright', 'Portuguese', 'pt-BR', 'German', 'Liguei antes, e agora tudo está funcionando. Obrigado pela ajuda.', '{"English":"I called earlier, and now everything is working. Thank you for the help.","German":"Ich habe vorher angerufen, und jetzt funktioniert alles. Danke für die Hilfe."}', 'af034119c81a225ad7fd8e5ba285f81b9c5a97d6d5b8edb46dae33cc73828501'),
  ('russian-a1-practical-1', 'russian-a1-practical-1-lesson-1-zdravstvuyte-english-question', 1, 'bright', 'Russian', 'ru-RU', 'German', 'Здравствуйте, вы говорите по-английски?', '{"English":"Hello, do you speak English?","German":"Guten Tag, sprechen Sie Englisch?"}', '0d35d87b7b821882c672b0f27f6985dd589126dd9c346948ec3d7ce27a331840'),
  ('russian-a1-practical-1', 'russian-a1-practical-1-lesson-2-ya-eshchyo-russian-speaking', 2, 'bright', 'Russian', 'ru-RU', 'German', 'Я ещё не говорю по-русски.', '{"English":"I do not speak Russian yet.","German":"Ich spreche noch kein Russisch."}', 'a9001769d476b8621c3f307d8a93d8e95d1cc8b94342150c48ee7ff8344957a6'),
  ('russian-a1-practical-1', 'russian-a1-practical-1-lesson-3-govorite-medlenno-slowly', 3, 'bright', 'Russian', 'ru-RU', 'German', 'Говорите медленно, пожалуйста.', '{"English":"Please speak slowly.","German":"Sprechen Sie bitte langsam."}', '90d7b4c29f51feb5afbf70956908ab89047f27890fc8eccdb888624852ba71df'),
  ('russian-a1-practical-1', 'russian-a1-practical-1-lesson-4-izvinite-ne-ponimayu-understand', 4, 'bright', 'Russian', 'ru-RU', 'German', 'Извините, я не понимаю.', '{"English":"Excuse me, I do not understand.","German":"Entschuldigen Sie, ich verstehe nicht."}', '9ac0e92c4822535924c9289c96a2cf4a29c5c021001c904b20f7d5b3aebd28aa'),
  ('russian-a1-practical-1', 'russian-a1-practical-1-lesson-5-kak-nazyvaetsya-name', 5, 'bright', 'Russian', 'ru-RU', 'German', 'Как это называется?', '{"English":"What is this called?","German":"Wie heißt das?"}', '9f039eaf4430f01017e5b384c2745fb77d0512b89858f9ab0815bea3b3939397'),
  ('russian-a1-practical-1', 'russian-a1-practical-1-lesson-6-bolshoe-spasibo-help', 6, 'bright', 'Russian', 'ru-RU', 'German', 'Большое спасибо за помощь.', '{"English":"Thank you very much for the help.","German":"Vielen Dank für die Hilfe."}', '79db162b6a94960a9de556a173b9053fa37846fe029f23c1f592f6e9e30f5f2b'),
  ('russian-a1-practical-1', 'russian-a1-practical-1-lesson-7-izvinite-mozhno-sprosit-attention', 7, 'bright', 'Russian', 'ru-RU', 'German', 'Извините, можно спросить?', '{"English":"Excuse me, may I ask something?","German":"Entschuldigen Sie, darf ich etwas fragen?"}', '8f91299c2f603022c79c979cd223a79173cbc7a7fd958230aa706b06832beff3'),
  ('russian-a1-practical-1', 'russian-a1-practical-1-lesson-8-da-moy-zakaz-confirm', 8, 'bright', 'Russian', 'ru-RU', 'German', 'Да, это мой заказ.', '{"English":"Yes, that is my order.","German":"Ja, das ist meine Bestellung."}', '55df05f9ef4efeb5a59e890f46a6453778c0a06bf48f0b49121a95d8210a55c0'),
  ('russian-a1-practical-1', 'russian-a1-practical-1-lesson-9-skazhite-gde-tualet-bathroom', 9, 'bright', 'Russian', 'ru-RU', 'German', 'Скажите, пожалуйста, где туалет?', '{"English":"Could you tell me where the bathroom is?","German":"Können Sie mir bitte sagen, wo die Toilette ist?"}', 'b77fcee8ec8c6160f63329220d11f37c517d0d439b521c50e06bbb01c5035100'),
  ('russian-a1-practical-1', 'russian-a1-practical-1-lesson-10-spasibo-do-svidaniya-goodbye', 10, 'bright', 'Russian', 'ru-RU', 'German', 'Спасибо вам, до свидания.', '{"English":"Thank you, goodbye.","German":"Danke Ihnen, auf Wiedersehen."}', '4798efd14e26ddb9f852de38198f1a43b320e6db14e904e21ebf5717c98c086a'),
  ('russian-a1-practical-10', 'russian-a1-practical-10-lesson-1-segodnya-khoroshiy-den-good-day', 1, 'bright', 'Russian', 'ru-RU', 'German', 'Сегодня хороший день.', '{"English":"Today is a good day.","German":"Heute ist ein guter Tag."}', '27aa0f5efb79a13e322dcf8ecd49686f2b39426505fa45054b23d8958431e9a7'),
  ('russian-a1-practical-10', 'russian-a1-practical-10-lesson-2-zdes-krasivoe-mesto-beautiful-place', 2, 'bright', 'Russian', 'ru-RU', 'German', 'Здесь очень красивое место.', '{"English":"This is a very beautiful place.","German":"Hier ist ein sehr schöner Ort."}', '18f055aaea30acf0637c67d01c6ca426875b96a3b91c9253a07cc6793ed629c8'),
  ('russian-a1-practical-10', 'russian-a1-practical-10-lesson-3-blagodaryu-za-vsyo-thank-everything', 3, 'bright', 'Russian', 'ru-RU', 'German', 'Благодарю вас за всё.', '{"English":"Thank you for everything.","German":"Ich danke Ihnen für alles."}', '356df9cfbed2c9ef04a40af6aa707b2d964d22a03ae8684ccf1f816b7f8a4533'),
  ('russian-a1-practical-10', 'russian-a1-practical-10-lesson-4-ponimayu-russkiy-luchshe-progress', 4, 'bright', 'Russian', 'ru-RU', 'German', 'Я всё лучше понимаю русский.', '{"English":"I understand Russian better and better.","German":"Ich verstehe Russisch immer besser."}', 'e2aa9944cd6e01210dad4d19ce1edb0ff39460278179598bc82cdc1ad771605e'),
  ('russian-a1-practical-10', 'russian-a1-practical-10-lesson-5-mne-pora-otdykhat-rest', 5, 'bright', 'Russian', 'ru-RU', 'German', 'Мне пора отдыхать.', '{"English":"It is time for me to rest.","German":"Es ist Zeit für mich, mich auszuruhen."}', '1a708b0a0172adaa192a8dbad3fcd560f9893a213a0bbe2f6e4fc88eee6635d5'),
  ('russian-a1-practical-10', 'russian-a1-practical-10-lesson-6-mne-pora-idti-leave', 6, 'bright', 'Russian', 'ru-RU', 'German', 'Мне уже пора идти.', '{"English":"It is time for me to go now.","German":"Ich muss jetzt schon gehen."}', 'ce284a60f5f24e41c7c13f12efa67281bc41e26ce36ace6d434a449b45812082'),
  ('russian-a1-practical-10', 'russian-a1-practical-10-lesson-7-nadeyus-uvidimsya-skoro-see-soon', 7, 'bright', 'Russian', 'ru-RU', 'German', 'Надеюсь, увидимся скоро.', '{"English":"I hope we see each other soon.","German":"Ich hoffe, wir sehen uns bald."}', '12b6e05299917d7492a9bcd37691925a12686586d728b5df8d5bfe7d6d8b3310'),
  ('russian-a1-practical-10', 'russian-a1-practical-10-lesson-8-zavtrashniy-vecher-podkhodit-tomorrow-works', 8, 'bright', 'Russian', 'ru-RU', 'German', 'Завтрашний вечер мне подходит.', '{"English":"Tomorrow evening works for me.","German":"Morgen Abend passt es mir."}', 'ad81ebd8e9234e9e5127ad1233a7bfed6d5b21030dba01b74bce001f0dbea33c'),
  ('russian-a1-practical-10', 'russian-a1-practical-10-lesson-9-vsem-spokoynoy-nochi-good-night', 9, 'bright', 'Russian', 'ru-RU', 'German', 'Всем спокойной ночи.', '{"English":"Good night, everyone.","German":"Gute Nacht allerseits."}', '96a4737aaaaa7ee8a8512e77d55e697dcd13f15f80d7b04bc987a843d0a654b9'),
  ('russian-a1-practical-10', 'russian-a1-practical-10-lesson-10-do-svidaniya-beregite-sebya-farewell', 10, 'bright', 'Russian', 'ru-RU', 'German', 'До свидания, берегите себя.', '{"English":"Goodbye, take care of yourself.","German":"Auf Wiedersehen, passen Sie auf sich auf."}', 'b161a0e3739ab088c7fd6af29ad4d1da1a585ef856cffe7d0effe8e5c625370f'),
  ('russian-a1-practical-2', 'russian-a1-practical-2-lesson-1-vy-mozhete-pomoch-help', 1, 'bright', 'Russian', 'ru-RU', 'German', 'Вы можете мне помочь?', '{"English":"Can you help me?","German":"Können Sie mir helfen?"}', '15e18a9ad840a153eb2751cb1aa0150e3e40d585a1d2478e745ba28314c6075c'),
  ('russian-a1-practical-2', 'russian-a1-practical-2-lesson-2-zapishite-eto-write', 2, 'bright', 'Russian', 'ru-RU', 'German', 'Запишите это, пожалуйста.', '{"English":"Please write that down.","German":"Schreiben Sie das bitte auf."}', '28e28da654d18265dfef4a39d9e1529d62851b6a74707eb409184d26f0f83594'),
  ('russian-a1-practical-2', 'russian-a1-practical-2-lesson-3-pokazhite-na-karte-map', 3, 'bright', 'Russian', 'ru-RU', 'German', 'Покажите это на карте.', '{"English":"Show me that on the map.","German":"Zeigen Sie das auf der Karte."}', 'eeef8783bd8d48eb163e937b274173d1a1481b35c229b5ca57ae9248ded0bc6c'),
  ('russian-a1-practical-2', 'russian-a1-practical-2-lesson-4-kakoy-variant-luchshe-choice', 4, 'bright', 'Russian', 'ru-RU', 'German', 'Какой вариант лучше?', '{"English":"Which option is better?","German":"Welche Variante ist besser?"}', '902eed8d31ea87051c3938131a35aad8646791a70faeb065990497f741340406'),
  ('russian-a1-practical-2', 'russian-a1-practical-2-lesson-5-eshchyo-pirozhki-more', 5, 'bright', 'Russian', 'ru-RU', 'German', 'У вас есть ещё пирожки?', '{"English":"Do you have any more pirozhki?","German":"Haben Sie noch Piroschki?"}', 'f5e67fea7713c74cd5a0cab980a51144237a6ae29eb1fe44fa4e51c94e81bd33'),
  ('russian-a1-practical-2', 'russian-a1-practical-2-lesson-6-kartoy-mozhno-oplatit-card', 6, 'bright', 'Russian', 'ru-RU', 'German', 'Картой можно оплатить?', '{"English":"Can I pay by card?","German":"Kann man mit Karte bezahlen?"}', '92c66eab79e776729098c06832db48beba0044071e24355e02bbbc1a261b4409'),
  ('russian-a1-practical-2', 'russian-a1-practical-2-lesson-7-paket-chek-please', 7, 'bright', 'Russian', 'ru-RU', 'German', 'Пакет и чек, пожалуйста.', '{"English":"A bag and the receipt, please.","German":"Eine Tüte und den Beleg, bitte."}', '8b7df975dc7603049b65c0b609023eaa2ded772982e1ede2986d610fc5d94699'),
  ('russian-a1-practical-2', 'russian-a1-practical-2-lesson-8-u-menya-bron-reservation', 8, 'bright', 'Russian', 'ru-RU', 'German', 'У меня есть бронь.', '{"English":"I have a reservation.","German":"Ich habe eine Reservierung."}', '7c4c921bffb93e290f79af15fa27a13d467ebb2019f468389603d10997990550'),
  ('russian-a1-practical-2', 'russian-a1-practical-2-lesson-9-skazhite-adres-pravilnyy-correct', 9, 'bright', 'Russian', 'ru-RU', 'German', 'Скажите, это правильный адрес?', '{"English":"Could you tell me whether this is the correct address?","German":"Können Sie mir sagen, ob das die richtige Adresse ist?"}', '71046819348083d6ac2339f75b9b9652842eedf6867717baf43f66c9f9579e20'),
  ('russian-a1-practical-2', 'russian-a1-practical-2-lesson-10-odnu-minutu-moment', 10, 'bright', 'Russian', 'ru-RU', 'German', 'Одну минуту, пожалуйста.', '{"English":"One moment, please.","German":"Eine Minute, bitte."}', 'bc9ee89c8f367dccfc50e28a776ce3ce4c59bc6fc6128bd5f6f76233c2f61a75'),
  ('russian-a1-practical-3', 'russian-a1-practical-3-lesson-1-skazhite-napravo-nalevo-direction', 1, 'bright', 'Russian', 'ru-RU', 'German', 'Скажите, направо или налево?', '{"English":"Could you tell me, right or left?","German":"Sagen Sie, nach rechts oder nach links?"}', 'd25585e4741f02d66e5382375513d5df1c71b40febd4a068d9c24172bf7b6dbd'),
