  ('russian-a2-practical-9', 'russian-a2-practical-9-086-nepravilnuyu-sdachu-dali', 6, 'bright', 'Russian', 'ru-RU', 'German', 'Вы дали мне неправильную сдачу.', '{"English":"You gave me the wrong change.","German":"Sie haben mir das falsche Wechselgeld gegeben."}', '06ecd458f2ce9abab6bef3602cbbc86cb032d5ee740226e389b5b2d4845d6f04'),
