  ('russian-a2-practical-9', 'russian-a2-practical-9-089-sosednyaya-komnata-spala', 9, 'bright', 'Russian', 'ru-RU', 'German', 'Соседняя комната очень шумная. Я почти не спала.', '{"English":"The room next door is very noisy. I barely slept.","German":"Das Nachbarzimmer ist sehr laut. Ich habe kaum geschlafen."}', '41d48fc5faa2dfcc3938004c3faa11a5e3e94956764a47f725ec1672dc591937'),
